==============================\n\t-- Looks below follow the approved character sheets (sheet build\n\t-- multipliers are converted to muscle-shell sizes: 1.0 = no extra bulk).\n\t{\n\t\tName = \"JayCuttler\", DisplayName = \"Jay Cuttler\", InspiredBy = \"Jay Cutler\",\n\t\tRarity = \"GOAT\", Price = 12e12, IncomePerSecond = 3.1e9, SpawnWeight = 65, ModelName = \"JayCuttler\",\n\t\tLook = { Skin = C(217, 165, 122), Hair = { Style = \"Spiky\", Color = C(184, 155, 122) },\n\t\t\tTop = { Style = \"Tank\", Color = C(26, 26, 26) }, Bottom = { Style = \"Shorts\", Color = C(43, 43, 43), Trim = C(245, 245, 245) },\n\t\t\tSocks = { Color = C(245, 245, 245), Height = 0.55 }, Shoes = C(255, 255, 255), ShoeStyle = \"HighTop\",\n\t\t\t-- sheet: Height 1.05, Shoulders 1.4, Arms 1.35, Legs 1.25\n\t\t\tBuild = { Height = 1.05, Width = 1.35, Depth = 1.3, Shoulders = 1.05, Chest = 0.8, Arms = 0.9, Traps = 0.5, Legs = 0.8 } },\n\t\tSpawnFx = \"GoldSpotlight\", Poses = { \"DoubleBiceps\", \"SideChest\", \"CrossedArms\", \"LatSpread\" },\n\t},\n\t{\n\t\tName = \"RonnieCurlman\", DisplayName = \"Ronnie Curlman\", InspiredBy = \"Ronnie Coleman\",\n\t\tRarity = \"GOAT\", Price = 20e12, IncomePerSecond = 3.35e9, SpawnWeight = 27, ModelName = \"RonnieCurlman\",\n\t\t-- Uploaded rigged model: paste its Roblox asset ID here (used first).\n\t\tAssetId = nil,\n\t\tModelYaw = 0, -- degrees; set to 180 if a placed model rides the belt backwards\n\t\tMesh = \"RonnieCurlman\", -- baked Meshy model (MeshAssets/RonnieCurlman), used if no AssetId\n\t\tLook = { Skin = C(107, 63, 42), Hair = { Style = \"Bald\", Color = HAIR.Black },\n\t\t\tTop = { Style = \"Tank\", Color = C(26, 26, 26) }, Bottom = { Style = \"Shorts\", Color = C(31, 31, 31) },\n\t\t\tShoes = C(17, 17, 17), ShoeStyle = \"Boots\",\n\t\t\tGear = { \"LiftingBelt\", \"KneeSleeves\" }, SleeveBand = C(178, 34, 34),\n\t\t\tProps = { \"WristWraps\" }, WrapColor = C(26, 26, 26),\n\t\t\t-- sheet: Height 1.1, Shoulders 1.5, Arms 1.5, Legs 1.4 (largest in the game)\n\t\t\tBuild = { Height = 1.1, Width = 1.5, Depth = 1.45, Shoulders = 1.3, Arms = 1.3, Chest = 1.0, Traps = 1.0, Legs = 1.28 } },\n\t\tSpawnFx = \"HeavyLanding\", Poses = { \"DoubleBiceps\", \"MostMuscular\", \"SideChest\" }, Tags = { \"Biggest\" },\n\t},\n\t{\n\t\tName = \"ArnieIronberg\", DisplayName = \"Arnie Ironberg\", InspiredBy = \"Arnold Schwarzenegger\",\n\t\tRarity = \"GOAT\", Price = 35e12, IncomePerSecond = 3.5e9, SpawnWeight = 8, ModelName = \"ArnieIronberg\",\n\t\tLook = { Skin = C(210, 161, 121), Hair = { Style = \"SweptBack\", Color = C(59, 43, 32) },\n\t\t\tTop = { Style = \"Tank\", Color = C(178, 34, 34) }, Bottom = { Style = \"Shorts\", Color = C(31, 31, 31) },\n\t\t\tSocks = { Color = C(245, 245, 245), Height = 0.5, Stripes = { C(178, 34, 34), C(178, 34, 34) } },\n\t\t\tShoes = C(255, 255, 255),\n\t\t\t-- sheet: Height 1.1, Shoulders 1.45, Arms 1.4, Legs 1.3\n\t\t\tBuild = { Height = 1.1, Width = 1.4, Depth = 1.3, Shoulders = 1.17, Arms = 1.04, Chest = 1.2, Traps = 0.6, Legs = 0.96 } },\n\t\tSpawnFx = \"GoldenEra\", Poses = { \"DoubleBiceps\", \"SideChest\", \"Point\" }, Tags = { \"Rarest\", \"Prestige\" },\n\t},\n}\n\n-- ----------------------------------------------------------------------\n-- Lookups & helpers\n-- ----------------------------------------------------------------------\nCharacters.BY_NAME = {}\nCharacters.RARITY_BY_ID = {}\nCharacters.RARITY_INDEX = {}\nCharacters.BY_RARITY = {}\n\nfor i, r in ipairs(Characters.RARITIES) do\n\tCharacters.RARITY_BY_ID[r.Id] = r\n\tCharacters.RARITY_INDEX[r.Id] = i\n\tr.Index = i\n\tCharacters.BY_RARITY[r.Id] = {}\nend\nfor _, c in ipairs(Characters.LIST) do\n\tassert(Characters.RARITY_BY_ID[c.Rarity], \"Unknown rarity \" .. tostring(c.Rarity) .. \" for \" .. c.Name)\n\tassert(not Characters.BY_NAME[c.Name], \"Duplicate character \" .. c.Name)\n\tCharacters.BY_NAME[c.Name] = c\n\ttable.insert(Characters.BY_RARITY[c.Rarity], c)\nend\n\nfunction Characters.Get(name)\n\treturn Characters.BY_NAME[name]\nend\n\nfunction Characters.GetRarity(rarityId)\n\treturn Characters.RARITY_BY_ID[rarityId]\nend\n\nfunction Characters.RarityIndex(rarityId)\n\treturn Characters.RARITY_INDEX[rarityId] or 1\nend\n\n-- Income for an owned character (mutation-aware).\nfunction Characters.GetIncome(name, mutation)\n\tlocal c = Characters.BY_NAME[name]\n\tif not c then\n\t\treturn 0\n\tend\n\tlocal m = Characters.MUTATIONS[mutation or \"None\"] or Characters.MUTATIONS.None\n\treturn c.IncomePerSecond * m.Multiplier\nend\n\nlocal function weightedPick(list, weightOf, rng)\n\tlocal total = 0\n\tfor _, item in ipairs(list) do\n\t\ttotal += weightOf(item)\n\tend\n\tlocal roll = (rng and rng:NextNumber(0, total)) or (math.random() * total)\n\tlocal acc = 0\n\tfor _, item in ipairs(list) do\n\t\tacc += weightOf(item)\n\t\tif roll <= acc then\n\t\t\treturn item\n\t\tend\n\tend\n\treturn list[#list]\nend\n\n-- Roll the next conveyor character: rarity by Odds, then character by SpawnWeight.\nfunction Characters.Roll(rng)\n\tif Characters.PREVIEW and #Characters.PREVIEW > 0 then\n\t\tpreviewIndex = previewIndex % #Characters.PREVIEW + 1\n\t\tlocal c = Characters.BY_NAME[Characters.PREVIEW[previewIndex]]\n\t\tif c then\n\t\t\treturn c\n\t\tend\n\tend\n\tlocal candidates = {}\n\tfor _, r in ipairs(Characters.RARITIES) do\n\t\tif #Characters.Eligible(r.Id) > 0 then\n\t\t\ttable.insert(candidates, r)\n\t\tend\n\tend\n\tif #candidates == 0 then\n\t\treturn nil\n\tend\n\tlocal rarity = weightedPick(candidates, function(r)\n\t\treturn r.Odds\n\tend, rng)\n\treturn weightedPick(Characters.Eligible(rarity.Id), function(c)\n\t\treturn c.SpawnWeight\n\tend, rng)\nend\n\n-- Characters of a rarity that are allowed to spawn right now.\nfunction Characters.Eligible(rarityId)\n\tlocal list = Characters.BY_RARITY[rarityId] or {}\n\tif not (Characters.ONLY_WITH_MODELS and Characters.Filter) then\n\t\treturn list\n\tend\n\tlocal out = {}\n\tfor _, c in ipairs(list) do\n\t\tif Characters.Filter(c) then\n\t\t\ttable.insert(out, c)\n\t\tend\n\tend\n\treturn out\nend\n\n-- A character of exactly this rarity (guaranteed drops), or nil if none can spawn.\nfunction Characters.RollOfRarity(rarityId, rng)\n\tlocal pool = Characters.Eligible(rarityId)\n\tif Characters.PREVIEW and #Characters.PREVIEW > 0 then\n\t\tpool = {}\n\t\tfor _, name in ipairs(Characters.PREVIEW) do\n\t\t\tlocal c = Characters.BY_NAME[name]\n\t\t\tif c and c.Rarity == rarityId then\n\t\t\t\ttable.insert(pool, c)\n\t\t\tend\n\t\tend\n\tend\n\tif #pool == 0 then\n\t\treturn nil\n\tend\n\treturn weightedPick(pool, function(c)\n\t\treturn c.SpawnWeight\n\tend, rng)\nend\n\n-- Effective chance (0..1) of a character per conveyor spawn (for UI / balancing).\nfunction Characters.EffectiveOdds(name)\n\tlocal c = Characters.BY_NAME[name]\n\tif not c then\n\t\treturn 0\n\tend\n\tlocal r = Characters.RARITY_BY_ID[c.Rarity]\n\tlocal total = 0\n\tfor _, other in ipairs(Characters.BY_RARITY[c.Rarity]) do\n\t\ttotal += other.SpawnWeight\n\tend\n\treturn (r.Odds / 100) * (c.SpawnWeight / total)\nend\n\n-- For old saves: pick a stand-in character for a legacy rarity index.\nfunction Characters.DefaultForRarityIndex(index)\n\tlocal r = Characters.RARITIES[math.clamp(index or 1, 1, #Characters.RARITIES)]\n\treturn Characters.BY_RARITY[r.Id][1]\nend\n\nreturn Characters\n"},{"ReplicatedStorage/Modules/Constants","ModuleScript","--[[\n\tGYM WARS — Constants\n\tEvery tunable number and catalog in the game lives here.\n\tChange values in this file to rebalance without touching game logic.\n]]\n\nlocal Constants = {}\n\n-- ======================================================================\n-- SAVE DATA\n-- ======================================================================\nConstants.DATASTORE_NAME = \"GymWars_v1\"\nConstants.AUTOSAVE_INTERVAL = 60 -- seconds\n\n-- ======================================================================\n-- MAP  (compact linear map: 4 gyms on each side of a red-carpet conveyor)\n-- ======================================================================\nConstants.PLOT_COUNT = 8\nConstants.FLOOR_COUNT = 3 -- every gym grows up to 3 stories\nConstants.RACK_SLOT_MAX = 33 -- machines per gym (3 of each): 12 + 12 + 9 across the 3 floors\n\n-- ======================================================================\n-- SHARED CONVEYOR (runs down the middle of the map along +Z)\n-- Start/end points come from the BeltStart / BeltEnd parts in the map.\n-- ======================================================================\nConstants.BELT = {\n\tSpawnInterval = 3.5, -- seconds between characters walking out of the tunnel\n\tMaxOnBelt = 20, -- cap on how many walk the carpet at once\n\tWalkSpeed = 7, -- studs per second down the carpet (a steady strut)\n\tGuaranteeLegendary = 300, -- seconds: a Legendary is guaranteed this often\n\tGuaranteeMythic = 900, -- seconds: a Mythic is guaranteed this often\n\tSpeed = 6, -- legacy (old conveyor speed)\n\tClaimDistance = 11, -- ProximityPrompt activation range\n\tClaimHold = 0.3, -- seconds to hold the prompt\n\tDroppedDespawn = 60, -- seconds a dropped, unowned influencer waits before leaving\n}\n\n-- ======================================================================\n-- INFLUENCER NPCs (real R15 characters)\n-- ======================================================================\nConstants.NPC = {\n\tTravelSpeed = 16, -- once claimed they walk on their own straight to their machine\n\tFollowSpeed = 16, -- (legacy follow mode, unused by default)\n\tFollowGap = 5,\n\tSeatSpeed = 12,\n\tReturnSpeed = 16, -- walking back to their gym after the front desk saves them\n\tTeleportIfFartherThan = 160,\n\tSeatTimeout = 45, -- seconds before a stuck influencer just hops onto the machine\n\tEmoteChance = 0.12, -- per second, while riding the belt\n}\n\n-- Optional: make an influencer wear a real Roblox avatar.\n-- [Influencer name] = Roblox UserId (their avatar is loaded at spawn).\nConstants.INFLUENCER_AVATARS = {\n\t-- [\"Joey Swool\"] = 123456789,\n}\n\nConstants.SKIN_TONES = {\n\tColor3.fromRGB(255, 219, 172),\n\tColor3.fromRGB(241, 194, 125),\n\tColor3.fromRGB(224, 172, 105),\n\tColor3.fromRGB(198, 134, 66),\n\tColor3.fromRGB(141, 85, 36),\n\tColor3.fromRGB(95, 58, 30),\n}\n\n-- ======================================================================\n-- CHARACTERS: every collectible (price, income, rarity, odds, look) lives in\n-- ReplicatedStorage.Modules.Characters. Nothing character-related is here.\n-- ======================================================================\nConstants.STARTING_CASH = 100 -- enough to buy your first Common off the conveyor\n\n-- ======================================================================\n-- WORKOUT (personal Strength — permanent, never reset)\n-- ======================================================================\nConstants.WORKOUT = {\n\tBaseGain = 1, -- strength per rep, multiplied by the WorkoutGain equipment value\n\tRepCooldown = 0.6, -- seconds between reps (divided by workout-speed boosters)\n\tPromptDistance = 8,\n}\n\n-- ======================================================================\n-- CLOTHING  (Strength gates the RIGHT TO BUY. Cash is still required.)\n-- Bonus is added to the income multiplier: total = 1 + sum(equipped bonuses)\n-- ======================================================================\nConstants.CLOTHING_SLOTS = { \"Top\", \"Bottom\", \"Accessory\" }\n\nConstants.CLOTHING = {\n\t-- Top\n\t{ Id = \"GrayTee\", Name = \"Gray Tee\", Slot = \"Top\", Strength = 0, Price = 100, Bonus = 0.10 },\n\t{ Id = \"TankTop\", Name = \"Tank Top\", Slot = \"Top\", Strength = 50, Price = 500, Bonus = 0.25 },\n\t{ Id = \"Stringer\", Name = \"Stringer\", Slot = \"Top\", Strength = 200, Price = 2500, Bonus = 0.50 },\n\t{ Id = \"PumpCover\", Name = \"Pump Cover\", Slot = \"Top\", Strength = 600, Price = 10000, Bonus = 1.00 },\n\t-- Bottom\n\t{ Id = \"GymShorts\", Name = \"Gym Shorts\", Slot = \"Bottom\", Strength = 25, Price = 300, Bonus = 0.15 },\n\t{ Id = \"Joggers\", Name = \"Joggers\", Slot = \"Bottom\", Strength = 150, Price = 2000, Bonus = 0.40 },\n\t{ Id = \"Tights\", Name = \"Compression Tights\", Slot = \"Bottom\", Strength = 500, Price = 8000, Bonus = 0.80 },\n\t-- Accessory\n\t{ Id = \"WristWraps\", Name = \"Wrist Wraps\", Slot = \"Accessory\", Strength = 75, Price = 800, Bonus = 0.20 },\n\t{ Id = \"LiftingBelt\", Name = \"Lifting Belt\", Slot = \"Accessory\", Strength = 300, Price = 4000, Bonus = 0.60 },\n\t{ Id = \"GoldChain\", Name = \"Gold Chain\", Slot = \"Accessory\", Strength = 1000, Price = 25000, Bonus = 1.50 },\n}\n\n-- ======================================================================\n-- EQUIPMENT  (permanent gym upgrades, Cash only, survive rebirth)\n-- Level 1 is the starting level. Costs[n] is the price to go from level n-1 to n.\n-- ======================================================================\nConstants.EQUIPMENT_ORDER = { \"Floors\", \"WorkoutGain\", \"DeskSpeed\" }\n\nConstants.EQUIPMENT = {\n\tFloors = {\n\t\tName = \"Gym Floors\",\n\t\tDesc = \"Build another story on your gym (more machines)\",\n\t\tValues = { 12, 24, 33 }, -- machines available (floor 1, floors 1-2, floors 1-3)\n\t\tCosts = { 0, 7500, 45000 },\n\t\tUnit = \" machines\",\n\t},\n\tWorkoutGain = {\n\t\tName = \"Heavier Weights\",\n\t\tDesc = \"Strength gained per rep\",\n\t\tValues = { 1, 2, 4, 8, 16 },\n\t\tCosts = { 0, 800, 3000, 12000, 40000 },\n\t\tUnit = \"x per rep\",\n\t},\n\tDeskSpeed = {\n\t\tName = \"Front Desk Speed\",\n\t\tDesc = \"How fast your front desk worker chases stolen influencers\",\n\t\tValues = { 18, 21, 24, 28, 34 },\n\t\tCosts = { 0, 1000, 4000, 15000, 50000 },\n\t\tUnit = \" speed\",\n\t},\n}\n\n-- ======================================================================\n-- BOOSTERS  (temporary, Cash-purchased consumables)\n-- Effect = \"Income\" multiplies Cash income; \"WorkoutSpeed\" multiplies rep speed.\n-- Buying the same booster again while active refreshes its timer.\n-- ======================================================================\nConstants.BOOSTERS = {\n\t{ Id = \"ProteinShake\", Name = \"Protein Shake\", Price = 250, Effect = \"Income\", Multiplier = 1.5, Duration = 300, Desc = \"x1.5 Cash for 5 min\" },\n\t{ Id = \"Creatine\", Name = \"Creatine\", Price = 600, Effect = \"WorkoutSpeed\", Multiplier = 2, Duration = 600, Desc = \"2x workout speed for 10 min\" },\n\t{ Id = \"Steroids\", Name = \"Steroids\", Price = 2000, Effect = \"Income\", Multiplier = 3, Duration = 300, Desc = \"x3 Cash for 5 min\" },\n}\n\n-- ======================================================================\n-- REBIRTH\n-- threshold(n)  = BaseThreshold * ThresholdGrowth ^ n\n-- multiplier(n) = 1 + MaxBonus * (1 - Curve ^ n)   -> tapers toward 1 + MaxBonus\n-- ======================================================================\nConstants.REBIRTH = {\n\tBaseThreshold = 10000,\n\tThresholdGrowth = 2.0,\n\tMaxBonus = 9, -- soft cap of 10x total\n\tCurve = 0.93,\n}\n\n-- ======================================================================\n-- DEFENSE (Front Desk Worker)\n-- ======================================================================\nConstants.DEFENSE = {\n\tCatchRadius = 4.5,\n\tStunSeconds = 2,\n\tReturnHomeSpeed = 12,\n}\n\n-- ======================================================================\n-- MOVEMENT\n-- ======================================================================\nConstants.NORMAL_WALKSPEED = 36 -- 2x the Roblox default feel for this map\nConstants.CARRY_WALKSPEED = 36\n\n-- ======================================================================\n-- GYM COLOR PRESETS (owner-selectable, cosmetic only). Saved as preset index.\n-- ======================================================================\nConstants.GYM_COLORS = {\n\t{ Name = \"Slate\", Wall = Color3.fromRGB(52, 58, 70), Accent = Color3.fromRGB(200, 205, 215) },\n\t{ Name = \"Crimson\", Wall = Color3.fromRGB(60, 24, 28), Accent = Color3.fromRGB(226, 81, 90) },\n\t{ Name = \"Ice\", Wall = Color3.fromRGB(22, 36, 52), Accent = Color3.fromRGB(79, 157, 251) },\n\t{ Name = \"Void\", Wall = Color3.fromRGB(36, 24, 50), Accent = Color3.fromRGB(176, 107, 240) },\n\t{ Name = \"Teal\", Wall = Color3.fromRGB(18, 48, 44), Accent = Color3.fromRGB(47, 207, 180) },\n\t{ Name = \"Furnace\", Wall = Color3.fromRGB(56, 32, 12), Accent = Color3.fromRGB(240, 152, 60) },\n\t{ Name = \"Glow\", Wall = Color3.fromRGB(56, 22, 42), Accent = Color3.fromRGB(240, 107, 176) },\n\t{ Name = \"Gold\", Wall = Color3.fromRGB(50, 42, 14), Accent = Color3.fromRGB(244, 201, 58) },\n}\n\n-- ======================================================================\n-- HELPERS\n-- ======================================================================\nfunction Constants.RebirthThreshold(rebirths)\n\treturn math.floor(Constants.REBIRTH.BaseThreshold * (Constants.REBIRTH.ThresholdGrowth ^ rebirths))\nend\n\nfunction Constants.RebirthMultiplier(rebirths)\n\treturn 1 + Constants.REBIRTH.MaxBonus * (1 - (Constants.REBIRTH.Curve ^ rebirths))\nend\n\nfunction Constants.GetClothing(id)\n\tfor _, item in ipairs(Constants.CLOTHING) do\n\t\tif item.Id == id then\n\t\t\treturn item\n\t\tend\n\tend\n\treturn nil\nend\n\nfunction Constants.GetBooster(id)\n\tfor _, item in ipairs(Constants.BOOSTERS) do\n\t\tif item.Id == id then\n\t\t\treturn item\n\t\tend\n\tend\n\treturn nil\nend\n\n-- Short money/number format: 950, 1.4K, 7.5M, 3.5B, 12T, 4.2Qa ... (works far past trillions)\nlocal SUFFIXES = { \"\", \"K\", \"M\", \"B\", \"T\", \"Qa\", \"Qi\", \"Sx\", \"Sp\", \"Oc\", \"No\", \"Dc\", \"Ud\", \"Dd\", \"Td\", \"Qad\", \"Qid\" }\nfunction Constants.FormatNumber(n)\n\tn = tonumber(n) or 0\n\tif n ~= n then\n\t\treturn \"0\"\n\tend\n\tlocal sign = n < 0 and \"-\" or \"\"\n\tn = math.abs(n)\n\tif n < 1000 then\n\t\tif n == math.floor(n) or n >= 100 then\n\t\t\treturn sign .. tostring(math.floor(n))\n\t\tend\n\t\treturn sign .. (string.format(\"%.1f\", n):gsub(\"%.0$\", \"\"))\n\tend\n\tlocal tier = math.min(math.floor(math.log10(n) / 3), #SUFFIXES - 1)\n\tlocal scaled = n / 10 ^ (tier * 3)\n\tif scaled >= 999.995 and tier < #SUFFIXES - 1 then\n\t\ttier += 1\n\t\tscaled = n / 10 ^ (tier * 3)\n\tend\n\tlocal text\n\tif scaled >= 100 then\n\t\ttext = string.format(\"%.0f\", scaled)\n\telseif scaled >= 10 then\n\t\ttext = string.format(\"%.1f\", scaled)\n\telse\n\t\ttext = string.format(\"%.2f\", scaled)\n\tend\n\ttext = text:gsub(\"(%..-)0+$\", \"%1\"):gsub(\"%.$\", \"\")\n\treturn sign .. text .. SUFFIXES[tier + 1]\nend\n\nreturn Constants\n"},{"ReplicatedStorage/Modules/MeshCharacter","ModuleScript","--[[\n\tMeshCharacter\n\tCharacters made from a Meshy (or any static textured) model, baked by\n\ttools/meshy/import.py into ReplicatedStorage.MeshAssets.<Name>:\n\n\t  Mesh.luau   rig (parts + joints at the model's real shoulders/elbows/...),\n\t              the mesh cut into the 15 R15 body parts, texture layout\n\t  Tex*.luau   base color texture, base64 RGB (4 chars = 1 pixel)\n\n\tServer: BuildRig(data) -> an invisible R15 rig that walks, paths and does\n\tevery workout like any other influencer.\n\tClient: Attach(model) builds the textured body-part meshes with\n\tEditableMesh / EditableImage and welds each one to its rig part.\n\n\tPublished games: EditableMesh/EditableImage need the owner to be ID\n\tverified with \"Enable Mesh / Image APIs\" on (Creator Dashboard). Studio\n\tplay-tests always work. If creation fails, the rig parts are shown instead.\n]]\n\nlocal AssetService = game:GetService(\"AssetService\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\n\nlocal MeshCharacter = {}\n\nlocal function assets()\n\treturn RS:FindFirstChild(\"MeshAssets\")\nend\n\nfunction MeshCharacter.Get(name)\n\tlocal folder = assets() and assets():FindFirstChild(name)\n\tlocal mod = folder and folder:FindFirstChild(\"Mesh\")\n\tif not mod then\n\t\treturn nil\n\tend\n\tlocal ok, data = pcall(require, mod)\n\treturn ok and data or nil\nend\n\nlocal function v3(t)\n\treturn Vector3.new(t[1], t[2], t[3])\nend\n\n-- ----------------------------------------------------------------------\n-- Rig (server)\n-- ----------------------------------------------------------------------\nfunction MeshCharacter.BuildRig(data)\n\tlocal model = Instance.new(\"Model\")\n\tmodel.Name = data.Name\n\tlocal parts = {}\n\tfor name, def in pairs(data.Parts) do\n\t\tlocal p = Instance.new(\"Part\")\n\t\tp.Name = name\n\t\tp.Size = v3(def.Size)\n\t\tp.CFrame = CFrame.new(v3(def.Center))\n\t\tp.Transparency = 1\n\t\tp.CanCollide = false\n\t\tp.CanQuery = false\n\t\tp.CastShadow = false\n\t\tp.Material = Enum.Material.SmoothPlastic\n\t\tp.Color = Color3.fromRGB(90, 60, 45)\n\t\tp.TopSurface = Enum.SurfaceType.Smooth\n\t\tp.BottomSurface = Enum.SurfaceType.Smooth\n\t\tp.Parent = model\n\t\tparts[name] = p\n\tend\n\tfor _, j in ipairs(data.Joints) do\n\t\tlocal name, p1, p0, pivot = j[1], parts[j[2]], parts[j[3]], v3(j[4])\n\t\tlocal m = Instance.new(\"Motor6D\")\n\t\tm.Name = name\n\t\tm.Part0 = p0\n\t\tm.Part1 = p1\n\t\tm.C0 = CFrame.new(pivot - p0.CFrame.Position)\n\t\tm.C1 = CFrame.new(pivot - p1.CFrame.Position)\n\t\tm.Parent = p1\n\tend\n\tlocal hum = Instance.new(\"Humanoid\")\n\thum.RigType = Enum.HumanoidRigType.R15\n\thum.HipHeight = data.HipHeight\n\thum.Parent = model\n\tInstance.new(\"Animator\").Parent = hum\n\tmodel.PrimaryPart = parts.HumanoidRootPart\n\tmodel:SetAttribute(\"MeshCharacter\", data.Name)\n\treturn model\nend\n\n-- ----------------------------------------------------------------------\n-- Visuals (client)\n-- ----------------------------------------------------------------------\nlocal B64 = {}\ndo\n\tlocal alphabet = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"\n\tfor i = 1, #alphabet do\n\t\tB64[string.byte(alphabet, i)] = i - 1\n\tend\nend\n\nlocal textures = {} -- [name] = EditableImage | false (failed) | \"loading\"\nlocal meshes = {} -- [name] = { [partName] = EditableMesh } | false\n\nlocal function buildTexture(data)\n\tlocal folder = assets():FindFirstChild(data.Name)\n\tlocal tex = data.Texture\n\tlocal w, h = tex.Width, tex.Height\n\tlocal img = AssetService:CreateEditableImage({ Size = Vector2.new(w, h) })\n\tif not img then\n\t\treturn nil\n\tend\n\tlocal buf = buffer.create(w * h * 4)\n\tlocal pixel = 0\n\tfor _, modName in ipairs(tex.Modules) do\n\t\tlocal s = require(folder:WaitForChild(modName))\n\t\tlocal n = #s // 4\n\t\tfor i = 0, n - 1 do\n\t\t\tlocal a, b, c, d = string.byte(s, i * 4 + 1, i * 4 + 4)\n\t\t\tlocal v = B64[a] * 262144 + B64[b] * 4096 + B64[c] * 64 + B64[d]\n\t\t\tlocal r, g, bl = v // 65536, (v // 256) % 256, v % 256\n\t\t\tbuffer.writeu32(buf, (pixel + i) * 4, r + g * 256 + bl * 65536 + 4278190080)\n\t\t\tif i % 65536 == 65535 then\n\t\t\t\ttask.wait() -- spread decoding over a few frames\n\t\t\tend\n\t\tend\n\t\tpixel += n\n\tend\n\timg:WritePixelsBuffer(Vector2.zero, Vector2.new(w, h), buf)\n\treturn img\nend\n\nlocal function buildMesh(chunk)\n\tlocal em = AssetService:CreateEditableMesh()\n\tif not em then\n\t\treturn nil\n\tend\n\tlocal P, T, N, F = chunk.P, chunk.T, chunk.N, chunk.F\n\tlocal vids, tids, nids = {}, {}, {}\n\tfor i = 1, #P, 3 do\n\t\tvids[#vids + 1] = em:AddVertex(Vector3.new(P[i], P[i + 1], P[i + 2]))\n\tend\n\tfor i = 1, #T, 2 do\n\t\ttids[#tids + 1] = em:AddUV(Vector2.new(T[i], T[i + 1]))\n\tend\n\tfor i = 1, #N, 3 do\n\t\tnids[#nids + 1] = em:AddNormal(Vector3.new(N[i], N[i + 1], N[i + 2]))\n\tend\n\tfor i = 1, #F, 9 do\n\t\tlocal fid = em:AddTriangle(vids[F[i]], vids[F[i + 1]], vids[F[i + 2]])\n\t\tem:SetFaceUVs(fid, { tids[F[i + 3]], tids[F[i + 4]], tids[F[i + 5]] })\n\t\tem:SetFaceNormals(fid, { nids[F[i + 6]], nids[F[i + 7]], nids[F[i + 8]] })\n\tend\n\treturn em\nend\n\nlocal function ensureAssets(data)\n\tlocal name = data.Name\n\twhile textures[name] == \"loading\" do\n\t\ttask.wait()\n\tend\n\tif textures[name] == nil then\n\t\ttextures[name] = \"loading\"\n\t\tlocal ok, img = pcall(buildTexture, data)\n\t\tlocal okM, set = pcall(function()\n\t\t\tlocal out = {}\n\t\t\tfor partName, chunk in pairs(data.Chunks) do\n\t\t\t\tlocal em = buildMesh(chunk)\n\t\t\t\tif not em then\n\t\t\t\t\treturn nil\n\t\t\t\tend\n\t\t\t\tout[partName] = em\n\t\t\tend\n\t\t\treturn out\n\t\tend)\n\t\tif not ok or not img then\n\t\t\twarn(\"[MeshCharacter] texture failed for \" .. name .. \": \" .. tostring(img))\n\t\tend\n\t\tif not okM or not set then\n\t\t\twarn(\"[MeshCharacter] mesh failed for \" .. name .. \": \" .. tostring(set))\n\t\tend\n\t\ttextures[name] = (ok and img) or false\n\t\tmeshes[name] = (okM and set) or false\n\tend\n\treturn textures[name], meshes[name]\nend\n\nlocal function showRig(model)\n\tfor _, p in ipairs(model:GetChildren()) do\n\t\tif p:IsA(\"BasePart\") and p.Name ~= \"HumanoidRootPart\" then\n\t\t\tp.Transparency = 0 -- local only: fallback so the character never goes invisible\n\t\tend\n\tend\nend\n\nfunction MeshCharacter.Attach(model)\n\tlocal name = model:GetAttribute(\"MeshCharacter\")\n\tif not name or model:GetAttribute(\"MeshAttached\") then\n\t\treturn\n\tend\n\tmodel:SetAttribute(\"MeshAttached\", true) -- local attribute: once per client\n\tlocal data = MeshCharacter.Get(name)\n\tif not data then\n\t\tshowRig(model)\n\t\treturn\n\tend\n\tlocal img, set = ensureAssets(data)\n\tif not set then\n\t\tshowRig(model)\n\t\treturn\n\tend\n\tlocal folder = Instance.new(\"Folder\")\n\tfolder.Name = \"MeshVisual\"\n\tfor partName in pairs(data.Chunks) do\n\t\tlocal limb = model:WaitForChild(partName, 10)\n\t\tlocal em = set[partName]\n\t\tif not (limb and limb:IsA(\"BasePart\") and em) then\n\t\t\tcontinue\n\t\tend\n\t\tlocal ok, mp = pcall(function()\n\t\t\treturn AssetService:CreateMeshPartAsync(Content.fromObject(em), {\n\t\t\t\tCollisionFidelity = Enum.CollisionFidelity.Box,\n\t\t\t\tRenderFidelity = Enum.RenderFidelity.Precise,\n\t\t\t})\n\t\tend)\n\t\tif not ok or not mp then\n\t\t\twarn(\"[MeshCharacter] CreateMeshPartAsync failed: \" .. tostring(mp))\n\t\t\tshowRig(model)\n\t\t\tfolder:Destroy()\n\t\t\treturn\n\t\tend\n\t\tif not model.Parent then\n\t\t\tfolder:Destroy()\n\t\t\treturn\n\t\tend\n\t\tmp.Name = partName\n\t\tmp.Anchored = false\n\t\tmp.CanCollide = false\n\t\tmp.CanQuery = false\n\t\tmp.CanTouch = false\n\t\tmp.Massless = true\n\t\tmp.Material = Enum.Material.SmoothPlastic\n\t\t-- body parts are open shells cut from one skin: render the inside too\n\t\t-- so bending joints never show a see-through hole\n\t\tmp.DoubleSided = true\n\t\tmp.Color = Color3.new(1, 1, 1)\n\t\tif img then\n\t\t\tmp.TextureContent = Content.fromObject(img)\n\t\tend\n\t\t-- each chunk was baked centered on its part, so it simply takes the\n\t\t-- part's frame and (scaled) size\n\t\tmp.Size = limb.Size\n\t\tmp.CFrame = limb.CFrame\n\t\tlocal weld = Instance.new(\"WeldConstraint\")\n\t\tweld.Part0 = limb\n\t\tweld.Part1 = mp\n\t\tweld.Parent = mp\n\t\tmp.Parent = folder\n\tend\n\tfolder.Parent = model\nend\n\nreturn MeshCharacter\n"},{"ReplicatedStorage/Modules/Gym/Poses","ModuleScript","--[[\n\tPoses\n\tBodybuilding poses struck on the conveyor. Pure IK targets relative to the\n\trig, shared by the client animator and the offline pose renderer.\n\n\t  Poses.Apply(rig, name)   -- call after rig:reset() / setRootCFrame\n\t  Poses.JOINTS             -- joints a pose writes (blend these)\n]]\n\nlocal Poses = {}\n\nPoses.JOINTS = { \"LeftShoulder\", \"LeftElbow\", \"LeftWrist\", \"RightShoulder\", \"RightElbow\", \"RightWrist\", \"Waist\", \"Neck\" }\n\nlocal WAIST = {\n\tMostMuscular = { -14, 0 },\n\tVacuum = { 5, 0 },\n\tLatSpread = { 3, 0 },\n\tCrossedArms = { 2, 0 },\n\tSideChest = { -4, -22 },\n\tPoint = { 4, 12 },\n}\n\nlocal NECK = {\n\tMostMuscular = { 10, 0 },\n\tSideChest = { 0, 26 },\n\tPoint = { -6, 10 },\n}\n\nfunction Poses.Apply(rig, name)\n\tlocal w = WAIST[name]\n\tif w then\n\t\trig:set(\"Waist\", CFrame.Angles(math.rad(w[1]), math.rad(w[2]), 0))\n\tend\n\tlocal d = rig.Dims\n\tlocal k = d.Scale\n\tlocal ut = rig:world(\"UpperTorso\")\n\tlocal right, up, fwd = ut.RightVector, ut.UpVector, ut.LookVector\n\tlocal head = rig:world(\"Head\").Position\n\tlocal lt = rig:world(\"LowerTorso\")\n\tlocal chest = ut.Position + fwd * (0.95 * k) - up * (0.45 * k)\n\tfor _, side in ipairs({ \"Left\", \"Right\" }) do\n\t\tlocal sgn = side == \"Left\" and -1 or 1\n\t\tlocal S = rig:pivot(side .. \"Shoulder\")\n\t\tlocal target, pole\n\t\tif name == \"DoubleBiceps\" then\n\t\t\ttarget = S + right * sgn * (1.15 * k) + up * (1.05 * k) - fwd * (0.1 * k)\n\t\t\tpole = S + right * sgn * (3 * k) - up * (0.4 * k)\n\t\telseif name == \"Vacuum\" then\n\t\t\ttarget = head + right * sgn * (0.45 * k) - fwd * (0.55 * k) + up * (0.15 * k)\n\t\t\tpole = S + right * sgn * (2.5 * k) + up * (1.6 * k)\n\t\telseif name == \"MostMuscular\" then\n\t\t\ttarget = ut.Position + fwd * (0.95 * k) - up * (0.75 * k) + right * sgn * (0.25 * k)\n\t\t\tpole = S + right * sgn * (2.6 * k) + fwd * (0.4 * k)\n\t\telseif name == \"CrossedArms\" then\n\t\t\t-- forearms stacked across the chest, hands tucked by the opposite elbow\n\t\t\tlocal lift = side == \"Left\" and 0.12 or -0.02\n\t\t\ttarget = ut.Position + fwd * (0.85 * k) - up * ((0.35 - lift) * k) - right * sgn * (0.55 * k)\n\t\t\tpole = S + right * sgn * (2.2 * k) + fwd * (1.2 * k) - up * (1.4 * k)\n\t\telseif name == \"SideChest\" then\n\t\t\t-- torso twisted, lead arm bent at 90, rear hand gripping the lead wrist\n\t\t\tlocal lead = side == \"Right\"\n\t\t\ttarget = chest + right * ((lead and 0.35 or 0.05) * k) - up * ((lead and 0.1 or 0.18) * k)\n\t\t\tpole = S + right * sgn * (1.8 * k) - up * (2 * k) + (lead and fwd * (0.4 * k) or -fwd * (0.6 * k))\n\t\telseif name == \"Point\" and side == \"Right\" then\n\t\t\t-- arm stretched out toward the crowd\n\t\t\ttarget = S + (fwd * 0.8 + up * 0.5 + right * 0.3).Unit * (3.2 * k)\n\t\t\tpole = S - up * (2 * k) + right * (0.8 * k)\n\t\telse -- LatSpread (and Point's free arm): fists on the waist, elbows flared\n\t\t\ttarget = lt * Vector3.new(sgn * (d.ShoulderHalfWidth - 0.25 * k), 0.3 * k, 0.12 * k)\n\t\t\tpole = S + right * sgn * (2.6 * k) - fwd * (1.1 * k)\n\t\tend\n\t\trig:armIK(side, target, pole)\n\tend\n\tlocal n = NECK[name]\n\tif n then\n\t\trig:set(\"Neck\", CFrame.Angles(math.rad(n[1]), math.rad(n[2]), 0))\n\tend\nend\n\nreturn Poses\n"},{"ServerScriptService/BeltService","ModuleScript","--[[\n\tBeltService\n\tThe red-carpet parade down the middle of the map. Characters walk out of\n\tthe drop tunnel and straight down the carpet (BeltStart -> BeltEnd) at a\n\tsteady pace, held on the center line, until someone buys them or they\n\tleave through the exit tunnel.\n\n\tEvery few seconds it rolls the next character from ReplicatedStorage.Modules\n\t.Characters (rarity by Odds, then character by SpawnWeight) and sends it\n\tout of the tunnel. Rarity events (sounds, conveyor color, banners, G.O.A.T. server\n\tevents) are broadcast to clients through Remotes.CharacterFx; server-side\n\tspectacle (spotlights, gold particles) is created here. Unsold characters\n\tleave at BeltEnd.\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal SSS = game:GetService(\"ServerScriptService\")\n\nlocal Constants = require(RS.Modules.Constants)\nlocal Characters = require(RS.Modules.Characters)\nlocal InfluencerService = require(SSS.InfluencerService)\nlocal Notify = require(SSS.Notify)\n\nlocal BeltService = {}\n\nlocal FxRemote = RS:WaitForChild(\"Remotes\"):WaitForChild(\"CharacterFx\")\n\n-- A light that follows a character around for a few seconds (spawn spectacle).\nlocal function followSpotlight(model, color, duration)\n\tlocal root = model:FindFirstChild(\"HumanoidRootPart\")\n\tif not root then\n\t\treturn\n\tend\n\tlocal rig = Instance.new(\"Part\")\n\trig.Name = \"SpawnSpotlight\"\n\trig.Anchored = true\n\trig.CanCollide = false\n\trig.CanQuery = false\n\trig.CanTouch = false\n\trig.Transparency = 1\n\trig.Size = Vector3.new(1, 1, 1)\n\trig.Parent = workspace\n\tlocal spot = Instance.new(\"SpotLight\")\n\tspot.Face = Enum.NormalId.Bottom\n\tspot.Angle = 38\n\tspot.Range = 45\n\tspot.Brightness = 3\n\tspot.Color = color\n\tspot.Shadows = true\n\tspot.Parent = rig\n\tlocal beam = Instance.new(\"Part\")\n\tbeam.Name = \"LightBeam\"\n\tbeam.Anchored = true\n\tbeam.CanCollide = false\n\tbeam.CanQuery = false\n\tbeam.CanTouch = false\n\tbeam.Material = Enum.Material.Neon\n\tbeam.Color = color\n\tbeam.Transparency = 0.9\n\tbeam.Shape = Enum.PartType.Cylinder\n\tbeam.Size = Vector3.new(30, 7, 7)\n\tbeam.CastShadow = false\n\tbeam.Parent = workspace\n\tlocal t0 = os.clock()\n\tlocal conn\n\tconn = RunService.Heartbeat:Connect(function()\n\t\tlocal alive = root.Parent and os.clock() - t0 < duration\n\t\tif not alive then\n\t\t\tconn:Disconnect()\n\t\t\trig:Destroy()\n\t\t\tbeam:Destroy()\n\t\t\treturn\n\t\tend\n\t\tlocal p = root.Position\n\t\trig.CFrame = CFrame.new(p + Vector3.new(0, 30, 0))\n\t\tbeam.CFrame = CFrame.new(p + Vector3.new(0, 15, 0)) * CFrame.Angles(0, 0, math.rad(90))\n\t\tlocal fade = math.clamp((duration - (os.clock() - t0)) / 1.5, 0, 1)\n\t\tbeam.Transparency = 1 - 0.1 * fade\n\t\tspot.Brightness = 3 * fade\n\tend)\nend\n\nlocal function goldBurst(model, duration)\n\tlocal root = model:FindFirstChild(\"HumanoidRootPart\")\n\tif not root then\n\t\treturn\n\tend\n\tlocal att = Instance.new(\"Attachment\")\n\tatt.Parent = root\n\tlocal pe = Instance.new(\"ParticleEmitter\")\n\tpe.Color = ColorSequence.new(Color3.fromRGB(255, 236, 140), Color3.fromRGB(255, 180, 20))\n\tpe.LightEmission = 0.6\n\tpe.Rate = 25\n\tpe.Lifetime = NumberRange.new(1.2, 2.2)\n\tpe.Speed = NumberRange.new(4, 10)\n\tpe.SpreadAngle = Vector2.new(180, 180)\n\tpe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.3), NumberSequenceKeypoint.new(1, 0) })\n\tpe.Acceleration = Vector3.new(0, 3, 0)\n\tpe.Parent = att\n\ttask.delay(duration, function()\n\t\tpe.Enabled = false\n\t\ttask.delay(3, function()\n\t\t\tatt:Destroy()\n\t\tend)\n\tend)\nend\n\nlocal function announce(char, rarity, model)\n\tlocal fx = char.SpawnFx\n\tif fx == \"GoldSpotlight\" then\n\t\tfollowSpotlight(model, Color3.fromRGB(255, 205, 70), 9)\n\telseif fx == \"Cinematic\" then\n\t\tfollowSpotlight(model, Color3.fromRGB(235, 240, 255), 6)\n\telseif fx == \"GoldenEra\" then\n\t\tfollowSpotlight(model, Color3.fromRGB(255, 215, 90), 10)\n\t\tgoldBurst(model, 8)\n\telseif rarity.Index >= 7 then\n\t\tgoldBurst(model, 5)\n\tend\n\n\tFxRemote:FireAllClients(\"Spawn\", {\n\t\tModel = model,\n\t\tId = char.Name,\n\t\tName = char.DisplayName,\n\t\tRarity = char.Rarity,\n\t\tSpawnFx = fx,\n\t})\n\n\tif rarity.Announce then\n\t\tlocal text\n\t\tif rarity.Index >= 7 then\n\t\t\ttext = \"A G.O.A.T. HAS ENTERED THE GYM: \" .. char.DisplayName:upper() .. \"!\"\n\t\telseif rarity.Index >= 6 then\n\t\t\ttext = \"MYTHIC \" .. char.DisplayName:upper() .. \" just walked onto the conveyor!\"\n\t\telse\n\t\t\ttext = rarity.DisplayName .. \" \" .. char.DisplayName .. \" just hit the red carpet!\"\n\t\tend\n\t\tfor _, player in ipairs(Players:GetPlayers()) do\n\t\t\tNotify(player, text, \"info\")\n\t\tend\n\tend\nend\n\nfunction BeltService.OnPurchased(rec, buyer)\n\tFxRemote:FireAllClients(\"Purchase\", {\n\t\tModel = rec.Model,\n\t\tId = rec.Id,\n\t\tRarity = rec.Char.Rarity,\n\t\tBuyer = buyer,\n\t})\nend\n\nlocal rng = Random.new()\nlocal spawnTimer = 0\nlocal startPart, endPart\nlocal direction = Vector3.new(0, 0, 1)\nlocal dropPoints = {}\nlocal dropQueue = {}\n\n-- Shuffled round-robin: each chute gets one drop per cycle (fair to every gym).\nlocal function nextDropPoint()\n\tif #dropQueue == 0 then\n\t\tfor _, p in ipairs(dropPoints) do\n\t\t\ttable.insert(dropQueue, p)\n\t\tend\n\t\tfor i = #dropQueue, 2, -1 do\n\t\t\tlocal j = rng:NextInteger(1, i)\n\t\t\tdropQueue[i], dropQueue[j] = dropQueue[j], dropQueue[i]\n\t\tend\n\tend\n\treturn table.remove(dropQueue)\nend\n\nfunction BeltService.Init()\n\tlocal belt = workspace:WaitForChild(\"GymWarsMap\"):WaitForChild(\"Belt\")\n\tstartPart = belt:WaitForChild(\"BeltStart\")\n\tendPart = belt:WaitForChild(\"BeltEnd\")\n\tdirection = (endPart.Position - startPart.Position) * Vector3.new(1, 0, 1)\n\tdirection = direction.Unit\n\tfor _, d in ipairs(belt:GetDescendants()) do\n\t\tif d:IsA(\"BasePart\") and d:GetAttribute(\"DropPoint\") then\n\t\t\ttable.insert(dropPoints, d)\n\t\tend\n\tend\n\tif #dropPoints == 0 then\n\t\ttable.insert(dropPoints, startPart)\n\tend\n\tInfluencerService.OnPurchased = BeltService.OnPurchased\n\tworkspace:SetAttribute(\"BeltSpeed\", 0) -- nothing scrolls any more\n\tBeltService.StartClocks()\n\n\tRunService.Heartbeat:Connect(function(dt)\n\t\tBeltService.Step(dt)\n\tend)\nend\n\nlocal checkAccum = 0\nlocal lastPreviewEvent = -math.huge\nlocal nextLegendaryAt, nextMythicAt, forcedReadyAt = math.huge, math.huge, 0\n\n-- Walk a character out of the drop gate (and announce it).\nlocal function spawnCharacter(char, guaranteed)\n\tlocal rarity = Characters.GetRarity(char.Rarity)\n\tlocal drop = nextDropPoint()\n\tlocal pos = drop.Position -- everyone walks out of the gate (no sky drops)\n\t-- avatar creation can yield (asset loading), so don't block Heartbeat\n\ttask.spawn(function()\n\t\tlocal rec = InfluencerService.Spawn(char, CFrame.new(pos))\n\t\tif rec and rec.Model then\n\t\t\tlocal now = os.clock()\n\t\t\tif guaranteed or not Characters.PREVIEW or now - lastPreviewEvent >= Characters.PREVIEW_EVENT_COOLDOWN then\n\t\t\t\tlastPreviewEvent = now\n\t\t\t\tannounce(char, rarity, rec.Model)\n\t\t\tend\n\t\tend\n\tend)\nend\n\nfunction BeltService.StartClocks()\n\tlocal now = workspace:GetServerTimeNow()\n\tnextLegendaryAt = now + Constants.BELT.GuaranteeLegendary\n\tnextMythicAt = now + Constants.BELT.GuaranteeMythic\n\tworkspace:SetAttribute(\"GuaranteeLegendaryAt\", nextLegendaryAt)\n\tworkspace:SetAttribute(\"GuaranteeMythicAt\", nextMythicAt)\nend\n\nfunction BeltService.Step(dt)\n\tlocal cfg = Constants.BELT\n\n\t-- walkers: keep everyone marching down the center line\n\tcheckAccum += dt\n\tif checkAccum >= 0.2 then\n\t\tcheckAccum = 0\n\t\tlocal endDist = (endPart.Position - startPart.Position):Dot(direction)\n\t\tfor _, rec in ipairs(InfluencerService.GetAllOnBelt()) do\n\t\t\tlocal hum = rec.Humanoid\n\t\t\tif not (hum and rec.Root) or rec.Root.Anchored then\n\t\t\t\tcontinue\n\t\t\tend\n\t\t\tlocal rel = rec.Root.Position - startPart.Position\n\t\t\tlocal along = rel:Dot(direction)\n\t\t\tlocal lateral = (rel - direction * along) * Vector3.new(1, 0, 1)\n\t\t\tif along >= endDist then\n\t\t\t\tInfluencerService.Destroy(rec) -- walked out through the exit tunnel\n\t\t\t\tcontinue\n\t\t\tend\n\t\t\t-- walk forward, steering gently back onto the line\n\t\t\thum.WalkSpeed = cfg.WalkSpeed\n\t\t\tlocal steer = direction - lateral * 0.25\n\t\t\thum:Move(steer.Unit, false)\n\t\tend\n\tend\n\n\t-- guaranteed drops: a Legendary every 5 min, a Mythic every 15 min\n\t-- (the clock board in the wall shows these countdowns)\n\tlocal now = workspace:GetServerTimeNow()\n\tif now >= forcedReadyAt then\n\t\tlocal forced\n\t\tif now >= nextMythicAt then\n\t\t\tforced = \"Mythic\"\n\t\t\tnextMythicAt += cfg.GuaranteeMythic\n\t\telseif now >= nextLegendaryAt then\n\t\t\tforced = \"Legendary\"\n\t\t\tnextLegendaryAt += cfg.GuaranteeLegendary\n\t\tend\n\t\tif forced then\n\t\t\tworkspace:SetAttribute(\"GuaranteeLegendaryAt\", nextLegendaryAt)\n\t\t\tworkspace:SetAttribute(\"GuaranteeMythicAt\", nextMythicAt)\n\t\t\tforcedReadyAt = now + 3 -- keep two guaranteed drops from stacking in the doorway\n\t\t\tlocal char = Characters.RollOfRarity(forced, rng)\n\t\t\tif char then\n\t\t\t\tspawnTimer = 0\n\t\t\t\tspawnCharacter(char, true)\n\t\t\tend\n\t\tend\n\tend\n\n\tspawnTimer += dt\n\tif spawnTimer >= cfg.SpawnInterval then\n\t\tspawnTimer = 0\n\t\tif InfluencerService.CountOnBelt() < cfg.MaxOnBelt then\n\t\t\tlocal char = Characters.Roll(rng)\n\t\t\tif char then\n\t\t\t\tspawnCharacter(char, false)\n\t\t\tend\n\t\tend\n\tend\nend\n\nreturn BeltService\n"},{"ServerScriptService/CharacterLooks","ModuleScript","--[[\n\tCharacterLooks\n\tBuilds a character's Roblox model from its Look spec in\n\tReplicatedStorage.Modules.Characters — no per-character scripts.\n\n\t  - Base R15 avatar (body colors + proportions via HumanoidDescription)\n\t  - Clothing by coloring body parts + loose \"cloth shells\" (oversized tees,\n\t    stringers, hoods, baggy pants...) — no real logos or branded designs\n\t  - Hair / beards / mustaches built from rounded parts\n\t  - Props (duffel, gallon jug, clipboard, camera, straps, cap)\n\t  - Muscle shaping: shoulder caps, biceps, forearms, pecs, traps, quads/calves\n\t  - Rarity presentation: outline, aura particles, light, overhead card\n\n\tAll extra parts are welded, massless and non-colliding, so they ride along\n\twith walking and with the procedural workout animations.\n]]\n\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal SSS = game:GetService(\"ServerScriptService\")\n\nlocal Constants = require(RS.Modules.Constants)\nlocal Characters = require(RS.Modules.Characters)\nlocal StationSpecs = require(RS.Modules.Gym.StationSpecs)\nlocal NpcService = require(SSS.NpcService)\nlocal MeshCharacter = require(RS.Modules.MeshCharacter)\nlocal CharacterModels = require(SSS.CharacterModels)\n\nlocal CharacterLooks = {}\n\nlocal LIMBS = {\n\t\"LeftUpperArm\", \"LeftLowerArm\", \"LeftHand\", \"RightUpperArm\", \"RightLowerArm\", \"RightHand\",\n\t\"LeftUpperLeg\", \"LeftLowerLeg\", \"LeftFoot\", \"RightUpperLeg\", \"RightLowerLeg\", \"RightFoot\",\n}\n\n-- ----------------------------------------------------------------------\n-- Part helpers\n-- ----------------------------------------------------------------------\nlocal function attach(folder, host, size, offset, color, opts)\n\topts = opts or {}\n\tlocal p = Instance.new(\"Part\")\n\tp.Name = opts.Name or \"Look\"\n\tp.Size = size\n\tp.Color = color\n\tp.Material = opts.Material or Enum.Material.SmoothPlastic\n\tp.TopSurface = Enum.SurfaceType.Smooth\n\tp.BottomSurface = Enum.SurfaceType.Smooth\n\tp.CanCollide = false\n\tp.CanTouch = false\n\tp.CanQuery = false\n\tp.Massless = true\n\tp.CastShadow = opts.Shadow ~= false\n\tp.CollisionGroup = NpcService.GROUP_NPC\n\tp.CFrame = host.CFrame * (opts.Rot and (CFrame.new(offset) * opts.Rot) or CFrame.new(offset))\n\tif opts.Round ~= false then\n\t\tlocal mesh = Instance.new(\"SpecialMesh\")\n\t\tmesh.MeshType = opts.Cylinder and Enum.MeshType.Cylinder or Enum.MeshType.Sphere\n\t\tmesh.Parent = p\n\tend\n\tif opts.Transparency then\n\t\tp.Transparency = opts.Transparency\n\tend\n\tif opts.Prop then\n\t\tp:SetAttribute(\"Prop\", true)\n\tend\n\tp.Parent = folder\n\tlocal w = Instance.new(\"WeldConstraint\")\n\tw.Part0 = host\n\tw.Part1 = p\n\tw.Parent = p\n\treturn p\nend\n\n-- size/offset given as fractions of the host part's size\nlocal function shell(folder, host, sizeMul, offsetMul, color, opts)\n\tlocal s = host.Size\n\treturn attach(folder, host, s * sizeMul, s * offsetMul, color or host.Color, opts)\nend\n\n-- ----------------------------------------------------------------------\n-- Clothing (color the body, then add loose cloth where the style needs it)\n-- ----------------------------------------------------------------------\nlocal function paint(model, look)\n\tlocal skin = look.Skin\n\tlocal top = look.Top or { Style = \"Tee\", Color = Color3.fromRGB(60, 60, 66) }\n\tlocal bottom = look.Bottom or { Style = \"Shorts\", Color = Color3.fromRGB(30, 30, 34) }\n\tlocal P = {}\n\tfor _, n in ipairs(LIMBS) do\n\t\tP[n] = model:FindFirstChild(n)\n\tend\n\tP.Head = model:FindFirstChild(\"Head\")\n\tP.UpperTorso = model:FindFirstChild(\"UpperTorso\")\n\tP.LowerTorso = model:FindFirstChild(\"LowerTorso\")\n\tlocal function color(names, c)\n\t\tfor _, n in ipairs(names) do\n\t\t\tif P[n] then\n\t\t\t\tP[n].Color = c\n\t\t\tend\n\t\tend\n\tend\n\n\tcolor({ \"Head\", \"LeftUpperArm\", \"LeftLowerArm\", \"LeftHand\", \"RightUpperArm\", \"RightLowerArm\", \"RightHand\",\n\t\t\"LeftUpperLeg\", \"LeftLowerLeg\", \"RightUpperLeg\", \"RightLowerLeg\" }, skin)\n\tcolor({ \"LeftFoot\", \"RightFoot\" }, look.Shoes or Color3.fromRGB(40, 40, 44))\n\n\t-- top\n\tlocal ts = top.Style\n\tif ts == \"Stringer\" then\n\t\tcolor({ \"UpperTorso\" }, skin)\n\telse\n\t\tcolor({ \"UpperTorso\" }, top.Color)\n\tend\n\tif ts == \"Tee\" or ts == \"Oversized\" then\n\t\tcolor({ \"LeftUpperArm\", \"RightUpperArm\" }, top.Color)\n\telseif ts == \"Hoodie\" then\n\t\tcolor({ \"LeftUpperArm\", \"RightUpperArm\", \"LeftLowerArm\", \"RightLowerArm\" }, top.Color)\n\tend\n\n\t-- bottom\n\tlocal bs = bottom.Style\n\tcolor({ \"LowerTorso\" }, bottom.Color)\n\tif bs == \"Joggers\" or bs == \"Sweatpants\" or bs == \"FlowingPants\" then\n\t\tcolor({ \"LeftUpperLeg\", \"RightUpperLeg\", \"LeftLowerLeg\", \"RightLowerLeg\" }, bottom.Color)\n\telseif bs == \"Shorts\" or bs == \"LongShorts\" then\n\t\tcolor({ \"LeftUpperLeg\", \"RightUpperLeg\" }, bottom.Color)\n\t\tif typeof(look.Socks) == \"Color3\" then\n\t\t\tcolor({ \"LeftLowerLeg\", \"RightLowerLeg\" }, look.Socks)\n\t\tend\n\telseif bs == \"PosingShorts\" then\n\t\tif typeof(look.Socks) == \"Color3\" then\n\t\t\tcolor({ \"LeftLowerLeg\", \"RightLowerLeg\" }, look.Socks)\n\t\tend\n\tend\n\treturn P, top, bottom\nend\n\nlocal function cloth(folder, P, top, bottom, look, shape)\n\tlocal ts, bs = top.Style, bottom.Style\n\tlocal ut = P.UpperTorso\n\tif ut then\n\t\tif ts == \"Oversized\" then\n\t\t\tshell(folder, ut, Vector3.new(1.14, 1.06, 1.22), Vector3.new(0, -0.02, 0), top.Color, { Name = \"Cloth\", Round = false })\n\t\t\tfor _, n in ipairs({ \"LeftUpperArm\", \"RightUpperArm\" }) do\n\t\t\t\tif P[n] then\n\t\t\t\t\tshell(folder, P[n], Vector3.new(1.3, 0.72, 1.3), Vector3.new(0, 0.16, 0), top.Color, { Name = \"Cloth\", Round = false })\n\t\t\t\tend\n\t\t\tend\n\t\telseif ts == \"Stringer\" then\n\t\t\tshell(folder, ut, Vector3.new(0.5, 0.95, 1.04), Vector3.new(0, -0.02, 0), top.Color, { Name = \"Cloth\", Round = false })\n\t\t\tfor _, s in ipairs({ -1, 1 }) do\n\t\t\t\tshell(folder, ut, Vector3.new(0.1, 0.35, 1.02), Vector3.new(s * 0.2, 0.35, 0), top.Color, { Name = \"Cloth\", Round = false })\n\t\t\tend\n\t\telseif ts == \"Hoodie\" or ts == \"SleevelessHoodie\" then\n\t\t\tshell(folder, ut, Vector3.new(0.8, 0.32, 0.55), Vector3.new(0, 0.48, 0.42), top.Color, { Name = \"Hood\" })\n\t\t\tshell(folder, ut, Vector3.new(0.5, 0.25, 0.1), Vector3.new(0, -0.1, -0.52), top.Color:Lerp(Color3.new(0, 0, 0), 0.25), { Name = \"Pocket\", Round = false })\n\t\tend\n\tend\n\tfor _, n in ipairs({ \"LeftUpperLeg\", \"RightUpperLeg\" }) do\n\t\tlocal leg = P[n]\n\t\tif leg then\n\t\t\tif bs == \"PosingShorts\" then\n\t\t\t\tshell(folder, leg, Vector3.new(1.06, 0.3, 1.06), Vector3.new(0, 0.36, 0), bottom.Color, { Name = \"Cloth\", Round = false })\n\t\t\telseif bs == \"Sweatpants\" or bs == \"FlowingPants\" then\n\t\t\t\tlocal k = bs == \"FlowingPants\" and 1.45 or 1.18\n\t\t\t\tshell(folder, leg, Vector3.new(k, 1.02, k), Vector3.new(0, 0, 0), bottom.Color, { Name = \"Cloth\" })\n\t\t\tend\n\t\tend\n\tend\n\tif bottom.Trim and (bs == \"Shorts\" or bs == \"PosingShorts\") then\n\t\t-- contrast piping around the hem and up the outer seam\n\t\tfor _, side in ipairs({ \"Left\", \"Right\" }) do\n\t\t\tlocal leg = P[side .. \"UpperLeg\"]\n\t\t\tif leg then\n\t\t\t\tlocal s = side == \"Left\" and -1 or 1\n\t\t\t\tlocal hemY = bs == \"PosingShorts\" and 0.22 or -0.44\n\t\t\t\t-- the quad shell tapers toward the knee; the hem ring hugs that taper\n\t\t\t\tlocal L = shape.Legs or 0\n\t\t\t\tlocal k = bs == \"PosingShorts\" and 0.5 or 0.3\n\t\t\t\tshell(folder, leg, Vector3.new(1.08 + k * L, 0.07, 1.1 + k * L), Vector3.new(s * 0.04 * L, hemY, -0.04 * L), bottom.Trim, { Name = \"Trim\", Round = false })\n\t\t\t\tshell(folder, leg, Vector3.new(0.06, 0.5 - hemY, 0.3), Vector3.new(s * (0.56 + 0.32 * L), 0.25 + hemY / 2, 0), bottom.Trim, { Name = \"Trim\", Round = false })\n\t\t\tend\n\t\tend\n\tend\n\tfor _, n in ipairs({ \"LeftLowerLeg\", \"RightLowerLeg\" }) do\n\t\tlocal leg = P[n]\n\t\tif leg then\n\t\t\tif bs == \"LongShorts\" then\n\t\t\t\tshell(folder, leg, Vector3.new(1.12, 0.45, 1.12), Vector3.new(0, 0.3, 0), bottom.Color, { Name = \"Cloth\", Round = false })\n\t\t\telseif bs == \"Sweatpants\" or bs == \"FlowingPants\" then\n\t\t\t\tlocal k = bs == \"FlowingPants\" and 1.5 or 1.2\n\t\t\t\tshell(folder, leg, Vector3.new(k, 1.02, k), Vector3.new(0, 0, 0), bottom.Color, { Name = \"Cloth\" })\n\t\t\tend\n\t\tend\n\tend\nend\n\n-- ----------------------------------------------------------------------\n-- Muscle shaping\n-- ----------------------------------------------------------------------\n-- Build values are authored on a 0..~1.3 scale; shells use a damped version\n-- so even the biggest bodies read as muscle rather than balloons.\nlocal BULK = 0.5\nlocal function shapeOf(build)\n\tlocal out = {}\n\tfor k, v in pairs(build) do\n\t\tout[k] = v\n\tend\n\tfor _, k in ipairs({ \"Shoulders\", \"Arms\", \"Forearms\", \"Chest\", \"Traps\", \"Legs\" }) do\n\t\tout[k] = (build[k] or 0) * BULK\n\tend\n\treturn out\nend\n\nlocal function bulk(folder, P, build)\n\tlocal sh, arms, fore = build.Shoulders or 0, build.Arms or 0, build.Forearms or 0\n\tlocal chest, traps, legs = build.Chest or 0, build.Traps or 0, build.Legs or 0\n\tfor _, side in ipairs({ \"Left\", \"Right\" }) do\n\t\tlocal s = side == \"Left\" and -1 or 1\n\t\tlocal ua, la = P[side .. \"UpperArm\"], P[side .. \"LowerArm\"]\n\t\tif ua and sh > 0 then\n\t\t\tshell(folder, ua, Vector3.new(1.15 + 0.45 * sh, 0.55 + 0.25 * sh, 1.12 + 0.4 * sh), Vector3.new(s * 0.1 * sh, 0.3, 0), nil, { Name = \"Delt\" })\n\t\tend\n\t\tif ua and arms > 0 then\n\t\t\tshell(folder, ua, Vector3.new(0.95 + 0.35 * arms, 0.62, 0.8 + 0.45 * arms), Vector3.new(0, -0.05, -0.12 - 0.08 * arms), nil, { Name = \"Bicep\" })\n\t\t\tshell(folder, ua, Vector3.new(0.9 + 0.3 * arms, 0.7, 0.7 + 0.35 * arms), Vector3.new(0, 0.02, 0.14 + 0.06 * arms), nil, { Name = \"Tricep\" })\n\t\tend\n\t\tif la and (fore > 0 or arms > 0.4) then\n\t\t\tlocal f = math.max(fore, arms * 0.5)\n\t\t\tshell(folder, la, Vector3.new(1.0 + 0.4 * f, 0.7, 1.0 + 0.4 * f), Vector3.new(0, 0.15, 0), nil, { Name = \"Forearm\" })\n\t\tend\n\t\tlocal ul, ll = P[side .. \"UpperLeg\"], P[side .. \"LowerLeg\"]\n\t\tif ul and legs > 0 then\n\t\t\tshell(folder, ul, Vector3.new(1.08 + 0.55 * legs, 0.98, 1.1 + 0.6 * legs), Vector3.new(s * 0.04 * legs, -0.02, -0.06 * legs), nil, { Name = \"Quad\" })\n\t\tend\n\t\tif ll and legs > 0 then\n\t\t\tshell(folder, ll, Vector3.new(1.0 + 0.4 * legs, 0.66, 1.05 + 0.6 * legs), Vector3.new(0, 0.12, 0.1 * legs), nil, { Name = \"Calf\" })\n\t\tend\n\tend\n\tlocal ut = P.UpperTorso\n\tif ut and chest > 0 then\n\t\tshell(folder, ut, Vector3.new(0.9, 0.46, 0.3 + 0.25 * chest), Vector3.new(0, 0.16, -0.46 - 0.08 * chest), nil, { Name = \"Pecs\" })\n\tend\n\tif ut and traps > 0 then\n\t\tshell(folder, ut, Vector3.new(0.62 + 0.25 * traps, 0.25 + 0.2 * traps, 0.55), Vector3.new(0, 0.46 + 0.05 * traps, 0.08), nil, { Name = \"Traps\" })\n\tend\nend\n\n-- ----------------------------------------------------------------------\n-- Hair & face\n-- ----------------------------------------------------------------------\nlocal function hair(folder, head, look)\n\tlocal h = look.Hair or { Style = \"Short\" }\n\tlocal c = h.Color or Color3.fromRGB(60, 40, 28)\n\tlocal style = h.Style\n\tlocal function blob(size, offset, opts)\n\t\treturn shell(folder, head, size, offset, c, opts or { Name = \"Hair\" })\n\tend\n\tlocal function block(size, offset)\n\t\treturn shell(folder, head, size, offset, c, { Name = \"Hair\", Round = false })\n\tend\n\tlocal function cap(height)\n\t\tblob(Vector3.new(1.08, height or 0.42, 1.1), Vector3.new(0, 0.34, 0.03))\n\t\tblob(Vector3.new(1.06, 0.62, 0.36), Vector3.new(0, 0.12, 0.38))\n\tend\n\n\tif style == \"Bald\" then\n\t\treturn\n\telseif style == \"Buzz\" then\n\t\tblob(Vector3.new(1.04, 0.3, 1.06), Vector3.new(0, 0.37, 0.02))\n\telseif style == \"Short\" then\n\t\tcap(0.4)\n\telseif style == \"Fringe\" then\n\t\tcap(0.42)\n\t\tblock(Vector3.new(0.86, 0.16, 0.12), Vector3.new(0, 0.3, -0.49))\n\telseif style == \"Shaggy\" then\n\t\tcap(0.46)\n\t\tfor _, o in ipairs({\n\t\t\tVector3.new(-0.36, 0.3, -0.1), Vector3.new(0.36, 0.3, -0.1), Vector3.new(-0.4, 0.18, 0.25),\n\t\t\tVector3.new(0.4, 0.18, 0.25), Vector3.new(0, 0.44, 0.1), Vector3.new(0, 0.05, 0.46),\n\t\t}) do\n\t\t\tblob(Vector3.new(0.5, 0.42, 0.5), o)\n\t\tend\n\t\tblock(Vector3.new(0.8, 0.2, 0.14), Vector3.new(0.05, 0.26, -0.49))\n\telseif style == \"Curly\" or style == \"LongCurly\" then\n\t\tcap(0.4)\n\t\tfor i = 0, 9 do\n\t\t\tlocal a = i / 10 * math.pi * 2\n\t\t\tblob(Vector3.new(0.34, 0.34, 0.34), Vector3.new(math.cos(a) * 0.38, 0.42 + (i % 2) * 0.05, math.sin(a) * 0.38))\n\t\tend\n\t\tif style == \"LongCurly\" then\n\t\t\tfor i = 0, 8 do\n\t\t\t\tlocal a = (i / 8) * math.pi + math.pi * 0.0\n\t\t\t\tblob(Vector3.new(0.34, 0.4, 0.34), Vector3.new(math.cos(a) * 0.5, -0.05 - (i % 3) * 0.08, 0.1 + math.abs(math.sin(a)) * 0.38))\n\t\t\tend\n\t\tend\n\telseif style == \"Wavy\" then\n\t\tcap(0.44)\n\t\tfor _, s in ipairs({ -1, 1 }) do\n\t\t\tblob(Vector3.new(0.2, 0.55, 0.85), Vector3.new(s * 0.5, 0.12, 0.08))\n\t\tend\n\t\tblob(Vector3.new(1.02, 0.7, 0.3), Vector3.new(0, 0.02, 0.44))\n\t\tblock(Vector3.new(0.7, 0.18, 0.12), Vector3.new(-0.1, 0.3, -0.49))\n\telseif style == \"Fluffy\" then\n\t\tblob(Vector3.new(1.22, 0.66, 1.2), Vector3.new(0, 0.4, 0.02))\n\t\tblob(Vector3.new(0.7, 0.4, 0.5), Vector3.new(-0.12, 0.46, -0.32))\n\t\tblob(Vector3.new(1.06, 0.6, 0.36), Vector3.new(0, 0.12, 0.38))\n\telseif style == \"Styled\" then\n\t\tcap(0.4)\n\t\tblob(Vector3.new(0.82, 0.34, 0.48), Vector3.new(0, 0.54, -0.22))\n\telseif style == \"Pompadour\" then\n\t\tcap(0.4)\n\t\tblob(Vector3.new(0.92, 0.52, 0.62), Vector3.new(0, 0.62, -0.2))\n\t\tblob(Vector3.new(0.7, 0.3, 0.3), Vector3.new(0, 0.74, -0.42))\n\telseif style == \"Floppy\" then\n\t\tcap(0.46)\n\t\tblock(Vector3.new(0.95, 0.34, 0.14), Vector3.new(0.06, 0.22, -0.49))\n\t\tfor _, s in ipairs({ -1, 1 }) do\n\t\t\tblob(Vector3.new(0.2, 0.5, 0.7), Vector3.new(s * 0.5, 0.14, 0.05))\n\t\tend\n\telseif style == \"SweptBack\" then\n\t\tblob(Vector3.new(1.06, 0.5, 1.1), Vector3.new(0, 0.38, 0.06))\n\t\tblob(Vector3.new(0.98, 0.5, 0.55), Vector3.new(0, 0.36, 0.28))\n\t\tblob(Vector3.new(1.06, 0.62, 0.36), Vector3.new(0, 0.12, 0.38))\n\telseif style == \"Spiky\" then\n\t\tcap(0.36)\n\t\tfor i = 0, 6 do\n\t\t\tlocal x = -0.36 + i * 0.12\n\t\t\tblock(Vector3.new(0.12, 0.3, 0.12), Vector3.new(x, 0.56 + (i % 2) * 0.05, -0.1 + (i % 3) * 0.12))\n\t\tend\n\telseif style == \"Tied\" then\n\t\tcap(0.4)\n\t\tblob(Vector3.new(0.36, 0.36, 0.36), Vector3.new(0, 0.34, 0.58))\n\telse\n\t\tcap(0.4)\n\tend\nend\n\nlocal function face(folder, head, look)\n\tlocal hc = (look.Hair and look.Hair.Color) or Color3.fromRGB(40, 30, 24)\n\tif look.Beard == \"Full\" then\n\t\tshell(folder, head, Vector3.new(0.92, 0.42, 0.42), Vector3.new(0, -0.3, -0.3), hc, { Name = \"Beard\" })\n\t\tfor _, s in ipairs({ -1, 1 }) do\n\t\t\tshell(folder, head, Vector3.new(0.14, 0.5, 0.55), Vector3.new(s * 0.45, -0.1, -0.08), hc, { Name = \"Beard\" })\n\t\tend\n\telseif look.Beard == \"Large\" then\n\t\tshell(folder, head, Vector3.new(0.96, 0.68, 0.5), Vector3.new(0, -0.42, -0.3), hc, { Name = \"Beard\" })\n\t\tfor _, s in ipairs({ -1, 1 }) do\n\t\t\tshell(folder, head, Vector3.new(0.16, 0.6, 0.6), Vector3.new(s * 0.46, -0.12, -0.06), hc, { Name = \"Beard\" })\n\t\tend\n\telseif look.Beard == \"Stubble\" then\n\t\tshell(folder, head, Vector3.new(0.9, 0.34, 0.2), Vector3.new(0, -0.3, -0.42), hc, { Name = \"Stubble\", Transparency = 0.45 })\n\tend\n\tif look.Mustache then\n\t\tshell(folder, head, Vector3.new(0.46, 0.09, 0.1), Vector3.new(0, -0.14, -0.5), hc, { Name = \"Mustache\", Round = false })\n\tend\nend\n\n-- ----------------------------------------------------------------------\n-- Footwear, socks and training gear (belt, knee sleeves, wraps)\n-- ----------------------------------------------------------------------\nlocal function gear(folder, P, look, build)\n\tlocal legs = build.Legs or 0\n\tlocal socks = look.Socks\n\tif type(socks) == \"table\" then\n\t\tlocal h = socks.Height or 0.5\n\t\tfor _, n in ipairs({ \"LeftLowerLeg\", \"RightLowerLeg\" }) do\n\t\t\tlocal ll = P[n]\n\t\t\tif ll then\n\t\t\t\t-- slightly bulkier than the calf so the sock reads as fabric\n\t\t\t\tshell(folder, ll, Vector3.new(1.05 + 0.3 * legs, h, 1.06 + 0.4 * legs), Vector3.new(0, -0.5 + h / 2, 0.04 * legs), socks.Color, { Name = \"Sock\", Round = false })\n\t\t\t\tfor i, stripe in ipairs(socks.Stripes or {}) do\n\t\t\t\t\tlocal y = -0.5 + h - 0.08 - (i - 1) * 0.1\n\t\t\t\t\tshell(folder, ll, Vector3.new(1.07 + 0.3 * legs, 0.05, 1.08 + 0.4 * legs), Vector3.new(0, y, 0.04 * legs), stripe, { Name = \"SockStripe\", Round = false })\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\tlocal shoe = look.ShoeStyle\n\tif shoe == \"HighTop\" or shoe == \"Boots\" then\n\t\tlocal c = look.Shoes or Color3.fromRGB(40, 40, 44)\n\t\tfor _, side in ipairs({ \"Left\", \"Right\" }) do\n\t\t\tlocal foot, ll = P[side .. \"Foot\"], P[side .. \"LowerLeg\"]\n\t\t\tif foot then\n\t\t\t\tshell(folder, foot, Vector3.new(1.12, 1.15, 1.1), Vector3.new(0, 0.04, -0.02), c, { Name = \"Shoe\", Round = false })\n\t\t\t\tshell(folder, foot, Vector3.new(1.16, 0.22, 1.14), Vector3.new(0, -0.42, -0.02), shoe == \"Boots\" and Color3.fromRGB(20, 20, 22) or Color3.fromRGB(235, 235, 235), { Name = \"Sole\", Round = false })\n\t\t\tend\n\t\t\tif ll then\n\t\t\t\tlocal h = shoe == \"Boots\" and 0.34 or 0.2\n\t\t\t\tshell(folder, ll, Vector3.new(1.08 + 0.3 * legs, h, 1.1 + 0.4 * legs), Vector3.new(0, -0.5 + h / 2, 0.04 * legs), c, { Name = \"ShoeCollar\", Round = false })\n\t\t\tend\n\t\tend\n\tend\n\tfor _, item in ipairs(look.Gear or {}) do\n\t\tif item == \"LiftingBelt\" and P.LowerTorso then\n\t\t\tlocal lt = P.LowerTorso\n\t\t\tshell(folder, lt, Vector3.new(1.08, 0.42, 1.12), Vector3.new(0, 0.28, 0), Color3.fromRGB(28, 26, 26), { Name = \"Belt\", Round = false, Material = Enum.Material.Leather })\n\t\t\tshell(folder, lt, Vector3.new(0.3, 0.3, 0.06), Vector3.new(0, 0.28, -0.57), Color3.fromRGB(190, 190, 196), { Name = \"Buckle\", Round = false, Material = Enum.Material.Metal })\n\t\t\tfor _, x in ipairs({ -0.36, 0.36 }) do\n\t\t\t\tshell(folder, lt, Vector3.new(0.06, 0.06, 0.02), Vector3.new(x, 0.28, -0.57), Color3.fromRGB(170, 170, 176), { Name = \"Rivet\", Material = Enum.Material.Metal })\n\t\t\tend\n\t\telseif item == \"KneeSleeves\" then\n\t\t\tlocal band = look.SleeveBand or Color3.fromRGB(190, 30, 36)\n\t\t\tfor _, n in ipairs({ \"LeftLowerLeg\", \"RightLowerLeg\" }) do\n\t\t\t\tlocal ll = P[n]\n\t\t\t\tif ll then\n\t\t\t\t\tshell(folder, ll, Vector3.new(1.1 + 0.35 * legs, 0.32, 1.12 + 0.45 * legs), Vector3.new(0, 0.34, 0.04 * legs), Color3.fromRGB(22, 22, 24), { Name = \"KneeSleeve\", Round = false, Material = Enum.Material.Rubber })\n\t\t\t\t\tshell(folder, ll, Vector3.new(1.12 + 0.35 * legs, 0.06, 1.14 + 0.45 * legs), Vector3.new(0, 0.2, 0.04 * legs), band, { Name = \"SleeveBand\", Round = false })\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\nend\n\n-- ----------------------------------------------------------------------\n-- Props (hidden while training on a machine)\n-- ----------------------------------------------------------------------\nlocal function props(folder, P, look)\n\tlocal list = look.Props or {}\n\tfor _, prop in ipairs(list) do\n\t\tif prop == \"Duffel\" and P.RightHand then\n\t\t\tlocal bag = attach(folder, P.RightHand, Vector3.new(1.3, 0.62, 0.62), Vector3.new(0, -0.55, 0), Color3.fromRGB(40, 44, 52), { Name = \"Duffel\", Round = false, Prop = true })\n\t\t\tbag.Material = Enum.Material.Fabric\n\t\t\tattach(folder, P.RightHand, Vector3.new(0.9, 0.08, 0.1), Vector3.new(0, -0.2, 0), Color3.fromRGB(30, 30, 34), { Name = \"DuffelStrap\", Round = false, Prop = true })\n\t\telseif prop == \"WaterJug\" and P.RightHand then\n\t\t\tattach(folder, P.RightHand, Vector3.new(0.72, 1.05, 0.72), Vector3.new(0, -0.68, 0), Color3.fromRGB(215, 228, 240), { Name = \"Jug\", Round = false, Prop = true, Transparency = 0.25 })\n\t\t\tattach(folder, P.RightHand, Vector3.new(0.3, 0.14, 0.3), Vector3.new(0, -0.08, 0), Color3.fromRGB(40, 110, 200), { Name = \"JugCap\", Cylinder = false, Prop = true })\n\t\telseif prop == \"Clipboard\" and P.LeftHand then\n\t\t\tattach(folder, P.LeftHand, Vector3.new(0.85, 1.15, 0.08), Vector3.new(0, -0.45, -0.25), Color3.fromRGB(120, 90, 56), { Name = \"Clipboard\", Round = false, Prop = true })\n\t\t\tattach(folder, P.LeftHand, Vector3.new(0.7, 0.9, 0.02), Vector3.new(0, -0.48, -0.3), Color3.fromRGB(245, 245, 245), { Name = \"Paper\", Round = false, Prop = true })\n\t\telseif prop == \"Tripod\" and P.RightHand then\n\t\t\tattach(folder, P.RightHand, Vector3.new(0.12, 1.4, 0.12), Vector3.new(0, 0.5, 0), Color3.fromRGB(30, 30, 34), { Name = \"TripodPole\", Round = false, Prop = true })\n\t\t\tattach(folder, P.RightHand, Vector3.new(0.5, 0.34, 0.3), Vector3.new(0, 1.25, 0), Color3.fromRGB(24, 24, 28), { Name = \"Camera\", Round = false, Prop = true })\n\t\t\tattach(folder, P.RightHand, Vector3.new(0.18, 0.18, 0.12), Vector3.new(0, 1.25, -0.2), Color3.fromRGB(60, 90, 140), { Name = \"Lens\", Prop = true })\n\t\telseif (prop == \"WristStraps\" or prop == \"WristWraps\") then\n\t\t\tlocal c = look.WrapColor or (prop == \"WristWraps\" and Color3.fromRGB(200, 40, 40) or Color3.fromRGB(30, 30, 34))\n\t\t\tfor _, n in ipairs({ \"LeftLowerArm\", \"RightLowerArm\" }) do\n\t\t\t\tlocal la = P[n]\n\t\t\t\tif la then\n\t\t\t\t\tshell(folder, la, Vector3.new(1.12, 0.18, 1.12), Vector3.new(0, -0.4, 0), c, { Name = \"Wrap\", Round = false })\n\t\t\t\tend\n\t\t\tend\n\t\telseif prop == \"Cap\" and P.Head then\n\t\t\tlocal cc = look.CapColor or Color3.fromRGB(30, 30, 34)\n\t\t\tshell(folder, P.Head, Vector3.new(1.1, 0.4, 1.12), Vector3.new(0, 0.38, 0.02), cc, { Name = \"Cap\" })\n\t\t\tshell(folder, P.Head, Vector3.new(0.9, 0.06, 0.5), Vector3.new(0, 0.26, -0.6), cc, { Name = \"CapBrim\", Round = false })\n\t\tend\n\tend\nend\n\nfunction CharacterLooks.SetPropsVisible(model, visible)\n\tlocal folder = model:FindFirstChild(\"Look\")\n\tif not folder then\n\t\treturn\n\tend\n\tfor _, p in ipairs(folder:GetChildren()) do\n\t\tif p:IsA(\"BasePart\") and p:GetAttribute(\"Prop\") then\n\t\t\tp.Transparency = visible and (p:GetAttribute(\"BaseTransparency\") or 0) or 1\n\t\tend\n\tend\nend\n\n-- ----------------------------------------------------------------------\n-- Overhead card: NAME / RARITY / PRICE / +INCOME\n-- ----------------------------------------------------------------------\nfunction CharacterLooks.BuildTag(model, char, rarity, income)\n\tlocal head = model:FindFirstChild(\"Head\") or model.PrimaryPart\n\tlocal k = rarity.TagScale or 1\n\tlocal tag = Instance.new(\"BillboardGui\")\n\ttag.Name = \"NameTag\"\n\t-- sized in studs so tags shrink with distance and don't swamp the screen\n\ttag.Size = UDim2.fromScale(6 * k, 2.6 * k)\n\ttag.StudsOffsetWorldSpace = Vector3.new(0, 2.6 + 0.6 * k, 0)\n\ttag.AlwaysOnTop = false\n\ttag.MaxDistance = rarity.Index >= 5 and 150 or (rarity.Index >= 3 and 110 or 80)\n\ttag.LightInfluence = 0\n\ttag.Parent = head\n\n\tlocal list = Instance.new(\"UIListLayout\")\n\tlist.FillDirection = Enum.FillDirection.Vertical\n\tlist.HorizontalAlignment = Enum.HorizontalAlignment.Center\n\tlist.SortOrder = Enum.SortOrder.LayoutOrder\n\tlist.Parent = tag\n\n\tlocal function line(name, order, heightScale, text, color, font)\n\t\tlocal l = Instance.new(\"TextLabel\")\n\t\tl.Name = name\n\t\tl.LayoutOrder = order\n\t\tl.Size = UDim2.new(1, 0, heightScale, 0)\n\t\tl.BackgroundTransparency = 1\n\t\tl.Font = font or Enum.Font.GothamBlack\n\t\tl.TextScaled = true\n\t\tl.TextColor3 = color\n\t\tl.Text = text\n\t\tlocal stroke = Instance.new(\"UIStroke\")\n\t\tstroke.Thickness = rarity.Index >= 4 and 2 or 1.4\n\t\tstroke.Color = Color3.new(0, 0, 0)\n\t\tstroke.Transparency = 0.15\n\t\tstroke.Parent = l\n\t\tl.Parent = tag\n\t\treturn l\n\tend\n\n\tlocal nameLabel = line(\"CharName\", 1, 0.32, char.DisplayName:upper(), Color3.new(1, 1, 1))\n\tlocal rarityLabel = line(\"Rarity\", 2, 0.22, rarity.DisplayName, rarity.Color)\n\tlocal priceLabel = line(\"Price\", 3, 0.22, \"$\" .. Constants.FormatNumber(char.Price), Color3.fromRGB(255, 240, 150), Enum.Font.GothamBold)\n\tlocal incomeLabel = line(\"Income\", 4, 0.22, \"+$\" .. Constants.FormatNumber(income) .. \"/s\", Color3.fromRGB(110, 255, 140), Enum.Font.GothamBold)\n\n\tif rarity.Gradient then\n\t\tfor _, l in ipairs({ nameLabel, rarityLabel }) do\n\t\t\tlocal g = Instance.new(\"UIGradient\")\n\t\t\tlocal keys = {}\n\t\t\tfor i, c in ipairs(rarity.Gradient) do\n\t\t\t\ttable.insert(keys, ColorSequenceKeypoint.new((i - 1) / math.max(#rarity.Gradient - 1, 1), c))\n\t\t\tend\n\t\t\tg.Color = ColorSequence.new(keys)\n\t\t\tg.Parent = l\n\t\t\tif l == nameLabel then\n\t\t\t\tl.TextColor3 = Color3.new(1, 1, 1)\n\t\t\tend\n\t\tend\n\t\ttag:SetAttribute(\"AnimatedGradient\", true)\n\telseif rarity.Index >= 2 then\n\t\tnameLabel.TextColor3 = Color3.new(1, 1, 1):Lerp(rarity.Color, 0.35)\n\tend\n\treturn tag, priceLabel, incomeLabel\nend\n\n-- ----------------------------------------------------------------------\n-- Rarity presentation (outline / aura / light)\n-- ----------------------------------------------------------------------\nlocal function rarityFx(model, char, rarity)\n\tlocal root = model:FindFirstChild(\"HumanoidRootPart\")\n\t-- no Highlight: its fill/outline washed the whole body in the rarity color\n\tif root and (rarity.Aura or 0) > 0 then\n\t\tlocal att = Instance.new(\"Attachment\")\n\t\tatt.Name = \"AuraAttachment\"\n\t\tatt.Position = Vector3.new(0, -root.Size.Y * 1.3, 0) -- around the feet\n\t\tatt.Parent = root\n\t\tlocal aura = Instance.new(\"ParticleEmitter\")\n\t\taura.Name = \"RarityAura\"\n\t\taura.Color = ColorSequence.new(rarity.Color, rarity.Glow)\n\t\taura.LightEmission = 0.5\n\t\taura.LightInfluence = 0\n\t\taura.Rate = math.min(rarity.Aura, 10)\n\t\taura.Lifetime = NumberRange.new(1.2, 2)\n\t\taura.Speed = NumberRange.new(0.4, 1.2)\n\t\taura.SpreadAngle = Vector2.new(25, 25)\n\t\taura.EmissionDirection = Enum.NormalId.Top\n\t\taura.Shape = Enum.ParticleEmitterShape.Disc\n\t\taura.ShapeStyle = Enum.ParticleEmitterShapeStyle.Surface\n\t\taura.ShapeInOut = Enum.ParticleEmitterShapeInOut.Outward\n\t\tatt.Axis = Vector3.new(1, 0, 0)\n\t\tatt.SecondaryAxis = Vector3.new(0, 0, 1)\n\t\taura.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.18), NumberSequenceKeypoint.new(1, 0) })\n\t\taura.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.35), NumberSequenceKeypoint.new(1, 1) })\n\t\taura.Acceleration = Vector3.new(0, 1.2, 0)\n\t\taura.Parent = att\n\tend\n\tlocal ut = model:FindFirstChild(\"UpperTorso\") or root\n\tif root and (rarity.Light or 0) > 0 then\n\t\t-- a soft pool of rarity-colored light on the belt, not on the skin\n\t\tlocal light = Instance.new(\"PointLight\")\n\t\tlight.Name = \"RarityLight\"\n\t\tlight.Color = rarity.Color\n\t\tlight.Brightness = math.min(rarity.Light, 3) * 0.25\n\t\tlight.Range = 6 + rarity.Index * 0.5\n\t\tlight.Shadows = false\n\t\tlight.Parent = root:FindFirstChild(\"AuraAttachment\") or root\n\tend\n\tif char.Glow and ut then\n\t\t-- \"always in perfect gym lighting\"\n\t\tlocal glow = Instance.new(\"PointLight\")\n\t\tglow.Name = \"PerfectLighting\"\n\t\tglow.Color = Color3.fromRGB(255, 244, 228)\n\t\tglow.Brightness = 0.5\n\t\tglow.Range = 8\n\t\tglow.Shadows = false\n\t\tglow.Parent = ut\n\tend\nend\n\n-- ----------------------------------------------------------------------\n-- Build a character model\n-- ----------------------------------------------------------------------\nfunction CharacterLooks.Build(char, opts)\n\topts = opts or {}\n\tlocal rarity = Characters.GetRarity(char.Rarity)\n\t-- 1) a real rigged model (uploaded asset or .rbxm), sized like the rest\n\tlocal buildH = (char.Look and char.Look.Build and char.Look.Build.Height) or 1\n\tlocal height = 5.95 * buildH * StationSpecs.SCALE\n\tlocal custom, kind = CharacterModels.Build(char, height)\n\tlocal meshData = char.Mesh and MeshCharacter.Get(char.Mesh)\n\tif custom and kind == \"Rig\" then\n\t\tcustom.Name = char.DisplayName\n\t\tlocal model = NpcService.CreateRig({ Name = char.DisplayName, Model = custom, Face = false })\n\t\treturn CharacterLooks._finish(model, char, rarity)\n\telseif custom then\n\t\t-- plain imported mesh: ride an invisible rig of the right size\n\t\tlocal rigModel\n\t\tif meshData then\n\t\t\trigModel = MeshCharacter.BuildRig(meshData)\n\t\t\trigModel:SetAttribute(\"MeshCharacter\", nil) -- the placed model is the visual\n\t\tend\n\t\tlocal model = NpcService.CreateRig({ Name = char.DisplayName, Model = rigModel, Face = false, Height = buildH })\n\t\tpcall(function()\n\t\t\tmodel:ScaleTo(model:GetScale() * height / select(2, model:GetBoundingBox()).Y)\n\t\tend)\n\t\tfor _, d in ipairs(model:GetDescendants()) do\n\t\t\tif d:IsA(\"Accessory\") or d:IsA(\"Decal\") then\n\t\t\t\td:Destroy()\n\t\t\tend\n\t\tend\n\t\tCharacterModels.AttachStatic(model, custom, char)\n\t\treturn CharacterLooks._finish(model, char, rarity)\n\tend\n\t-- 2) a baked Meshy mesh (tools/meshy/import.py)\n\tif meshData then\n\t\t-- model-based character: invisible rig here, clients add the mesh\n\t\tlocal model = NpcService.CreateRig({ Name = char.DisplayName, Model = MeshCharacter.BuildRig(meshData), Face = false })\n\t\tpcall(function()\n\t\t\tmodel:ScaleTo(StationSpecs.SCALE)\n\t\tend)\n\t\treturn CharacterLooks._finish(model, char, rarity)\n\tend\n\tlocal look = char.Look or {}\n\tlocal build = look.Build or {}\n\tlocal model = NpcService.CreateRig({\n\t\tName = char.DisplayName,\n\t\tSkin = look.Skin,\n\t\tShirt = look.Top and look.Top.Color,\n\t\tPants = look.Bottom and look.Bottom.Color,\n\t\tHeight = build.Height or 1,\n\t\tWidth = build.Width or 1,\n\t\tDepth = build.Depth or 1,\n\t\tAvatarUserId = Constants.INFLUENCER_AVATARS and Constants.INFLUENCER_AVATARS[char.Name],\n\t})\n\tlocal bodyColors = model:FindFirstChildOfClass(\"BodyColors\")\n\tif bodyColors then\n\t\tbodyColors:Destroy()\n\tend\n\tfor _, d in ipairs(model:GetDescendants()) do\n\t\tif d:IsA(\"Accessory\") then\n\t\t\td:Destroy() -- a clean base; the look is built below\n\t\tend\n\tend\n\n\tlocal folder = Instance.new(\"Folder\")\n\tfolder.Name = \"Look\"\n\tfolder.Parent = model\n\tlocal P, top, bottom = paint(model, look)\n\tlocal shape = shapeOf(build)\n\tcloth(folder, P, top, bottom, look, shape)\n\tbulk(folder, P, shape)\n\tgear(folder, P, look, shape)\n\tif P.Head then\n\t\tlocal capped = false\n\t\tfor _, pr in ipairs(look.Props or {}) do\n\t\t\tif pr == \"Cap\" then\n\t\t\t\tcapped = true\n\t\t\tend\n\t\tend\n\t\tif not capped or (look.Hair and look.Hair.Style == \"Shaggy\") then\n\t\t\thair(folder, P.Head, look)\n\t\tend\n\t\tface(folder, P.Head, look)\n\tend\n\tprops(folder, P, look)\n\tfor _, p in ipairs(folder:GetDescendants()) do\n\t\tif p:IsA(\"BasePart\") then\n\t\t\tp:SetAttribute(\"BaseTransparency\", p.Transparency)\n\t\tend\n\tend\n\n\t-- everyone is built big to match the oversized equipment; very tall\n\t-- characters get their extra height from HumanoidDescription.HeightScale\n\tpcall(function()\n\t\tmodel:ScaleTo(StationSpecs.SCALE)\n\tend)\n\n\treturn CharacterLooks._finish(model, char, rarity)\nend\n\nfunction CharacterLooks._finish(model, char, rarity)\n\trarityFx(model, char, rarity)\n\n\tmodel:SetAttribute(\"CharacterId\", char.Name)\n\tmodel:SetAttribute(\"RarityId\", char.Rarity)\n\tmodel:SetAttribute(\"Rarity\", rarity.Index)\n\tif char.Poses then\n\t\tmodel:SetAttribute(\"Poses\", table.concat(char.Poses, \",\"))\n\tend\n\tif char.Chart then\n\t\tmodel:SetAttribute(\"Chart\", true)\n\tend\n\tif char.IdleSpeed then\n\t\tmodel:SetAttribute(\"IdleSpeed\", char.IdleSpeed)\n\tend\n\tif char.Emote then\n\t\tmodel:SetAttribute(\"FavoriteEmote\", char.Emote)\n\tend\n\treturn model, rarity\nend\n\nreturn CharacterLooks\n"},{"ServerScriptService/CharacterModels","ModuleScript","--[[\n\tCharacterModels\n\tUses a real, rigged R15 model for a character when one is available,\n\tchecked in this order:\n\n\t  1. ServerStorage.CharacterModels.<ModelName>   (a .rbxm dropped into\n\t     tools/models/ is baked there by the build). Init() also collects any\n\t     model you placed in the world / ServerStorage / ReplicatedStorage\n\t     whose name contains a character's name (\"RonnieCurlman\",\n\t     \"Meshy_AI_Ronnie_Curlman_Darker\", ...) and moves it here.\n\t  2. Characters entry AssetId = <number>          (a Model asset you\n\t     uploaded; loaded with InsertService, so it must be owned by the\n\t     game's creator)\n\n\tAn R15 rig (Humanoid, HumanoidRootPart, the 15 R15 parts) is used as the\n\tcharacter's body and animates fully. Any other model (a plain imported\n\tmesh) is used as a \"Static\" visual riding an invisible rig.\n]]\n\nlocal InsertService = game:GetService(\"InsertService\")\nlocal ServerStorage = game:GetService(\"ServerStorage\")\n\nlocal Characters = require(game:GetService(\"ReplicatedStorage\").Modules.Characters)\n\nlocal CharacterModels = {}\n\nlocal function norm(s)\n\treturn (s:lower():gsub(\"[^%w]\", \"\"))\nend\n\nlocal function modelsFolder()\n\tlocal f = ServerStorage:FindFirstChild(\"CharacterModels\")\n\tif not f then\n\t\tf = Instance.new(\"Folder\")\n\t\tf.Name = \"CharacterModels\"\n\t\tf.Parent = ServerStorage\n\tend\n\treturn f\nend\n\n-- Collect hand-placed character models (by name) before anything spawns.\nfunction CharacterModels.Init()\n\tlocal folder = modelsFolder()\n\tlocal keys = {}\n\tfor _, c in ipairs(Characters.LIST) do\n\t\tlocal names = { c.ModelName, c.Name, c.DisplayName }\n\t\t-- single words of the name count too (\"GoodRonnie\" -> Ronnie Curlman)\n\t\tfor word in (c.DisplayName or \"\"):gmatch(\"%a+\") do\n\t\t\ttable.insert(names, word)\n\t\tend\n\t\tfor _, k in ipairs(names) do\n\t\t\tif k and #norm(k) >= 6 then -- short names (\"Joe\") would match random parts\n\t\t\t\ttable.insert(keys, { norm(k), c })\n\t\t\tend\n\t\tend\n\tend\n\t-- longest names first so \"RonnieCurlman\" can't be claimed by a shorter name\n\ttable.sort(keys, function(a, b)\n\t\treturn #a[1] > #b[1]\n\tend)\n\tlocal found = {}\n\tlocal map = workspace:FindFirstChild(\"GymWarsMap\")\n\tfor _, root in ipairs({ workspace, ServerStorage, game:GetService(\"ReplicatedStorage\") }) do\n\t\tfor _, d in ipairs(root:GetDescendants()) do\n\t\t\tif (d:IsA(\"Model\") or d:IsA(\"MeshPart\")) and not d:GetAttribute(\"CharacterId\") and not d:IsDescendantOf(folder)\n\t\t\t\tand not (map and d:IsDescendantOf(map)) then\n\t\t\t\tlocal n = norm(d.Name)\n\t\t\t\t-- an exact name match wins, whatever its length (\"Joe\", \"SamSulik\")\n\t\t\t\tlocal exact\n\t\t\t\tfor _, c in ipairs(Characters.LIST) do\n\t\t\t\t\tif not found[c.ModelName] and not folder:FindFirstChild(c.ModelName)\n\t\t\t\t\t\tand (n == norm(c.ModelName or \"\") or n == norm(c.Name) or n == norm(c.DisplayName)) then\n\t\t\t\t\t\texact = c\n\t\t\t\t\t\tbreak\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\t\tif exact then\n\t\t\t\t\tfound[exact.ModelName] = d\n\t\t\t\t\tcontinue\n\t\t\t\tend\n\t\t\t\tfor _, kc in ipairs(keys) do\n\t\t\t\t\tlocal c = kc[2]\n\t\t\t\t\tif not found[c.ModelName] and n:find(kc[1], 1, true) and not folder:FindFirstChild(c.ModelName) then\n\t\t\t\t\t\t-- skip parts of an already-matched model\n\t\t\t\t\t\tlocal parentMatched = false\n\t\t\t\t\t\tfor _, m in pairs(found) do\n\t\t\t\t\t\t\tif d:IsDescendantOf(m) then\n\t\t\t\t\t\t\t\tparentMatched = true\n\t\t\t\t\t\t\tend\n\t\t\t\t\t\tend\n\t\t\t\t\t\tif not parentMatched then\n\t\t\t\t\t\t\tfound[c.ModelName] = d\n\t\t\t\t\t\tend\n\t\t\t\t\t\tbreak\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\tfor modelName, inst in pairs(found) do\n\t\tprint((\"[CharacterModels] using %s for %s\"):format(inst:GetFullName(), modelName))\n\t\tlocal holder = inst\n\t\tif inst:IsA(\"MeshPart\") then\n\t\t\tholder = Instance.new(\"Model\")\n\t\t\tinst.Parent = holder\n\t\tend\n\t\tholder.Name = modelName\n\t\tholder.Parent = folder -- out of the world: it's a template now\n\tend\nend\n\nlocal REQUIRED = {\n\t\"HumanoidRootPart\", \"Head\", \"UpperTorso\", \"LowerTorso\",\n\t\"LeftUpperArm\", \"LeftLowerArm\", \"LeftHand\", \"RightUpperArm\", \"RightLowerArm\", \"RightHand\",\n\t\"LeftUpperLeg\", \"LeftLowerLeg\", \"LeftFoot\", \"RightUpperLeg\", \"RightLowerLeg\", \"RightFoot\",\n}\n\nlocal function isRig(m)\n\tif not (m:IsA(\"Model\") and m:FindFirstChildOfClass(\"Humanoid\")) then\n\t\treturn false\n\tend\n\tfor _, n in ipairs(REQUIRED) do\n\t\tif not m:FindFirstChild(n) then\n\t\t\treturn false\n\t\tend\n\tend\n\treturn true\nend\n\nlocal function findRig(root)\n\tif isRig(root) then\n\t\treturn root\n\tend\n\tfor _, d in ipairs(root:GetDescendants()) do\n\t\tif isRig(d) then\n\t\t\treturn d\n\t\tend\n\tend\n\treturn nil\nend\n\nlocal assetCache = {} -- [assetId] = rig | false | \"loading\"\n\nlocal function fromAsset(id)\n\twhile assetCache[id] == \"loading\" do\n\t\ttask.wait()\n\tend\n\tif assetCache[id] == nil then\n\t\tassetCache[id] = \"loading\"\n\t\tlocal ok, asset = pcall(function()\n\t\t\treturn InsertService:LoadAsset(id)\n\t\tend)\n\t\tlocal rig = ok and asset and findRig(asset)\n\t\tif not ok then\n\t\t\twarn((\"[CharacterModels] couldn't load asset %d: %s\"):format(id, tostring(asset)))\n\t\telseif not rig then\n\t\t\twarn((\"[CharacterModels] asset %d isn't an R15 rig (run Avatar > Auto Setup on it in Studio and upload the result)\"):format(id))\n\t\tend\n\t\tassetCache[id] = rig or false\n\tend\n\treturn assetCache[id] or nil\nend\n\n-- Does this character have a real model to spawn with? (placed/baked/asset)\nfunction CharacterModels.HasModel(char)\n\tlocal folder = ServerStorage:FindFirstChild(\"CharacterModels\")\n\tif folder and char.ModelName and folder:FindFirstChild(char.ModelName) then\n\t\treturn true\n\tend\n\tif char.AssetId then\n\t\treturn true\n\tend\n\tif char.Mesh then\n\t\tlocal assets = game:GetService(\"ReplicatedStorage\"):FindFirstChild(\"MeshAssets\")\n\t\treturn assets ~= nil and assets:FindFirstChild(char.Mesh) ~= nil\n\tend\n\treturn false\nend\n\nfunction CharacterModels.Template(char)\n\tlocal folder = ServerStorage:FindFirstChild(\"CharacterModels\")\n\tlocal stored = folder and char.ModelName and folder:FindFirstChild(char.ModelName)\n\tif stored then\n\t\tlocal rig = findRig(stored)\n\t\tif rig then\n\t\t\treturn rig, \"Rig\"\n\t\tend\n\t\treturn stored, \"Static\"\n\tend\n\tif char.AssetId then\n\t\tlocal rig = fromAsset(char.AssetId)\n\t\treturn rig, rig and \"Rig\" or nil\n\tend\n\treturn nil\nend\n\n-- Returns (model, kind): kind \"Rig\" = full R15 body, \"Static\" = visual only.\nfunction CharacterModels.Build(char, height)\n\tlocal template, kind = CharacterModels.Template(char)\n\tif not template then\n\t\treturn nil\n\tend\n\tlocal m = template:Clone()\n\tfor _, d in ipairs(m:GetDescendants()) do\n\t\tif d:IsA(\"BaseScript\") or (kind == \"Static\" and (d:IsA(\"Humanoid\") or d:IsA(\"JointInstance\") or d:IsA(\"Constraint\"))) then\n\t\t\td:Destroy() -- never run scripts that came with an asset\n\t\tend\n\tend\n\tlocal _, size = m:GetBoundingBox()\n\tif size.Y > 0.1 then\n\t\tpcall(function()\n\t\t\tm:ScaleTo(m:GetScale() * height / size.Y)\n\t\tend)\n\tend\n\tfor _, d in ipairs(m:GetDescendants()) do\n\t\tif d:IsA(\"BasePart\") then\n\t\t\td.Anchored = false\n\t\t\td.CanCollide = false\n\t\t\td.Massless = d.Name ~= \"HumanoidRootPart\"\n\t\t\tif kind == \"Static\" then\n\t\t\t\td.CanQuery = false\n\t\t\t\td.CanTouch = false\n\t\t\tend\n\t\tend\n\tend\n\treturn m, kind\nend\n\n-- Weld a static visual onto a rig: feet on the ground, centered, facing the\n-- rig's front (turn it with the character's ModelYaw, in degrees).\nfunction CharacterModels.AttachStatic(rig, visual, char)\n\tlocal hrp = rig:FindFirstChild(\"HumanoidRootPart\")\n\tlocal hum = rig:FindFirstChildOfClass(\"Humanoid\")\n\tif not (hrp and hum) then\n\t\treturn\n\tend\n\tlocal cf, size = visual:GetBoundingBox()\n\tlocal feetY = hrp.CFrame.Position.Y - hrp.Size.Y / 2 - hum.HipHeight\n\tlocal yaw = math.rad(char.ModelYaw or 0)\n\tlocal rot = (hrp.CFrame - hrp.CFrame.Position) * CFrame.Angles(0, yaw, 0)\n\t-- box center goes over the rig, keeping the way you placed the model facing\n\tlocal boxInPivot = visual:GetPivot():ToObjectSpace(cf)\n\tlocal desiredBox = CFrame.new(hrp.CFrame.Position.X, feetY + size.Y / 2, hrp.CFrame.Position.Z) * rot * (cf - cf.Position)\n\tvisual:PivotTo(desiredBox * boxInPivot:Inverse())\n\tfor _, d in ipairs(visual:GetDescendants()) do\n\t\tif d:IsA(\"BasePart\") then\n\t\t\tlocal w = Instance.new(\"WeldConstraint\")\n\t\t\tw.Part0 = hrp\n\t\t\tw.Part1 = d\n\t\t\tw.Parent = d\n\t\tend\n\tend\n\tvisual.Name = \"StaticVisual\"\n\tvisual.Parent = rig\n\tfor _, p in ipairs(rig:GetChildren()) do\n\t\tif p:IsA(\"BasePart\") then\n\t\t\tp.Transparency = 1\n\t\tend\n\tend\nend\n\nreturn CharacterModels\n"},{"ServerScriptService/GymNav","ModuleScript","--[[\n\tGymNav\n\tDeterministic routes into, through and out of the gyms, built from the\n\tinvisible Nav points every plot carries (tools/map/Gym.luau):\n\n\t  Yard -> DoorOut -> Lobby -> CrossN (center aisle at the stair path)\n\t  -> StairFootN -> LandAN -> LandBN -> StairTop(N+1) ... -> machine\n\n\tNPCs walk these point to point (NpcService.WalkTo with a route), so they\n\tnever depend on the navmesh to find the stairs.\n]]\n\nlocal GymNav = {}\n\nlocal function navOf(plotModel)\n\treturn plotModel and plotModel:FindFirstChild(\"Nav\")\nend\n\nlocal function pt(nav, name)\n\tlocal p = nav and nav:FindFirstChild(name)\n\treturn p and p.CFrame.Position or nil\nend\n\nlocal function add(route, p)\n\tif p then\n\t\ttable.insert(route, p)\n\tend\nend\n\n-- Which plot (model) is `pos` inside, and on which floor?\nfunction GymNav.Locate(pos)\n\tlocal map = workspace:FindFirstChild(\"GymWarsMap\")\n\tlocal plots = map and map:FindFirstChild(\"Plots\")\n\tif not plots then\n\t\treturn nil, 1\n\tend\n\tfor _, model in ipairs(plots:GetChildren()) do\n\t\tlocal zone = model:FindFirstChild(\"GymZone\")\n\t\tlocal nav = navOf(model)\n\t\tif zone and nav then\n\t\t\tlocal lp = zone.CFrame:PointToObjectSpace(pos)\n\t\t\tlocal h = zone.Size / 2\n\t\t\tif math.abs(lp.X) <= h.X + 1 and math.abs(lp.Z) <= h.Z + 1 and lp.Y <= h.Y and lp.Y >= -h.Y - 2 then\n\t\t\t\tlocal base = pt(nav, \"Lobby\") or zone.CFrame.Position\n\t\t\t\tlocal fy = nav:GetAttribute(\"FloorH\") or 16\n\t\t\t\tlocal rel = pos.Y - base.Y\n\t\t\t\tlocal floor = math.clamp(math.floor(rel / fy) + 1, 1, 3)\n\t\t\t\treturn model, floor\n\t\t\tend\n\t\tend\n\tend\n\treturn nil, 1\nend\n\nlocal function descend(route, nav, from, to)\n\tfor k = from, to + 1, -1 do\n\t\tadd(route, pt(nav, \"StairTop\" .. k))\n\t\tadd(route, pt(nav, \"LandB\" .. (k - 1)))\n\t\tadd(route, pt(nav, \"LandA\" .. (k - 1)))\n\t\tadd(route, pt(nav, \"StairFoot\" .. (k - 1)))\n\tend\nend\n\nlocal function ascend(route, nav, from, to)\n\tfor k = from, to - 1 do\n\t\tadd(route, pt(nav, \"StairFoot\" .. k))\n\t\tadd(route, pt(nav, \"LandA\" .. k))\n\t\tadd(route, pt(nav, \"LandB\" .. k))\n\t\tadd(route, pt(nav, \"StairTop\" .. (k + 1)))\n\tend\nend\n\n-- From a machine, first step out into the floor's walkway (center aisle on\n-- floors 1-2, the lane on floor 3) so the walk to the stairs/door is clear.\nlocal function exitToWalkway(route, nav, floor, pos, toStairs)\n\tif floor <= 2 then\n\t\tlocal cross = nav:FindFirstChild(\"Cross\" .. floor)\n\t\tif cross then\n\t\t\tlocal lp = cross.CFrame:PointToObjectSpace(pos)\n\t\t\tadd(route, cross.CFrame * Vector3.new(0, 0, lp.Z))\n\t\t\tif toStairs then\n\t\t\t\tadd(route, cross.CFrame.Position)\n\t\t\tend\n\t\tend\n\telse\n\t\tlocal lane = nav:FindFirstChild(\"F3Lane\")\n\t\tif lane then\n\t\t\tlocal lp = lane.CFrame:PointToObjectSpace(pos)\n\t\t\tlocal z = lp.Z + (lp.Z > -20 and 0.6 or 0)\n\t\t\tadd(route, lane.CFrame * Vector3.new(lp.X, 0, z))\n\t\t\tadd(route, lane.CFrame * Vector3.new(0, 0, z))\n\t\t\tadd(route, pt(nav, \"F3Lane\"))\n\t\t\tadd(route, pt(nav, \"F3Turn\"))\n\t\tend\n\tend\nend\n\n-- Route (list of Vector3, not including the final approach point) from\n-- `fromPos` to a machine on `destFloor` of `destPlot`, whose approach point\n-- is `approachPos`.\nfunction GymNav.Route(fromPos, destPlot, destFloor, approachPos)\n\tlocal route = {}\n\tlocal destNav = navOf(destPlot)\n\tif not destNav then\n\t\treturn route\n\tend\n\tlocal curPlot, curFloor = GymNav.Locate(fromPos)\n\tlocal cameViaStairsOrDoor = false\n\n\t-- leaving another gym: down to the ground floor and out the front door\n\tif curPlot and curPlot ~= destPlot then\n\t\tlocal nav = navOf(curPlot)\n\t\texitToWalkway(route, nav, curFloor, fromPos, curFloor > 1)\n\t\tif curFloor > 1 then\n\t\t\tdescend(route, nav, curFloor, 1)\n\t\t\tadd(route, pt(nav, \"Cross1\"))\n\t\tend\n\t\tadd(route, pt(nav, \"Lobby\"))\n\t\tadd(route, pt(nav, \"DoorOut\"))\n\t\tadd(route, pt(nav, \"Yard\"))\n\t\tcurPlot, curFloor = nil, 1\n\tend\n\n\t-- outside: across the lawn and in through the door\n\tif not curPlot then\n\t\tadd(route, pt(destNav, \"Yard\"))\n\t\tadd(route, pt(destNav, \"DoorOut\"))\n\t\tadd(route, pt(destNav, \"Lobby\"))\n\t\tcurFloor = 1\n\t\tcameViaStairsOrDoor = true\n\tend\n\n\tif curFloor ~= destFloor and not cameViaStairsOrDoor then\n\t\t-- already inside this gym on another floor: out to the walkway first\n\t\texitToWalkway(route, destNav, curFloor, fromPos, true)\n\tend\n\tif curFloor < destFloor then\n\t\tadd(route, pt(destNav, \"Cross\" .. curFloor))\n\t\tascend(route, destNav, curFloor, destFloor)\n\t\tcameViaStairsOrDoor = true\n\telseif curFloor > destFloor then\n\t\tdescend(route, destNav, curFloor, destFloor)\n\t\tcameViaStairsOrDoor = true\n\tend\n\n\t-- last stretch on the machine's floor: along the center aisle to the\n\t-- machine's row, then across to it (floors 1-2 have a center aisle;\n\t-- floor 3 is open rows, so the final steer handles it)\n\tif cameViaStairsOrDoor and destFloor <= 2 and approachPos then\n\t\tlocal lobby = pt(destNav, \"Lobby\")\n\t\tlocal cross = pt(destNav, \"Cross\" .. destFloor)\n\t\tif destFloor > 1 or curFloor ~= 1 then\n\t\t\tadd(route, cross)\n\t\tend\n\t\tif lobby and cross then\n\t\t\t-- a point on the center aisle level with the machine\n\t\t\tlocal aisleCF = destNav:FindFirstChild(\"Cross\" .. destFloor).CFrame\n\t\t\tlocal lp = aisleCF:PointToObjectSpace(approachPos)\n\t\t\tadd(route, aisleCF * Vector3.new(0, 0, lp.Z))\n\t\tend\n\telseif destFloor == 3 and cameViaStairsOrDoor and approachPos then\n\t\t-- off the stairs, behind the benches, down the lane, across to the row\n\t\tlocal lane = destNav:FindFirstChild(\"F3Lane\")\n\t\tadd(route, pt(destNav, \"F3Turn\"))\n\t\tadd(route, pt(destNav, \"F3Lane\"))\n\t\tif lane then\n\t\t\tlocal lp = lane.CFrame:PointToObjectSpace(approachPos)\n\t\t\t-- walk the row a little on the open side of the machine\n\t\t\tlocal z = lp.Z + (lp.Z > -20 and 0.6 or 0)\n\t\t\tadd(route, lane.CFrame * Vector3.new(0, 0, z))\n\t\t\tadd(route, lane.CFrame * Vector3.new(lp.X, 0, z))\n\t\tend\n\tend\n\treturn route\nend\n\nreturn GymNav\n"},{"ServerScriptService/InfluencerService","ModuleScript","--[[\n\tInfluencerService\n\tOwns every influencer NPC (a real R15 character) and its lifecycle:\n\n\t  OnBelt    -> walking down the red carpet (claimable by anyone)\n\t  Seating   -> claimed: walking on their own, straight to a machine in the\n\t               claimer's gym (the machine is reserved the moment they're claimed)\n\t  Placed    -> training on a machine (anchored; clients animate the workout),\n\t               earning Cash for the plot owner\n\t  Stolen    -> lured out of someone else's gym, walking to a machine in the\n\t               thief's gym; the victim's front desk worker chases them\n\t  Returning -> walking back to their machine after the front desk caught them\n\t  Dropped   -> standing around unowned (knocked off the belt), claimable, leaves later\n\n\tStealing keeps OriginPlotId/OriginSlot reserved so a caught influencer can\n\twalk back; if they reach the thief's machine first, they're the thief's.\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal SSS = game:GetService(\"ServerScriptService\")\n\nlocal Constants = require(RS.Modules.Constants)\nlocal PlayerDataService = require(SSS.PlayerDataService)\nlocal PlotService = require(SSS.PlotService)\nlocal NpcService = require(SSS.NpcService)\nlocal GymNav = require(SSS.GymNav)\nlocal Characters = require(RS.Modules.Characters)\nlocal CharacterLooks = require(SSS.CharacterLooks)\nlocal Notify = require(SSS.Notify)\n\nlocal InfluencerService = {}\n\n-- Callbacks set by DefenseService\nInfluencerService.OnTheftStarted = nil -- function(rec, thiefPlayer, victimPlot)\nInfluencerService.OnTheftEnded = nil -- function(rec, victimPlot)\n-- Set by BeltService (purchase effects)\nInfluencerService.OnPurchased = nil -- function(rec, buyer)\n\nlocal records = {} -- [model] = rec\nlocal rackFullDebounce = {} -- [userId] = os.clock()\nlocal folder = nil\nlocal rng = Random.new()\n\n-- ----------------------------------------------------------------------\n-- Model construction\n-- ----------------------------------------------------------------------\nlocal function buildModel(rec)\n\tlocal model = CharacterLooks.Build(rec.Char)\n\tlocal root = model:FindFirstChild(\"HumanoidRootPart\")\n\tlocal _, priceLabel, incomeLabel = CharacterLooks.BuildTag(model, rec.Char, rec.RarityDef, rec.Income)\n\n\tlocal prompt = Instance.new(\"ProximityPrompt\")\n\tprompt.Name = \"GrabPrompt\"\n\tprompt.ActionText = \"Buy $\" .. Constants.FormatNumber(rec.Price)\n\tprompt.ObjectText = rec.Name\n\tprompt.HoldDuration = rec.RarityDef.Index >= 5 and 0.6 or Constants.BELT.ClaimHold\n\tprompt.MaxActivationDistance = Constants.BELT.ClaimDistance\n\tprompt.RequiresLineOfSight = false\n\tprompt.Parent = root\n\n\tlocal stationRef = Instance.new(\"ObjectValue\")\n\tstationRef.Name = \"Station\"\n\tstationRef.Parent = model\n\n\tmodel:SetAttribute(\"Income\", rec.Income)\n\tmodel:SetAttribute(\"Price\", rec.Price)\n\tmodel:SetAttribute(\"Seed\", rec.Seed)\n\tmodel:SetAttribute(\"Mutation\", rec.Mutation or \"None\")\n\tmodel:SetAttribute(\"State\", rec.State)\n\tmodel:SetAttribute(\"OwnerUserId\", 0)\n\n\trec.Model = model\n\trec.Root = root\n\trec.Humanoid = model:FindFirstChildOfClass(\"Humanoid\")\n\trec.Prompt = prompt\n\trec.PriceLabel = priceLabel\n\trec.IncomeLabel = incomeLabel\n\trec.StationRef = stationRef\n\trecords[model] = rec\n\n\tprompt.Triggered:Connect(function(player)\n\t\tInfluencerService.OnGrab(player, rec)\n\tend)\n\treturn model\nend\n\nlocal function setState(rec, state)\n\trec.State = state\n\tif rec.Model then\n\t\trec.Model:SetAttribute(\"State\", state)\n\t\tlocal forSale = state == \"OnBelt\" or state == \"Dropped\"\n\t\tif rec.Prompt then\n\t\t\trec.Prompt.Enabled = forSale or state == \"Placed\"\n\t\t\trec.Prompt.ActionText = state == \"Placed\" and \"Steal\" or (\"Buy $\" .. Constants.FormatNumber(rec.Price))\n\t\tend\n\t\tif rec.PriceLabel then\n\t\t\trec.PriceLabel.Visible = forSale\n\t\tend\n\t\tCharacterLooks.SetPropsVisible(rec.Model, state ~= \"Placed\")\n\tend\nend\n\nlocal function setAnchored(rec, anchored)\n\tif rec.Root then\n\t\trec.Root.Anchored = anchored\n\t\tif rec.Humanoid then\n\t\t\trec.Humanoid.PlatformStand = anchored\n\t\tend\n\t\tif not anchored then\n\t\t\tNpcService.Activate(rec.Model)\n\t\tend\n\tend\nend\n\n-- ----------------------------------------------------------------------\n-- Profile helpers (persist placed influencers)\n-- ----------------------------------------------------------------------\nlocal function removeFromProfile(player, slot)\n\tlocal profile = PlayerDataService.GetProfile(player.UserId)\n\tif not profile then\n\t\treturn\n\tend\n\tfor i = #profile.Placed, 1, -1 do\n\t\tif profile.Placed[i].Slot == slot then\n\t\t\ttable.remove(profile.Placed, i)\n\t\tend\n\tend\nend\n\nlocal function addToProfile(player, rec)\n\tlocal profile = PlayerDataService.GetProfile(player.UserId)\n\tif not profile then\n\t\treturn\n\tend\n\tremoveFromProfile(player, rec.Slot)\n\ttable.insert(profile.Placed, { Id = rec.Id, Slot = rec.Slot, Seed = rec.Seed, Mutation = rec.Mutation })\nend\n\nlocal function refreshRackAttr(plot)\n\tlocal owner = PlotService.GetOwnerPlayer(plot)\n\tif owner then\n\t\towner:SetAttribute(\"RackUsed\", PlotService.CountPlaced(plot.Id))\n\t\towner:SetAttribute(\"RackSlots\", plot.Unlocked)\n\tend\nend\n\n-- ----------------------------------------------------------------------\n-- Getting to a machine\n-- ----------------------------------------------------------------------\n-- Get off a machine: stand upright at the machine's approach point, unanchored.\nlocal function standUp(rec)\n\tlocal station = rec.StationRef.Value\n\tlocal approach = station and station:FindFirstChild(\"Approach\")\n\tlocal pos = approach and approach.Position or rec.Root.Position\n\tlocal look = rec.Root.CFrame.LookVector * Vector3.new(1, 0, 1)\n\tif look.Magnitude < 0.1 then\n\t\tlook = Vector3.new(0, 0, -1)\n\tend\n\trec.Model:PivotTo(CFrame.lookAt(pos + Vector3.new(0, 4, 0), pos + Vector3.new(0, 4, 0) + look.Unit))\n\tsetAnchored(rec, false)\n\tNpcService.SetAnimationsEnabled(rec.Model, true)\n\trec.StationRef.Value = nil\nend\n\n-- Anchor the NPC on its machine; clients take over and animate the workout.\nlocal function sitOnStation(rec, plot, slot, timeOffset)\n\tlocal station = PlotService.GetStation(plot.Id, slot)\n\tsetState(rec, \"Placed\")\n\trec.PlotId = plot.Id\n\trec.Slot = slot\n\trec.Arrive = nil\n\tplot.Slots[slot] = rec\n\tNpcService.Stop(rec.Model)\n\tNpcService.SetAnimationsEnabled(rec.Model, false)\n\tif station then\n\t\tlocal rider = station:FindFirstChild(\"Rider\")\n\t\tsetAnchored(rec, true)\n\t\trec.Root.CFrame = rider and rider.CFrame or station:GetPivot()\n\t\trec.StationRef.Value = station\n\tend\n\trec.Model:SetAttribute(\"OwnerUserId\", plot.OwnerUserId)\n\t-- clients animate from this timestamp (offset = start mid-workout, e.g. after a rejoin)\n\trec.Model:SetAttribute(\"SeatedAt\", workspace:GetServerTimeNow() - (timeOffset or 0))\n\trefreshRackAttr(plot)\nend\n\n-- Walk (on their own) to a machine's approach point; `onArrive` runs when\n-- they get there, or after the timeout if they got stuck (they then just hop on).\nlocal function walkTo(rec, plot, slot, speed, onArrive)\n\tlocal station = PlotService.GetStation(plot.Id, slot)\n\tlocal approach = station and station:FindFirstChild(\"Approach\")\n\tlocal token = {}\n\trec.SeatToken = token\n\tlocal function arrive()\n\t\tif rec.SeatToken == token and rec.Model then\n\t\t\trec.SeatToken = nil\n\t\t\tonArrive()\n\t\tend\n\tend\n\trec.Arrive = arrive\n\tif rec.Root.Anchored then\n\t\tstandUp(rec)\n\tend\n\tif not approach then\n\t\ttask.defer(arrive)\n\t\treturn\n\tend\n\t-- fixed route: lawn -> door -> aisle -> stairs -> landing -> right floor\n\tlocal route = GymNav.Route(rec.Root.Position, plot.Model, station:GetAttribute(\"Floor\") or 1, approach.Position)\n\tNpcService.WalkTo(rec.Model, approach.Position, speed, arrive, Constants.NPC.SeatTimeout, arrive, route)\nend\n\n-- Reserve `slot` in `plot` for rec and send them there.\nlocal function sendToOwnMachine(rec, plot, slot, speed, state)\n\tsetState(rec, state or \"Seating\")\n\trec.PlotId = plot.Id\n\trec.Slot = slot\n\tplot.Slots[slot] = rec -- reserved right away\n\trec.Model:SetAttribute(\"OwnerUserId\", plot.OwnerUserId)\n\trefreshRackAttr(plot)\n\twalkTo(rec, plot, slot, speed, function()\n\t\tif plot.Slots[slot] == rec then\n\t\t\tsitOnStation(rec, plot, slot)\n\t\t\tlocal owner = PlotService.GetOwnerPlayer(plot)\n\t\t\tif owner and state ~= \"Returning\" then\n\t\t\t\taddToProfile(owner, rec)\n\t\t\tend\n\t\tend\n\tend)\nend\n\nlocal function dropHere(rec)\n\tsetState(rec, \"Dropped\")\n\trec.PlotId = nil\n\trec.Slot = nil\n\trec.SeatToken = nil\n\trec.Arrive = nil\n\trec.DroppedAt = os.clock()\n\trec.Model:SetAttribute(\"OwnerUserId\", 0)\n\tif rec.Root.Anchored then\n\t\tstandUp(rec)\n\tend\n\trec.StationRef.Value = nil\n\tNpcService.Stop(rec.Model)\nend\n\n-- ----------------------------------------------------------------------\n-- Public: spawning / destroying\n-- ----------------------------------------------------------------------\nfunction InfluencerService.Init()\n\tfolder = workspace:FindFirstChild(\"Influencers\")\n\tif not folder then\n\t\tfolder = Instance.new(\"Folder\")\n\t\tfolder.Name = \"Influencers\"\n\t\tfolder.Parent = workspace\n\tend\n\n\tRunService.Heartbeat:Connect(function(dt)\n\t\tInfluencerService.Update(dt)\n\tend)\nend\n\nlocal function newRecord(char, seed, state, mutation)\n\tlocal rarity = Characters.GetRarity(char.Rarity)\n\treturn {\n\t\tChar = char,\n\t\tId = char.Name,\n\t\tName = char.DisplayName,\n\t\tRarityDef = rarity,\n\t\tRarity = rarity.Index,\n\t\tPrice = char.Price,\n\t\tMutation = mutation,\n\t\tIncome = Characters.GetIncome(char.Name, mutation),\n\t\tSeed = seed or rng:NextInteger(1, 2 ^ 30),\n\t\tState = state,\n\t}\nend\n\n-- Spawn a character at `spawnCF`, facing down the carpet (+Z); BeltService walks them.\nfunction InfluencerService.Spawn(char, spawnCF)\n\tlocal rec = newRecord(char, nil, \"OnBelt\")\n\tlocal model = buildModel(rec)\n\tsetState(rec, \"OnBelt\")\n\tlocal pos = spawnCF.Position\n\tmodel:PivotTo(CFrame.lookAt(pos, pos + Vector3.new(0, 0, 1)))\n\tmodel.Parent = folder\n\tNpcService.Activate(model)\n\treturn rec\nend\n\nfunction InfluencerService.Destroy(rec)\n\tif not rec or not rec.Model then\n\t\treturn\n\tend\n\trec.SeatToken = nil\n\tif rec.PlotId and rec.Slot then\n\t\tlocal plot = PlotService.GetPlotById(rec.PlotId)\n\t\tif plot and plot.Slots[rec.Slot] == rec then\n\t\t\tplot.Slots[rec.Slot] = nil\n\t\t\trefreshRackAttr(plot)\n\t\tend\n\tend\n\tif rec.OriginPlotId and rec.OriginSlot then\n\t\tlocal plot = PlotService.GetPlotById(rec.OriginPlotId)\n\t\tif plot and plot.Slots[rec.OriginSlot] == rec then\n\t\t\tplot.Slots[rec.OriginSlot] = nil\n\t\t\trefreshRackAttr(plot)\n\t\tend\n\tend\n\tNpcService.Forget(rec.Model)\n\trecords[rec.Model] = nil\n\trec.Model:Destroy()\n\trec.Model = nil\nend\n\nfunction InfluencerService.GetAllOnBelt()\n\tlocal list = {}\n\tfor _, rec in pairs(records) do\n\t\tif rec.State == \"OnBelt\" then\n\t\t\ttable.insert(list, rec)\n\t\tend\n\tend\n\treturn list\nend\n\nfunction InfluencerService.CountOnBelt()\n\tlocal n = 0\n\tfor _, rec in pairs(records) do\n\t\tif rec.State == \"OnBelt\" then\n\t\t\tn += 1\n\t\tend\n\tend\n\treturn n\nend\n\n-- ----------------------------------------------------------------------\n-- Public: grabbing (claim or steal)\n-- ----------------------------------------------------------------------\nlocal function fullNotice(player)\n\tlocal now = os.clock()\n\tif not rackFullDebounce[player.UserId] or now - rackFullDebounce[player.UserId] > 2 then\n\t\trackFullDebounce[player.UserId] = now\n\t\tNotify(player, \"Every machine on your open floors is taken! Buy another Gym Floor in the Shop.\", \"fail\")\n\tend\nend\n\nfunction InfluencerService.OnGrab(player, rec)\n\tif not rec.Model then\n\t\treturn\n\tend\n\tlocal uid = player.UserId\n\tif player:GetAttribute(\"Stunned\") then\n\t\treturn\n\tend\n\t-- server-side range check (prompts are client-evaluated)\n\tlocal char = player.Character\n\tlocal hrp = char and char:FindFirstChild(\"HumanoidRootPart\")\n\tif not hrp or (hrp.Position - rec.Root.Position).Magnitude > Constants.BELT.ClaimDistance + 8 then\n\t\treturn\n\tend\n\tlocal myPlot = PlotService.GetPlotByOwner(uid)\n\tif not myPlot then\n\t\tNotify(player, \"All gyms are taken — you need a gym to hold influencers.\", \"fail\")\n\t\treturn\n\tend\n\n\tif rec.State == \"OnBelt\" or rec.State == \"Dropped\" then\n\t\tlocal slot = PlotService.FindOpenSlot(myPlot.Id)\n\t\tif not slot then\n\t\t\tfullNotice(player)\n\t\t\treturn\n\t\tend\n\t\t-- BUY\n\t\tlocal profile = PlayerDataService.GetProfile(uid)\n\t\tif not profile or profile.Cash < rec.Price then\n\t\t\tNotify(player, \"You need $\" .. Constants.FormatNumber(rec.Price) .. \" to buy \" .. rec.Name .. \".\", \"fail\")\n\t\t\treturn\n\t\tend\n\t\tPlayerDataService.AddCash(player, -rec.Price)\n\t\tif InfluencerService.OnPurchased then\n\t\t\tInfluencerService.OnPurchased(rec, player)\n\t\tend\n\t\tlocal wasOnBelt = rec.State == \"OnBelt\"\n\t\trec.CarrierUserId = uid\n\t\tif wasOnBelt and rec.Humanoid then\n\t\t\trec.Humanoid:Move(Vector3.zero) -- stop parading; the walk to the gym takes over\n\t\tend\n\t\tsendToOwnMachine(rec, myPlot, slot, Constants.NPC.TravelSpeed)\n\t\tlocal station = PlotService.GetStation(myPlot.Id, slot)\n\t\tNotify(player, \"Bought \" .. rec.Name .. \" for $\" .. Constants.FormatNumber(rec.Price) .. \"! Heading to your \" .. (station and PlotService.StationName(station) or \"gym\") .. \" (+$\" .. Constants.FormatNumber(rec.Income) .. \"/s)\", \"success\")\n\t\treturn\n\tend\n\n\tif rec.State == \"Placed\" then\n\t\tlocal plot = PlotService.GetPlotById(rec.PlotId)\n\t\tif not plot then\n\t\t\treturn\n\t\tend\n\t\tif plot.OwnerUserId == uid then\n\t\t\tNotify(player, rec.Name .. \" is already training at your gym.\", \"info\")\n\t\t\treturn\n\t\tend\n\t\tlocal slot = PlotService.FindOpenSlot(myPlot.Id)\n\t\tif not slot then\n\t\t\tfullNotice(player)\n\t\t\treturn\n\t\tend\n\t\t-- THEFT: keep the origin slot reserved so it can return if the front desk catches them\n\t\trec.OriginPlotId = plot.Id\n\t\trec.OriginSlot = rec.Slot\n\t\trec.CarrierUserId = uid\n\t\tmyPlot.Slots[slot] = rec\n\t\trec.PlotId = myPlot.Id\n\t\trec.Slot = slot\n\t\tsetState(rec, \"Stolen\")\n\t\trec.Model:SetAttribute(\"OwnerUserId\", uid)\n\t\trefreshRackAttr(plot)\n\t\trefreshRackAttr(myPlot)\n\t\twalkTo(rec, myPlot, slot, Constants.NPC.TravelSpeed, function()\n\t\t\tInfluencerService.FinishTheft(rec)\n\t\tend)\n\n\t\tlocal victim = PlotService.GetOwnerPlayer(plot)\n\t\tNotify(player, \"You lured \" .. rec.Name .. \" away! They're heading to your gym — hope the front desk doesn't catch them!\", \"info\")\n\t\tif victim then\n\t\t\tNotify(victim, player.DisplayName .. \" is stealing your \" .. rec.Name .. \"! Your front desk is on it!\", \"fail\")\n\t\tend\n\t\tif InfluencerService.OnTheftStarted then\n\t\t\tInfluencerService.OnTheftStarted(rec, player, plot)\n\t\tend\n\tend\nend\n\nfunction InfluencerService.GetCarried(player)\n\treturn nil\nend\n\nfunction InfluencerService.GetCarrierPlayer(rec)\n\treturn rec.CarrierUserId and Players:GetPlayerByUserId(rec.CarrierUserId) or nil\nend\n\n-- ----------------------------------------------------------------------\n-- Public: theft outcomes\n-- ----------------------------------------------------------------------\n-- The stolen influencer reached the thief's machine: it's theirs now.\nfunction InfluencerService.FinishTheft(rec)\n\tlocal plot = rec.PlotId and PlotService.GetPlotById(rec.PlotId)\n\tlocal slot = rec.Slot\n\tif not plot or plot.Slots[slot] ~= rec then\n\t\tInfluencerService.ReturnToOrigin(rec)\n\t\treturn\n\tend\n\tlocal originPlot = rec.OriginPlotId and PlotService.GetPlotById(rec.OriginPlotId)\n\tif originPlot then\n\t\tif originPlot.Slots[rec.OriginSlot] == rec then\n\t\t\toriginPlot.Slots[rec.OriginSlot] = nil\n\t\tend\n\t\tlocal victim = PlotService.GetOwnerPlayer(originPlot)\n\t\tlocal thief = PlotService.GetOwnerPlayer(plot)\n\t\tif victim then\n\t\t\tremoveFromProfile(victim, rec.OriginSlot)\n\t\t\tNotify(victim, (thief and thief.DisplayName or \"Someone\") .. \" stole your \" .. rec.Name .. \"!\", \"fail\")\n\t\tend\n\t\trefreshRackAttr(originPlot)\n\t\tif InfluencerService.OnTheftEnded then\n\t\t\tInfluencerService.OnTheftEnded(rec, originPlot)\n\t\tend\n\tend\n\trec.OriginPlotId = nil\n\trec.OriginSlot = nil\n\tsitOnStation(rec, plot, slot)\n\tlocal owner = PlotService.GetOwnerPlayer(plot)\n\tif owner then\n\t\taddToProfile(owner, rec)\n\t\tNotify(owner, rec.Name .. \" joined your gym! +$\" .. Constants.FormatNumber(rec.Income) .. \"/s\", \"success\")\n\tend\nend\n\n-- Front desk caught them (or the thief left): walk back to the original machine.\nfunction InfluencerService.ReturnToOrigin(rec)\n\tlocal originPlot = rec.OriginPlotId and PlotService.GetPlotById(rec.OriginPlotId)\n\tlocal originSlot = rec.OriginSlot\n\t-- free the thief's reserved machine\n\tif rec.PlotId and rec.Slot then\n\t\tlocal plot = PlotService.GetPlotById(rec.PlotId)\n\t\tif plot and plot.Slots[rec.Slot] == rec and plot ~= originPlot then\n\t\t\tplot.Slots[rec.Slot] = nil\n\t\t\trefreshRackAttr(plot)\n\t\tend\n\tend\n\trec.OriginPlotId = nil\n\trec.OriginSlot = nil\n\trec.CarrierUserId = nil\n\tNpcService.Stop(rec.Model)\n\n\tif originPlot and originPlot.OwnerUserId ~= 0 and originPlot.Slots[originSlot] == rec then\n\t\tsendToOwnMachine(rec, originPlot, originSlot, Constants.NPC.ReturnSpeed, \"Returning\")\n\telse\n\t\tdropHere(rec)\n\tend\n\tif InfluencerService.OnTheftEnded and originPlot then\n\t\tInfluencerService.OnTheftEnded(rec, originPlot)\n\tend\nend\n\n-- Knocked off the conveyor: stand around (claimable) and leave after a while.\nfunction InfluencerService.DropFromBelt(rec)\n\tif rec.Model and rec.State == \"OnBelt\" then\n\t\tdropHere(rec)\n\tend\nend\n\n-- The player left / rebirthed: anything they were stealing goes back home.\nfunction InfluencerService.DropCarried(player)\n\tfor _, rec in pairs(records) do\n\t\tif rec.State == \"Stolen\" and rec.CarrierUserId == player.UserId then\n\t\t\tInfluencerService.ReturnToOrigin(rec)\n\t\tend\n\tend\nend\n\n-- Destroys every influencer placed on / walking to a plot (does NOT touch the profile).\nfunction InfluencerService.ClearPlot(plot)\n\tfor slot, rec in pairs(plot.Slots) do\n\t\tif rec and rec.Model then\n\t\t\tif rec.State == \"Stolen\" and rec.OriginPlotId == plot.Id then\n\t\t\t\t-- being stolen FROM this plot: it's gone for good, the thief keeps walking\n\t\t\t\trec.OriginPlotId, rec.OriginSlot = nil, nil\n\t\t\telseif rec.State == \"Stolen\" then\n\t\t\t\tInfluencerService.ReturnToOrigin(rec) -- was being stolen BY this plot's owner\n\t\t\telse\n\t\t\t\tInfluencerService.Destroy(rec)\n\t\t\tend\n\t\tend\n\t\tplot.Slots[slot] = nil\n\tend\n\trefreshRackAttr(plot)\nend\n\n-- Rebuilds a player's saved gym when they join.\nfunction InfluencerService.RestorePlaced(player, plot)\n\tlocal profile = PlayerDataService.GetProfile(player.UserId)\n\tif not profile then\n\t\treturn 0\n\tend\n\tlocal restored = 0\n\tfor _, entry in ipairs(profile.Placed) do\n\t\tlocal slot = entry.Slot\n\t\t-- saves store the character id; very old saves stored a rarity index + name\n\t\tlocal char = entry.Id and Characters.Get(entry.Id)\n\t\tif not char and entry.Rarity then\n\t\t\tchar = Characters.DefaultForRarityIndex(entry.Rarity)\n\t\t\tentry.Id = char and char.Name\n\t\tend\n\t\tif slot and slot <= plot.Unlocked and not plot.Slots[slot] and char then\n\t\t\tlocal rec = newRecord(char, entry.Seed, \"Placed\", entry.Mutation)\n\t\t\tentry.Seed = rec.Seed\n\t\t\tentry.Rarity, entry.Name = nil, nil\n\t\t\tlocal model = buildModel(rec)\n\t\t\tmodel.Parent = folder\n\t\t\tsitOnStation(rec, plot, slot, rng:NextNumber(0, 30))\n\t\t\trestored += 1\n\t\tend\n\tend\n\treturn restored\nend\n\n-- ----------------------------------------------------------------------\n-- Heartbeat\n-- ----------------------------------------------------------------------\nlocal tickAccum = 0\nlocal despawnAccum = 0\n\nfunction InfluencerService.Update(dt)\n\ttickAccum += dt\n\tif tickAccum >= 0.25 then\n\t\ttickAccum = 0\n\t\t-- fell off the world while walking? just finish the trip\n\t\tfor _, rec in pairs(records) do\n\t\t\tif rec.Root and rec.Root.Position.Y < -40 then\n\t\t\t\tif rec.Arrive then\n\t\t\t\t\ttask.defer(rec.Arrive)\n\t\t\t\telse\n\t\t\t\t\ttask.defer(InfluencerService.Destroy, rec)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\t-- dropped: leave after a while (checked ~once per second)\n\tdespawnAccum += dt\n\tif despawnAccum >= 1 then\n\t\tdespawnAccum = 0\n\t\tlocal now = os.clock()\n\t\tfor _, rec in pairs(records) do\n\t\t\tif rec.State == \"Dropped\" and rec.DroppedAt and now - rec.DroppedAt > Constants.BELT.DroppedDespawn then\n\t\t\t\ttask.defer(InfluencerService.Destroy, rec)\n\t\t\tend\n\t\tend\n\tend\nend\n\nreturn InfluencerService\n"},{"ServerScriptService/Main","Script","--[[\n\tGYM WARS — server bootstrap\n\tWires every service together and handles join / leave / respawn.\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal SSS = game:GetService(\"ServerScriptService\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\n\nlocal Constants = require(RS.Modules.Constants)\nlocal PlayerDataService = require(SSS.PlayerDataService)\nlocal PlotService = require(SSS.PlotService)\nlocal InfluencerService = require(SSS.InfluencerService)\nlocal BeltService = require(SSS.BeltService)\nlocal EconomyService = require(SSS.EconomyService)\nlocal WorkoutService = require(SSS.WorkoutService)\nlocal ShopService = require(SSS.ShopService)\nlocal DefenseService = require(SSS.DefenseService)\nlocal NpcService = require(SSS.NpcService)\nlocal EnvironmentService = require(SSS.EnvironmentService)\nlocal Notify = require(SSS.Notify)\nlocal CharacterModels = require(SSS.CharacterModels)\n\n-- ----------------------------------------------------------------------\n-- Init order matters: plots first (everything hangs off them)\n-- ----------------------------------------------------------------------\nCharacterModels.Init() -- before anything spawns\n-- only characters with a real model walk the carpet (Characters.ONLY_WITH_MODELS)\nrequire(RS.Modules.Characters).Filter = CharacterModels.HasModel\nEnvironmentService.Init()\nNpcService.Init()\nPlotService.Init()\nInfluencerService.Init()\nDefenseService.Init()\nBeltService.Init()\nEconomyService.Init()\nWorkoutService.Init()\nShopService.Init()\n\n-- ----------------------------------------------------------------------\nlocal function onCharacterAdded(player, character)\n\t-- players never collide with NPCs (influencers / front desk) so nobody gets body-blocked\n\tNpcService.SetGroup(character, NpcService.GROUP_PLAYERS)\n\tcharacter.DescendantAdded:Connect(function(d)\n\t\tif d:IsA(\"BasePart\") then\n\t\t\td.CollisionGroup = NpcService.GROUP_PLAYERS\n\t\tend\n\tend)\n\tlocal humanoid = character:WaitForChild(\"Humanoid\", 10)\n\tif humanoid then\n\t\thumanoid.WalkSpeed = Constants.NORMAL_WALKSPEED\n\tend\n\tplayer:SetAttribute(\"Stunned\", false)\n\tplayer:SetAttribute(\"Carrying\", \"\")\n\n\tlocal plot = PlotService.GetPlotByOwner(player.UserId)\n\tif plot then\n\t\tcharacter:WaitForChild(\"HumanoidRootPart\", 10)\n\t\ttask.wait() -- let the default spawn finish before moving\n\t\tPlotService.TeleportToPlot(player, plot)\n\tend\nend\n\nlocal function onPlayerAdded(player)\n\tlocal profile = PlayerDataService.LoadPlayer(player)\n\tlocal plot = PlotService.AssignPlot(player)\n\n\tif plot then\n\t\tlocal floorLevel = profile.Equipment.Floors or 1\n\t\tlocal slots = Constants.EQUIPMENT.Floors.Values[floorLevel] or Constants.EQUIPMENT.Floors.Values[1]\n\t\tPlotService.RefreshSlots(plot.Id, slots)\n\t\tPlotService.ApplyColor(plot.Id, profile.GymColor or 3)\n\t\tlocal restored = InfluencerService.RestorePlaced(player, plot)\n\t\tplayer:SetAttribute(\"RackSlots\", slots)\n\t\tplayer:SetAttribute(\"RackUsed\", PlotService.CountPlaced(plot.Id))\n\t\ttask.delay(3, function()\n\t\t\tif restored > 0 then\n\t\t\t\tNotify(player, \"Welcome back! \" .. restored .. \" influencers are still training at your gym.\", \"success\")\n\t\t\telse\n\t\t\t\tNotify(player, \"Claim influencers off the red carpet and lead them to your gym!\", \"info\")\n\t\t\tend\n\t\tend)\n\telse\n\t\ttask.delay(3, function()\n\t\t\tNotify(player, \"Server is full of gyms — you can still explore, but you need a gym to earn.\", \"fail\")\n\t\tend)\n\tend\n\n\tplayer.CharacterAdded:Connect(function(character)\n\t\tonCharacterAdded(player, character)\n\tend)\n\tif player.Character then\n\t\ttask.spawn(onCharacterAdded, player, player.Character)\n\tend\nend\n\nlocal function onPlayerRemoving(player)\n\tInfluencerService.DropCarried(player)\n\n\tlocal plot = PlotService.GetPlotByOwner(player.UserId)\n\tlocal profile = PlayerDataService.GetProfile(player.UserId)\n\tif plot and profile then\n\t\t-- anything being lured out of this gym right now is gone for good\n\t\tfor slot, rec in pairs(plot.Slots) do\n\t\t\tif rec and rec.State == \"Stolen\" and rec.OriginPlotId == plot.Id then\n\t\t\t\tfor i = #profile.Placed, 1, -1 do\n\t\t\t\t\tif profile.Placed[i].Slot == slot then\n\t\t\t\t\t\ttable.remove(profile.Placed, i)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\tPlayerDataService.SaveData(player)\n\n\tif plot then\n\t\tInfluencerService.ClearPlot(plot)\n\t\tDefenseService.ResetPlot(plot)\n\t\tPlotService.ReleasePlot(player)\n\tend\n\n\tEconomyService.ClearPlayer(player)\n\tWorkoutService.ClearPlayer(player)\n\tShopService.ClearPlayer(player)\n\tPlayerDataService.Cleanup(player)\nend\n\nRS.Remotes.DismissFollower.OnServerEvent:Connect(function(player)\n\tInfluencerService.DropCarried(player)\nend)\n\nPlayers.PlayerAdded:Connect(onPlayerAdded)\nPlayers.PlayerRemoving:Connect(onPlayerRemoving)\nfor _, player in ipairs(Players:GetPlayers()) do\n\ttask.spawn(onPlayerAdded, player)\nend\n\n-- ----------------------------------------------------------------------\n-- Autosave + shutdown save\n-- ----------------------------------------------------------------------\ntask.spawn(function()\n\twhile true do\n\t\ttask.wait(Constants.AUTOSAVE_INTERVAL)\n\t\tPlayerDataService.SaveAll()\n\tend\nend)\n\ngame:BindToClose(function()\n\tPlayerDataService.SaveAll()\n\ttask.wait(1)\nend)\n\nprint(\"[GymWars] Server ready — \" .. Constants.PLOT_COUNT .. \" gyms, red carpet conveyor running.\")\n"},{"ServerScriptService/NpcService","ModuleScript","--[[\n\tNpcService\n\tReal R15 humanoid NPCs for influencers and front-desk workers.\n\n\t- Rig creation: Players:CreateHumanoidModelFromDescriptionAsync (falls back\n\t  to the old API, then to a code-built block rig so NPCs always exist).\n\t- Collision groups: NPCs never collide with players or each other, so they\n\t  can't block doorways or be body-blocked.\n\t- Locomotion animation: Roblox's own default R15 idle/walk/run animations,\n\t  blended by actual ground speed exactly like the default Animate script.\n\t- Movement controller: Follow(leader) and WalkTo(point) using direct\n\t  MoveTo when there's line of sight and PathfindingService when there\n\t  isn't, with stuck detection (jump, then re-path, then teleport).\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal PhysicsService = game:GetService(\"PhysicsService\")\nlocal PathfindingService = game:GetService(\"PathfindingService\")\nlocal RunService = game:GetService(\"RunService\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\n\nlocal Constants = require(RS.Modules.Constants)\nlocal BlockRig = require(RS.Modules.Gym.BlockRig)\n\nlocal NpcService = {}\n\nNpcService.GROUP_NPC = \"NPC\"\nNpcService.GROUP_PLAYERS = \"Players\"\n\n-- Roblox default R15 animations (owned by Roblox, usable in any experience)\nlocal ANIMS = {\n\t-- (idle / walk / run play on the clients: StarterPlayerScripts.NpcLocomotion)\n\tJump = \"rbxassetid://507765000\",\n\tFall = \"rbxassetid://507767968\",\n\tWave = \"rbxassetid://507770239\",\n\tCheer = \"rbxassetid://507770677\",\n\tPoint = \"rbxassetid://507770453\",\n\tDance = \"rbxassetid://507771019\",\n}\nNpcService.EMOTES = { \"Wave\", \"Cheer\", \"Point\", \"Dance\" }\n\nlocal controllers = {} -- [model] = controller\nlocal animSets = {} -- [model] = { tracks = {}, ... }\nlocal descCache = {} -- [userId] = HumanoidDescription\n\n-- ----------------------------------------------------------------------\n-- Collision groups\n-- ----------------------------------------------------------------------\nfunction NpcService.Init()\n\tpcall(function()\n\t\tPhysicsService:RegisterCollisionGroup(NpcService.GROUP_NPC)\n\tend)\n\tpcall(function()\n\t\tPhysicsService:RegisterCollisionGroup(NpcService.GROUP_PLAYERS)\n\tend)\n\tPhysicsService:CollisionGroupSetCollidable(NpcService.GROUP_NPC, NpcService.GROUP_NPC, false)\n\tPhysicsService:CollisionGroupSetCollidable(NpcService.GROUP_NPC, NpcService.GROUP_PLAYERS, false)\n\n\tRunService.Heartbeat:Connect(NpcService._step)\nend\n\nfunction NpcService.SetGroup(model, group)\n\tfor _, d in ipairs(model:GetDescendants()) do\n\t\tif d:IsA(\"BasePart\") then\n\t\t\td.CollisionGroup = group\n\t\tend\n\tend\nend\n\n-- ----------------------------------------------------------------------\n-- Rig creation\n-- ----------------------------------------------------------------------\nlocal function buildDescription(opts)\n\tlocal desc\n\tlocal userId = opts.AvatarUserId\n\tif userId then\n\t\tdesc = descCache[userId]\n\t\tif not desc then\n\t\t\tlocal ok, result = pcall(function()\n\t\t\t\treturn Players:GetHumanoidDescriptionFromUserIdAsync(userId)\n\t\t\tend)\n\t\t\tif not ok then\n\t\t\t\tok, result = pcall(function()\n\t\t\t\t\treturn Players:GetHumanoidDescriptionFromUserId(userId)\n\t\t\t\tend)\n\t\t\tend\n\t\t\tif ok and result then\n\t\t\t\tdescCache[userId] = result\n\t\t\t\tdesc = result\n\t\t\tend\n\t\tend\n\t\tif desc then\n\t\t\treturn desc:Clone()\n\t\tend\n\tend\n\n\tdesc = Instance.new(\"HumanoidDescription\")\n\tlocal skin = opts.Skin or Color3.fromRGB(234, 184, 146)\n\tdesc.HeadColor = skin\n\tdesc.LeftArmColor = skin\n\tdesc.RightArmColor = skin\n\tdesc.LeftLegColor = opts.Pants or Color3.fromRGB(38, 40, 48)\n\tdesc.RightLegColor = opts.Pants or Color3.fromRGB(38, 40, 48)\n\tdesc.TorsoColor = opts.Shirt or Color3.fromRGB(80, 80, 90)\n\tdesc.HeightScale = opts.Height or 1\n\tdesc.WidthScale = opts.Width or 1\n\tdesc.DepthScale = opts.Depth or 1\n\tdesc.HeadScale = 1\n\tdesc.BodyTypeScale = 0\n\tdesc.ProportionScale = 0\n\treturn desc\nend\n\nlocal function createModel(desc)\n\tlocal ok, model = pcall(function()\n\t\treturn Players:CreateHumanoidModelFromDescriptionAsync(desc, Enum.HumanoidRigType.R15)\n\tend)\n\tif not ok or not model then\n\t\tok, model = pcall(function()\n\t\t\treturn Players:CreateHumanoidModelFromDescription(desc, Enum.HumanoidRigType.R15)\n\t\tend)\n\tend\n\tif ok and model and model:FindFirstChild(\"HumanoidRootPart\") then\n\t\treturn model, false\n\tend\n\twarn(\"[NpcService] Avatar rig creation failed, using block rig: \" .. tostring(model))\n\treturn nil, true\nend\n\n--[[\n\topts = {\n\t\tName, Skin, Shirt, Pants, Height, Width, Depth, AvatarUserId, Scale,\n\t\tFace = true (adds the classic face decal when the head has none),\n\t\tModel = prebuilt R15 rig to set up instead of creating an avatar\n\t}\n]]\nfunction NpcService.CreateRig(opts)\n\topts = opts or {}\n\tlocal model, isBlock\n\tif opts.Model then\n\t\tmodel, isBlock = opts.Model, false -- prebuilt rig (mesh characters)\n\telse\n\t\tmodel, isBlock = createModel(buildDescription(opts))\n\tend\n\tif isBlock then\n\t\tmodel = BlockRig.Build({ Skin = opts.Skin, Shirt = opts.Shirt, Pants = opts.Pants, Scale = opts.Scale })\n\telseif opts.Scale and opts.Scale ~= 1 then\n\t\t-- bigger-than-life influencers to match the oversized equipment\n\t\tpcall(function()\n\t\t\tmodel:ScaleTo(opts.Scale)\n\t\tend)\n\tend\n\tmodel.Name = opts.Name or \"NPC\"\n\n\tlocal animate = model:FindFirstChild(\"Animate\")\n\tif animate then\n\t\tanimate:Destroy()\n\tend\n\tlocal humanoid = model:FindFirstChildOfClass(\"Humanoid\")\n\tif not humanoid:FindFirstChildOfClass(\"Animator\") then\n\t\tInstance.new(\"Animator\").Parent = humanoid\n\tend\n\thumanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None\n\thumanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff\n\thumanoid.BreakJointsOnDeath = false\n\thumanoid.RequiresNeck = false\n\thumanoid.WalkSpeed = Constants.NPC.FollowSpeed\n\thumanoid.UseJumpPower = true\n\thumanoid.JumpPower = 45\n\tfor _, state in ipairs({\n\t\tEnum.HumanoidStateType.Dead,\n\t\tEnum.HumanoidStateType.FallingDown,\n\t\tEnum.HumanoidStateType.Ragdoll,\n\t\tEnum.HumanoidStateType.Climbing,\n\t\tEnum.HumanoidStateType.Swimming,\n\t\tEnum.HumanoidStateType.Seated,\n\t}) do\n\t\thumanoid:SetStateEnabled(state, false)\n\tend\n\n\tlocal head = model:FindFirstChild(\"Head\")\n\tif head and opts.Face ~= false and not head:FindFirstChildOfClass(\"Decal\") then\n\t\tlocal face = Instance.new(\"Decal\")\n\t\tface.Name = \"face\"\n\t\tface.Texture = \"rbxasset://textures/face.png\"\n\t\tface.Face = Enum.NormalId.Front\n\t\tface.Parent = head\n\tend\n\n\t-- set before the model is parented so clients get it together with the model\n\tmodel:SetAttribute(\"Loco\", true)\n\tNpcService.SetGroup(model, NpcService.GROUP_NPC)\n\tfor _, d in ipairs(model:GetDescendants()) do\n\t\tif d:IsA(\"BasePart\") then\n\t\t\td.CanTouch = false\n\t\tend\n\tend\n\tmodel.PrimaryPart = model:FindFirstChild(\"HumanoidRootPart\")\n\treturn model\nend\n\n-- Call after parenting into workspace.\nfunction NpcService.Activate(model)\n\tlocal hrp = model:FindFirstChild(\"HumanoidRootPart\")\n\tif hrp and not hrp.Anchored then\n\t\tpcall(function()\n\t\t\thrp:SetNetworkOwner(nil) -- server-owned: no exploit control, no ownership hand-off jitter\n\t\tend)\n\tend\n\tNpcService._ensureAnims(model)\n\t-- walking/running/idle are animated on each client (StarterPlayerScripts.NpcLocomotion)\n\tmodel:SetAttribute(\"Loco\", true)\nend\n\n-- ----------------------------------------------------------------------\n-- Animation\n-- ----------------------------------------------------------------------\nfunction NpcService._ensureAnims(model)\n\tlocal set = animSets[model]\n\tif set then\n\t\treturn set\n\tend\n\tlocal humanoid = model:FindFirstChildOfClass(\"Humanoid\")\n\tlocal animator = humanoid and humanoid:FindFirstChildOfClass(\"Animator\")\n\tif not animator then\n\t\treturn nil\n\tend\n\tset = { Tracks = {}, Animator = animator, Humanoid = humanoid, Enabled = true, Emote = nil }\n\tfor key, id in pairs(ANIMS) do\n\t\tlocal anim = Instance.new(\"Animation\")\n\t\tanim.AnimationId = id\n\t\tlocal ok, track = pcall(function()\n\t\t\treturn animator:LoadAnimation(anim)\n\t\tend)\n\t\tif ok and track then\n\t\t\tlocal looped = key == \"Idle\" or key == \"Walk\" or key == \"Run\" or key == \"Dance\"\n\t\t\ttrack.Looped = looped\n\t\t\ttrack.Priority = (key == \"Idle\" or key == \"Walk\" or key == \"Run\") and Enum.AnimationPriority.Core\n\t\t\t\tor Enum.AnimationPriority.Action\n\t\t\tset.Tracks[key] = track\n\t\tend\n\tend\n\tanimSets[model] = set\n\tmodel.Destroying:Connect(function()\n\t\tanimSets[model] = nil\n\t\tcontrollers[model] = nil\n\tend)\n\treturn set\nend\n\nfunction NpcService.PlayEmote(model, name)\n\tlocal set = NpcService._ensureAnims(model)\n\tlocal track = set and set.Tracks[name]\n\tif track and set.Enabled then\n\t\tif set.Emote and set.Emote.IsPlaying then\n\t\t\tset.Emote:Stop(0.2)\n\t\tend\n\t\ttrack:Play(0.2)\n\t\tset.Emote = track\n\t\tif track.Looped then\n\t\t\ttask.delay(4, function()\n\t\t\t\tif set.Emote == track then\n\t\t\t\t\ttrack:Stop(0.4)\n\t\t\t\tend\n\t\t\tend)\n\t\tend\n\tend\nend\n\n-- Stop all server animation (the client drives the rig procedurally on machines)\nfunction NpcService.SetAnimationsEnabled(model, enabled)\n\tlocal set = NpcService._ensureAnims(model)\n\tif not set then\n\t\treturn\n\tend\n\tset.Enabled = enabled\n\tmodel:SetAttribute(\"Loco\", enabled) -- clients stop walk/idle while the rig works out\n\tif not enabled then\n\t\tfor _, t in pairs(set.Tracks) do\n\t\t\tt:Stop(0.1)\n\t\tend\n\tend\nend\n\n-- ----------------------------------------------------------------------\n-- Movement controller\n-- ----------------------------------------------------------------------\nlocal AGENT = { AgentRadius = 2, AgentHeight = 7.2, AgentCanJump = true, WaypointSpacing = 6 }\n\nlocal losParams = RaycastParams.new()\nlosParams.CollisionGroup = NpcService.GROUP_NPC\nlosParams.FilterType = Enum.RaycastFilterType.Exclude\nlosParams.RespectCanCollide = true\n\nlocal function flat(v)\n\treturn Vector3.new(v.X, 0, v.Z)\nend\n\nlocal function hasLineOfSight(from, to)\n\tlocal a = from + Vector3.new(0, 0.5, 0)\n\tlocal b = to + Vector3.new(0, 0.5, 0)\n\tlocal dir = b - a\n\tif dir.Magnitude < 0.5 then\n\t\treturn true\n\tend\n\t-- two rays (waist + knee height) so low obstacles count too\n\tlocal hit1 = workspace:Raycast(a, dir, losParams)\n\tlocal hit2 = workspace:Raycast(a - Vector3.new(0, 1.8, 0), dir, losParams)\n\treturn hit1 == nil and hit2 == nil\nend\n\nlocal function newController(model)\n\tlocal c = controllers[model]\n\tif c then\n\t\treturn c\n\tend\n\tc = {\n\t\tModel = model,\n\t\tHumanoid = model:FindFirstChildOfClass(\"Humanoid\"),\n\t\tRoot = model:FindFirstChild(\"HumanoidRootPart\"),\n\t\tMode = \"None\",\n\t\tPath = nil,\n\t\tWaypoints = nil,\n\t\tWpIndex = 0,\n\t\tPathBusy = false,\n\t\tPathAt = 0,\n\t\tLastProgressPos = nil,\n\t\tLastProgressAt = os.clock(),\n\t\tAccum = 0,\n\t}\n\tcontrollers[model] = c\n\treturn c\nend\n\n-- Follow a leader (Player). offset = sideways offset so several followers fan out.\nfunction NpcService.Follow(model, player, speed, offset)\n\tlocal c = newController(model)\n\tc.Humanoid.WalkSpeed = speed or Constants.NPC.FollowSpeed\n\tc.Offset = offset or 0\n\tif c.Mode == \"Follow\" and c.Leader == player then\n\t\treturn -- already following them; just refresh speed/offset\n\tend\n\tc.Mode = \"Follow\"\n\tc.Leader = player\n\tc.Waypoints = nil\n\tc.LastProgressAt = os.clock()\nend\n\n-- Walk to a point, then call onArrive(model). onFail after `timeout` seconds.\n-- `route` (optional): list of Vector3 walked point to point first (plain\n-- MoveTo, no pathfinding), e.g. a GymNav route through doors and up stairs.\nfunction NpcService.WalkTo(model, point, speed, onArrive, timeout, onFail, route)\n\tlocal c = newController(model)\n\tc.Mode = \"WalkTo\"\n\tc.Target = point\n\tc.OnArrive = onArrive\n\tc.OnFail = onFail\n\tc.Deadline = os.clock() + (timeout or 30)\n\tc.Humanoid.WalkSpeed = speed or Constants.NPC.SeatSpeed\n\tc.Waypoints = nil\n\tc.Route = route\n\tc.RouteIndex = 1\n\tc.LastProgressAt = os.clock()\nend\n\n-- Chase a player's character directly (front desk).\nfunction NpcService.Chase(model, player, speed)\n\tlocal c = newController(model)\n\tc.Humanoid.WalkSpeed = speed or 16\n\tif c.Mode == \"Chase\" and c.Leader == player then\n\t\treturn\n\tend\n\tc.Mode = \"Chase\"\n\tc.Leader = player\n\tc.Offset = 0\n\tc.Waypoints = nil\n\tc.LastProgressAt = os.clock()\nend\n\n-- Chase another model (e.g. a stolen influencer).\nfunction NpcService.ChaseModel(model, target, speed)\n\tlocal c = newController(model)\n\tc.Humanoid.WalkSpeed = speed or 16\n\tif c.Mode == \"ChaseModel\" and c.TargetModel == target then\n\t\treturn\n\tend\n\tc.Mode = \"ChaseModel\"\n\tc.TargetModel = target\n\tc.Waypoints = nil\n\tc.LastProgressAt = os.clock()\nend\n\nfunction NpcService.Stop(model)\n\tlocal c = controllers[model]\n\tif c then\n\t\tc.Mode = \"None\"\n\t\tc.Waypoints = nil\n\t\tif c.Humanoid and c.Root and not c.Root.Anchored then\n\t\t\tc.Humanoid:MoveTo(c.Root.Position)\n\t\tend\n\tend\nend\n\nfunction NpcService.Forget(model)\n\tcontrollers[model] = nil\nend\n\nlocal function computePath(c, goal)\n\tif c.PathBusy then\n\t\treturn\n\tend\n\tc.PathBusy = true\n\tlocal from = c.Root.Position\n\ttask.spawn(function()\n\t\tlocal path = PathfindingService:CreatePath(AGENT)\n\t\tlocal ok = pcall(function()\n\t\t\tpath:ComputeAsync(from, goal)\n\t\tend)\n\t\tc.PathBusy = false\n\t\tc.PathAt = os.clock()\n\t\tif ok and path.Status == Enum.PathStatus.Success then\n\t\t\tc.Waypoints = path:GetWaypoints()\n\t\t\tc.WpIndex = math.min(2, #c.Waypoints)\n\t\t\tc.PathGoal = goal\n\t\telse\n\t\t\tc.Waypoints = nil\n\t\tend\n\tend)\nend\n\nlocal function followWaypoints(c)\n\tlocal wps = c.Waypoints\n\tif not wps or c.WpIndex > #wps then\n\t\treturn false\n\tend\n\tlocal wp = wps[c.WpIndex]\n\tif flat(wp.Position - c.Root.Position).Magnitude < 2.5 then\n\t\tc.WpIndex += 1\n\t\twp = wps[c.WpIndex]\n\t\tif not wp then\n\t\t\treturn false\n\t\tend\n\tend\n\tif wp.Action == Enum.PathWaypointAction.Jump then\n\t\tc.Humanoid.Jump = true\n\tend\n\tc.Humanoid:MoveTo(wp.Position)\n\treturn true\nend\n\n-- stuck detection: jump, and if that doesn't help, hop a few studs forward\nlocal function unstick(c, pos, goal)\n\tlocal now = os.clock()\n\tif not c.LastProgressPos or (pos - c.LastProgressPos).Magnitude > 1.2 then\n\t\tc.LastProgressPos = pos\n\t\tc.LastProgressAt = now\n\telseif now - c.LastProgressAt > 1.4 then\n\t\tc.Humanoid.Jump = true\n\t\tc.Waypoints = nil\n\t\tif now - c.LastProgressAt > 5 then\n\t\t\tlocal dir = flat(goal - pos)\n\t\t\tif dir.Magnitude > 0.1 then\n\t\t\t\tc.Model:PivotTo(CFrame.new(pos + dir.Unit * math.min(6, dir.Magnitude) + Vector3.new(0, 2, 0)))\n\t\t\tend\n\t\t\tc.LastProgressAt = now\n\t\tend\n\tend\nend\n\n-- Returns true when the NPC reached `goal` (XZ within arriveDist).\nlocal function steer(c, goal, arriveDist)\n\tlocal pos = c.Root.Position\n\tlocal d = flat(goal - pos).Magnitude\n\t-- same floor check: a machine directly above/below isn't \"arrived\"\n\tif d <= arriveDist and math.abs(goal.Y - pos.Y) < 6 then\n\t\tc.Humanoid:MoveTo(pos)\n\t\tc.Waypoints = nil\n\t\treturn true\n\tend\n\tif math.abs(goal.Y - pos.Y) < 5 and hasLineOfSight(pos, goal) then\n\t\tc.Waypoints = nil\n\t\tc.Humanoid:MoveTo(goal)\n\telse\n\t\tlocal stale = not c.Waypoints\n\t\t\tor os.clock() - c.PathAt > 2\n\t\t\tor (c.PathGoal and (c.PathGoal - goal).Magnitude > 8)\n\t\tif stale then\n\t\t\tcomputePath(c, goal)\n\t\tend\n\t\tif not followWaypoints(c) then\n\t\t\tc.Humanoid:MoveTo(goal)\n\t\tend\n\tend\n\n\tunstick(c, pos, goal)\n\treturn false\nend\n\n-- Follow a fixed route one point at a time. Returns true once it's done.\nlocal function followRoute(c)\n\tlocal route = c.Route\n\tif not route then\n\t\treturn true\n\tend\n\tlocal pos = c.Root.Position\n\twhile c.RouteIndex <= #route do\n\t\tlocal p = route[c.RouteIndex]\n\t\t-- intermediate points only need to be passed on the right level\n\t\tif flat(p - pos).Magnitude < 2.5 and math.abs(p.Y - pos.Y) < 7 then\n\t\t\tc.RouteIndex += 1\n\t\telse\n\t\t\tc.Humanoid:MoveTo(p)\n\t\t\tunstick(c, pos, p)\n\t\t\treturn false\n\t\tend\n\tend\n\tc.Route = nil\n\treturn true\nend\n\nlocal function leaderRoot(c)\n\tlocal p = c.Leader\n\tlocal char = p and p.Parent and p.Character\n\tlocal hrp = char and char:FindFirstChild(\"HumanoidRootPart\")\n\tlocal hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n\tif hrp and hum and hum.Health > 0 then\n\t\treturn hrp\n\tend\n\treturn nil\nend\n\nfunction NpcService.GetLeaderRoot(model)\n\tlocal c = controllers[model]\n\treturn c and leaderRoot(c)\nend\n\nfunction NpcService._step(dt)\n\tfor model, c in pairs(controllers) do\n\t\tif not model.Parent or not c.Root or not c.Root.Parent then\n\t\t\tcontrollers[model] = nil\n\t\t\tcontinue\n\t\tend\n\t\tif c.Root.Anchored or c.Mode == \"None\" then\n\t\t\tcontinue\n\t\tend\n\t\tc.Accum += dt\n\t\tif c.Accum < 0.12 then\n\t\t\tcontinue\n\t\tend\n\t\tc.Accum = 0\n\n\t\tif c.Mode == \"Follow\" or c.Mode == \"Chase\" then\n\t\t\tlocal lr = leaderRoot(c)\n\t\t\tif lr then\n\t\t\t\tlocal look = flat(lr.CFrame.LookVector)\n\t\t\t\tlook = look.Magnitude > 0.1 and look.Unit or Vector3.new(0, 0, -1)\n\t\t\t\tlocal right = look:Cross(Vector3.yAxis)\n\t\t\t\tlocal goal\n\t\t\t\tlocal arrive\n\t\t\t\tif c.Mode == \"Chase\" then\n\t\t\t\t\tgoal, arrive = lr.Position, 1\n\t\t\t\telse\n\t\t\t\t\tgoal = lr.Position - look * Constants.NPC.FollowGap + right * c.Offset\n\t\t\t\t\tarrive = 2.2\n\t\t\t\tend\n\t\t\t\tlocal gap = flat(goal - c.Root.Position).Magnitude\n\t\t\t\tif gap > Constants.NPC.TeleportIfFartherThan then\n\t\t\t\t\tmodel:PivotTo(CFrame.new(goal + Vector3.new(0, 3, 0), goal + look))\n\t\t\t\t\tc.Waypoints = nil\n\t\t\t\telseif steer(c, goal, arrive) and c.Mode == \"Follow\" then\n\t\t\t\t\t-- idle next to the leader: turn to face them\n\t\t\t\t\tlocal to = flat(lr.Position - c.Root.Position)\n\t\t\t\t\tif to.Magnitude > 0.5 then\n\t\t\t\t\t\tc.Root.CFrame = CFrame.lookAt(c.Root.Position, c.Root.Position + to)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\telse\n\t\t\t\tc.Humanoid:MoveTo(c.Root.Position)\n\t\t\tend\n\t\telseif c.Mode == \"ChaseModel\" then\n\t\t\tlocal tr = c.TargetModel and c.TargetModel.Parent and c.TargetModel:FindFirstChild(\"HumanoidRootPart\")\n\t\t\tif tr then\n\t\t\t\tsteer(c, tr.Position, 1)\n\t\t\telse\n\t\t\t\tc.Humanoid:MoveTo(c.Root.Position)\n\t\t\tend\n\t\telseif c.Mode == \"WalkTo\" then\n\t\t\tif not followRoute(c) then\n\t\t\t\tif os.clock() > c.Deadline then\n\t\t\t\t\tc.Mode = \"None\"\n\t\t\t\t\tc.Route = nil\n\t\t\t\t\tlocal cb = c.OnFail\n\t\t\t\t\tc.OnArrive, c.OnFail = nil, nil\n\t\t\t\t\tif cb then\n\t\t\t\t\t\ttask.spawn(cb, model)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\telseif steer(c, c.Target, 1.6) then\n\t\t\t\tc.Mode = \"None\"\n\t\t\t\tlocal cb = c.OnArrive\n\t\t\t\tc.OnArrive, c.OnFail = nil, nil\n\t\t\t\tif cb then\n\t\t\t\t\ttask.spawn(cb, model)\n\t\t\t\tend\n\t\t\telseif os.clock() > c.Deadline then\n\t\t\t\tc.Mode = \"None\"\n\t\t\t\tlocal cb = c.OnFail\n\t\t\t\tc.OnArrive, c.OnFail = nil, nil\n\t\t\t\tif cb then\n\t\t\t\t\ttask.spawn(cb, model)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\nend\n\nreturn NpcService\n"},{"StarterPlayerScripts/CharacterEffects","LocalScript","--[[\n\tCharacterEffects (client)\n\tEverything players see/hear around rarity — all data-driven from\n\tReplicatedStorage.Modules.Characters:\n\t  - spawn sounds (3D for low rarities, server-wide for Legendary+)\n\t  - conveyor glow flashes in the rarity color; Mythic/G.O.A.T. recolor the belt\n\t  - big banners for Mythic and G.O.A.T. (\"A G.O.A.T. HAS ENTERED THE GYM.\")\n\t  - G.O.A.T.: gym lights flicker; Arnie shifts the whole world's lighting gold;\n\t    Ronnie slams onto the belt (camera shake + metallic impact)\n\t  - purchase bursts (particles, shockwave ring and flash for higher rarities)\n\t  - animated gradients on high-rarity name cards; Jeff's floating chart\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal Lighting = game:GetService(\"Lighting\")\nlocal Debris = game:GetService(\"Debris\")\n\nlocal Characters = require(RS:WaitForChild(\"Modules\"):WaitForChild(\"Characters\"))\nlocal FxRemote = RS:WaitForChild(\"Remotes\"):WaitForChild(\"CharacterFx\")\n\nlocal player = Players.LocalPlayer\nlocal camera = workspace.CurrentCamera\nlocal map = workspace:WaitForChild(\"GymWarsMap\")\nlocal influencers = workspace:WaitForChild(\"Influencers\", 30)\n\n-- ----------------------------------------------------------------------\n-- Sound\n-- ----------------------------------------------------------------------\nlocal function playSound(def, parent, volumeMul)\n\tif not def or not def.Id then\n\t\treturn\n\tend\n\tlocal s = Instance.new(\"Sound\")\n\ts.SoundId = def.Id\n\ts.Volume = (def.Volume or 0.5) * (volumeMul or 1)\n\ts.PlaybackSpeed = def.Pitch or 1\n\ts.RollOffMaxDistance = 220\n\ts.Parent = parent or workspace\n\ts:Play()\n\tDebris:AddItem(s, 6)\n\treturn s\nend\n\n-- ----------------------------------------------------------------------\n-- Banner\n-- ----------------------------------------------------------------------\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"RarityEvents\"\ngui.ResetOnSpawn = false\ngui.IgnoreGuiInset = true\ngui.DisplayOrder = 20\ngui.Parent = player:WaitForChild(\"PlayerGui\")\n\nlocal function banner(title, subtitle, rarity, seconds)\n\tlocal frame = Instance.new(\"Frame\")\n\tframe.AnchorPoint = Vector2.new(0.5, 0)\n\tframe.Position = UDim2.new(0.5, 0, 0.12, 0)\n\tframe.Size = UDim2.new(0.7, 0, 0.14, 0)\n\tframe.BackgroundColor3 = Color3.new(0, 0, 0)\n\tframe.BackgroundTransparency = 0.35\n\tframe.Parent = gui\n\tlocal corner = Instance.new(\"UICorner\")\n\tcorner.CornerRadius = UDim.new(0, 14)\n\tcorner.Parent = frame\n\tlocal stroke = Instance.new(\"UIStroke\")\n\tstroke.Color = rarity.Color\n\tstroke.Thickness = 3\n\tstroke.Parent = frame\n\n\tlocal t = Instance.new(\"TextLabel\")\n\tt.BackgroundTransparency = 1\n\tt.Size = UDim2.new(1, -20, 0.62, 0)\n\tt.Position = UDim2.new(0, 10, 0.02, 0)\n\tt.Font = Enum.Font.GothamBlack\n\tt.TextScaled = true\n\tt.TextColor3 = Color3.new(1, 1, 1)\n\tt.Text = title\n\tt.Parent = frame\n\tif rarity.Gradient then\n\t\tlocal g = Instance.new(\"UIGradient\")\n\t\tlocal keys = {}\n\t\tfor i, c in ipairs(rarity.Gradient) do\n\t\t\ttable.insert(keys, ColorSequenceKeypoint.new((i - 1) / math.max(#rarity.Gradient - 1, 1), c))\n\t\tend\n\t\tg.Color = ColorSequence.new(keys)\n\t\tg.Parent = t\n\t\ttask.spawn(function()\n\t\t\tlocal t0 = os.clock()\n\t\t\twhile g.Parent and os.clock() - t0 < seconds do\n\t\t\t\tg.Offset = Vector2.new(math.sin((os.clock() - t0) * 3) * 0.5, 0)\n\t\t\t\ttask.wait()\n\t\t\tend\n\t\tend)\n\tend\n\tlocal sub = Instance.new(\"TextLabel\")\n\tsub.BackgroundTransparency = 1\n\tsub.Size = UDim2.new(1, -20, 0.32, 0)\n\tsub.Position = UDim2.new(0, 10, 0.64, 0)\n\tsub.Font = Enum.Font.GothamBold\n\tsub.TextScaled = true\n\tsub.TextColor3 = rarity.Color\n\tsub.Text = subtitle\n\tsub.Parent = frame\n\n\tframe.Size = UDim2.new(0.2, 0, 0.04, 0)\n\tTweenService:Create(frame, TweenInfo.new(0.35, Enum.EasingStyle.Back), { Size = UDim2.new(0.7, 0, 0.14, 0) }):Play()\n\ttask.delay(seconds, function()\n\t\tlocal tw = TweenService:Create(frame, TweenInfo.new(0.5), { BackgroundTransparency = 1 })\n\t\ttw:Play()\n\t\tTweenService:Create(t, TweenInfo.new(0.5), { TextTransparency = 1 }):Play()\n\t\tTweenService:Create(sub, TweenInfo.new(0.5), { TextTransparency = 1 }):Play()\n\t\tTweenService:Create(stroke, TweenInfo.new(0.5), { Transparency = 1 }):Play()\n\t\ttw.Completed:Wait()\n\t\tframe:Destroy()\n\tend)\nend\n\n-- ----------------------------------------------------------------------\n-- Big-moment effects\n-- ----------------------------------------------------------------------\nlocal function flickerGymLights(seconds)\n\tlocal lights = {}\n\tlocal plots = map:FindFirstChild(\"Plots\")\n\tif not plots then\n\t\treturn\n\tend\n\tfor _, d in ipairs(plots:GetDescendants()) do\n\t\tif d:IsA(\"SurfaceLight\") or d:IsA(\"PointLight\") or d:IsA(\"SpotLight\") then\n\t\t\ttable.insert(lights, { L = d, B = d.Brightness })\n\t\tend\n\tend\n\ttask.spawn(function()\n\t\tlocal t0 = os.clock()\n\t\twhile os.clock() - t0 < seconds do\n\t\t\tlocal on = math.random() < 0.55\n\t\t\tfor _, l in ipairs(lights) do\n\t\t\t\tl.L.Brightness = on and l.B or l.B * 0.08\n\t\t\tend\n\t\t\ttask.wait(math.random(4, 12) / 100)\n\t\tend\n\t\tfor _, l in ipairs(lights) do\n\t\t\tl.L.Brightness = l.B\n\t\tend\n\tend)\nend\n\nlocal function shakeCamera(strength, seconds)\n\tlocal t0 = os.clock()\n\tlocal conn\n\tconn = RunService.RenderStepped:Connect(function()\n\t\tlocal t = os.clock() - t0\n\t\tif t > seconds then\n\t\t\tconn:Disconnect()\n\t\t\treturn\n\t\tend\n\t\tlocal k = strength * (1 - t / seconds)\n\t\tcamera.CFrame = camera.CFrame * CFrame.new(math.noise(t * 20, 0) * k, math.noise(0, t * 20) * k, 0)\n\t\t\t* CFrame.Angles(0, 0, math.noise(t * 15, 5) * k * 0.02)\n\tend)\nend\n\nlocal function shockwave(position, color, size)\n\tlocal ring = Instance.new(\"Part\")\n\tring.Anchored = true\n\tring.CanCollide = false\n\tring.CanQuery = false\n\tring.CanTouch = false\n\tring.CastShadow = false\n\tring.Material = Enum.Material.Neon\n\tring.Color = color\n\tring.Shape = Enum.PartType.Cylinder\n\tring.Size = Vector3.new(0.2, 2, 2)\n\tring.CFrame = CFrame.new(position) * CFrame.Angles(0, 0, math.rad(90))\n\tring.Transparency = 0.2\n\tring.Parent = workspace\n\tTweenService:Create(ring, TweenInfo.new(0.7, Enum.EasingStyle.Quad), { Size = Vector3.new(0.2, size, size), Transparency = 1 }):Play()\n\tDebris:AddItem(ring, 0.8)\nend\n\nlocal function burst(root, rarity, count)\n\tlocal att = Instance.new(\"Attachment\")\n\tatt.Parent = root\n\tlocal pe = Instance.new(\"ParticleEmitter\")\n\tpe.Color = ColorSequence.new(rarity.Color, rarity.Glow)\n\tpe.LightEmission = 1\n\tpe.Enabled = false\n\tpe.Lifetime = NumberRange.new(0.6, 1.4)\n\tpe.Speed = NumberRange.new(8, 22)\n\tpe.SpreadAngle = Vector2.new(180, 180)\n\tpe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.6), NumberSequenceKeypoint.new(1, 0) })\n\tpe.Drag = 3\n\tpe.Parent = att\n\tpe:Emit(count)\n\tlocal light = Instance.new(\"PointLight\")\n\tlight.Color = rarity.Color\n\tlight.Range = 18\n\tlight.Brightness = 3 + rarity.Index\n\tlight.Parent = att\n\tTweenService:Create(light, TweenInfo.new(0.8), { Brightness = 0 }):Play()\n\tDebris:AddItem(att, 2)\nend\n\n-- ----------------------------------------------------------------------\n-- Events from the server\n-- ----------------------------------------------------------------------\nFxRemote.OnClientEvent:Connect(function(kind, data)\n\tlocal rarity = Characters.GetRarity(data.Rarity)\n\tif not rarity then\n\t\treturn\n\tend\n\tlocal model = data.Model\n\tlocal root = model and model:FindFirstChild(\"HumanoidRootPart\")\n\n\tif kind == \"Spawn\" then\n\t\tlocal global = rarity.Index >= 5\n\t\tplaySound(rarity.SpawnSound, (not global) and root or nil)\n\t\tif rarity.Index >= 7 then\n\t\t\tplaySound(rarity.SpawnSound, nil, 1)\n\t\t\ttask.delay(0.35, function()\n\t\t\t\tplaySound({ Id = rarity.SpawnSound.Id, Volume = 1, Pitch = 0.22 })\n\t\t\tend)\n\t\t\tbanner(\"A G.O.A.T. HAS ENTERED THE GYM.\", data.Name:upper(), rarity, 7)\n\t\t\tflickerGymLights(2.5)\n\t\telseif rarity.Index == 6 then\n\t\t\tbanner(\"A MYTHIC HAS APPEARED!\", data.Name:upper(), rarity, 5)\n\t\telseif data.SpawnFx == \"Milestone\" then\n\t\t\tbanner(\"FIRST $1 BILLION/SEC CHARACTER!\", data.Name:upper(), rarity, 4)\n\t\tend\n\t\tif data.SpawnFx == \"HeavyLanding\" and root then\n\t\t\t-- the ground shakes as he stomps out of the gate\n\t\t\ttask.delay(1.2, function()\n\t\t\t\tif not root.Parent then\n\t\t\t\t\treturn\n\t\t\t\tend\n\t\t\t\tplaySound({ Id = \"rbxasset://sounds/action_jump_land.mp3\", Volume = 1, Pitch = 0.45 }, root)\n\t\t\t\tplaySound({ Id = \"rbxasset://sounds/electronicpingshort.wav\", Volume = 0.7, Pitch = 0.3 }, root)\n\t\t\t\tshockwave(root.Position - Vector3.new(0, 3, 0), rarity.Color, 30)\n\t\t\t\tlocal myRoot = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\t\t\t\tlocal d = myRoot and (myRoot.Position - root.Position).Magnitude or 999\n\t\t\t\tif d < 200 then\n\t\t\t\t\tshakeCamera(1.6 * (1 - d / 200) + 0.3, 0.9)\n\t\t\t\tend\n\t\t\tend)\n\t\tend\n\telseif kind == \"Purchase\" then\n\t\tif root then\n\t\t\tplaySound(rarity.PurchaseSound, root)\n\t\t\tburst(root, rarity, rarity.Particles or 10)\n\t\t\tif rarity.Index >= 4 then\n\t\t\t\tshockwave(root.Position - Vector3.new(0, 2.5, 0), rarity.Color, 10 + rarity.Index * 3)\n\t\t\tend\n\t\tend\n\t\tif data.Buyer == player and rarity.Index >= 6 then\n\t\t\tbanner(\"YOU GOT \" .. (Characters.Get(data.Id) and Characters.Get(data.Id).DisplayName:upper() or \"IT\") .. \"!\", rarity.DisplayName, rarity, 3)\n\t\tend\n\tend\nend)\n\n-- ----------------------------------------------------------------------\n-- Ambient: animated rarity gradients + Jeff's chart\n-- ----------------------------------------------------------------------\nlocal chartNext = {}\nRunService.Heartbeat:Connect(function()\n\tif not influencers then\n\t\treturn\n\tend\n\tlocal t = os.clock()\n\tfor _, model in ipairs(influencers:GetChildren()) do\n\t\tlocal head = model:FindFirstChild(\"Head\")\n\t\tlocal tag = head and head:FindFirstChild(\"NameTag\")\n\t\tif tag and tag:GetAttribute(\"AnimatedGradient\") then\n\t\t\tfor _, l in ipairs(tag:GetChildren()) do\n\t\t\t\tlocal g = l:FindFirstChildOfClass(\"UIGradient\")\n\t\t\t\tif g then\n\t\t\t\t\tg.Offset = Vector2.new(math.sin(t * 2 + l.LayoutOrder) * 0.4, 0)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tif model:GetAttribute(\"Chart\") and head then\n\t\t\tlocal nextAt = chartNext[model]\n\t\t\tif not nextAt then\n\t\t\t\tchartNext[model] = t + math.random(3, 8)\n\t\t\telseif t >= nextAt then\n\t\t\t\tchartNext[model] = t + math.random(7, 12)\n\t\t\t\tlocal bb = Instance.new(\"BillboardGui\")\n\t\t\t\tbb.Size = UDim2.new(0, 60, 0, 60)\n\t\t\t\tbb.StudsOffsetWorldSpace = Vector3.new(1.8, 2, 0)\n\t\t\t\tbb.AlwaysOnTop = true\n\t\t\t\tbb.LightInfluence = 0\n\t\t\t\tbb.Parent = head\n\t\t\t\tlocal l = Instance.new(\"TextLabel\")\n\t\t\t\tl.BackgroundTransparency = 1\n\t\t\t\tl.Size = UDim2.new(1, 0, 1, 0)\n\t\t\t\tl.Text = \"📈\"\n\t\t\t\tl.TextScaled = true\n\t\t\t\tl.Parent = bb\n\t\t\t\tTweenService:Create(bb, TweenInfo.new(2.2), { StudsOffsetWorldSpace = Vector3.new(1.8, 4.5, 0) }):Play()\n\t\t\t\tTweenService:Create(l, TweenInfo.new(2.2), { TextTransparency = 1 }):Play()\n\t\t\t\tDebris:AddItem(bb, 2.3)\n\t\t\tend\n\t\tend\n\tend\nend)\n\nif influencers then\n\tinfluencers.ChildRemoved:Connect(function(m)\n\t\tchartNext[m] = nil\n\tend)\nend\n"},{"StarterPlayerScripts/GymAnimator","LocalScript","--[[\n\tGymAnimator (client)\n\tBrings the gyms to life locally:\n\t  - Influencers sitting on a machine are posed every frame by the procedural\n\t    exercise library (RigSolver + Exercises). Time comes from\n\t    workspace:GetServerTimeNow(), so every player sees the same rep.\n\t  - Machine parts (bars, weight stacks, cables, pedals, treadmill belts)\n\t    move with the athlete.\n\t  - When an athlete hops on, the pose blends in from how they were standing.\n\t  - The conveyor's chevrons scroll so the belt visibly runs.\n\t  - Your own placed influencers don't show a \"Steal\" prompt to you.\n\t  - [X] lets go of the influencer following you.\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal UIS = game:GetService(\"UserInputService\")\n\nlocal Modules = RS:WaitForChild(\"Modules\")\nlocal GymModules = Modules:WaitForChild(\"Gym\")\nlocal Constants = require(Modules:WaitForChild(\"Constants\"))\nlocal RigSolver = require(GymModules:WaitForChild(\"RigSolver\"))\nlocal Poses = require(GymModules:WaitForChild(\"Poses\"))\nlocal Exercises = require(GymModules:WaitForChild(\"Exercises\"))\nlocal Specs = require(GymModules:WaitForChild(\"StationSpecs\"))\nlocal Remotes = RS:WaitForChild(\"Remotes\")\n\nlocal player = Players.LocalPlayer\nlocal camera = workspace.CurrentCamera\n\nlocal ANIM_RANGE = 230 -- only animate athletes this close to the camera\nlocal BLEND_TIME = 0.9\n\nlocal influencers = workspace:WaitForChild(\"Influencers\", 30)\nlocal mapFolder = workspace:WaitForChild(\"GymWarsMap\")\n\nlocal bulkParts, bulkCFs = {}, {}\nlocal function queue(part, cf)\n\tlocal n = #bulkParts + 1\n\tbulkParts[n] = part\n\tbulkCFs[n] = cf\nend\n\nlocal function smooth(x)\n\tx = math.clamp(x, 0, 1)\n\treturn x * x * (3 - 2 * x)\nend\n\nlocal function axisCF(a, b)\n\tlocal mid = (a + b) / 2\n\tlocal dir = (b - a).Unit\n\tlocal up = math.abs(dir.Y) > 0.95 and Vector3.new(1, 0, 0) or Vector3.new(0, 1, 0)\n\tlocal z = dir:Cross(up).Unit\n\treturn CFrame.fromMatrix(mid, dir, z:Cross(dir).Unit, z)\nend\n\n-- ----------------------------------------------------------------------\n-- Station contexts (rest poses of every moving part, captured once)\n-- ----------------------------------------------------------------------\nlocal stationCtx = {}\n\nlocal function buildCtx(station)\n\tlocal base = station:FindFirstChild(\"Base\")\n\tlocal kind = station:GetAttribute(\"Exercise\")\n\tif not base or not kind then\n\t\treturn nil\n\tend\n\tlocal ctx = {\n\t\tStation = station,\n\t\tKind = kind,\n\t\tBase = base.CFrame,\n\t\tSpec = Specs[kind],\n\t\tRestLocal = {},\n\t\tGroups = {},\n\t\tCables = {},\n\t}\n\tlocal moving = station:FindFirstChild(\"Moving\")\n\tif moving then\n\t\tfor _, m in ipairs(moving:GetChildren()) do\n\t\t\tlocal prim = m:IsA(\"Model\") and (m.PrimaryPart or m:FindFirstChildWhichIsA(\"BasePart\"))\n\t\t\tif prim then\n\t\t\t\tlocal primRest = prim.CFrame\n\t\t\t\tctx.RestLocal[m.Name] = ctx.Base:ToObjectSpace(primRest)\n\t\t\t\tlocal g = { Parts = {}, Rel = {}, Rest = {}, Tier = {}, Order = {} }\n\t\t\t\tfor _, p in ipairs(m:GetDescendants()) do\n\t\t\t\t\tif p:IsA(\"BasePart\") then\n\t\t\t\t\t\ttable.insert(g.Parts, p)\n\t\t\t\t\t\ttable.insert(g.Rel, primRest:ToObjectSpace(p.CFrame))\n\t\t\t\t\t\ttable.insert(g.Rest, p.CFrame)\n\t\t\t\t\t\tg.Tier[#g.Parts] = p:GetAttribute(\"Tier\")\n\t\t\t\t\t\tg.Order[#g.Parts] = p:GetAttribute(\"StackOrder\")\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\t\tctx.Groups[m.Name] = g\n\t\t\tend\n\t\tend\n\tend\n\tlocal cables = station:FindFirstChild(\"Cables\")\n\tif cables then\n\t\tfor _, c in ipairs(cables:GetChildren()) do\n\t\t\tif c:IsA(\"BasePart\") then\n\t\t\t\tctx.Cables[c.Name] = { Part = c, RestCF = c.CFrame, RestSize = c.Size }\n\t\t\tend\n\t\tend\n\tend\n\tstationCtx[station] = ctx\n\treturn ctx\nend\n\nlocal function getCtx(station)\n\treturn stationCtx[station] or buildCtx(station)\nend\n\n-- Heavier weight for rarer athletes: rarity index = plates per side on bars and\n-- dumbbells (Common 1 ... Legendary 5), and more of the weight stack gets lifted.\nlocal IDLE_PLATES = 2\nlocal function plateCount(rarity)\n\treturn math.clamp(rarity or 1, 1, 5)\nend\nlocal function stackCount(rarity)\n\treturn 2 + 2 * math.clamp(rarity or 1, 1, 5)\nend\n\nlocal function setPlates(ctx, count)\n\tif ctx.PlatesShown == count then\n\t\treturn\n\tend\n\tctx.PlatesShown = count\n\tfor _, g in pairs(ctx.Groups) do\n\t\tfor i, p in ipairs(g.Parts) do\n\t\t\tlocal tier = g.Tier[i]\n\t\t\tif tier then\n\t\t\t\tp.Transparency = tier <= count and 0 or 1\n\t\t\tend\n\t\tend\n\tend\nend\n\nlocal function applyEquipment(ctx, e, rarity)\n\tsetPlates(ctx, plateCount(rarity))\n\tlocal lift = stackCount(rarity)\n\tfor name, cf in pairs(e.Moves) do\n\t\tlocal g = ctx.Groups[name]\n\t\tif g then\n\t\t\tfor i, p in ipairs(g.Parts) do\n\t\t\t\tlocal order = g.Order[i]\n\t\t\t\tif order and order > lift then\n\t\t\t\t\tqueue(p, g.Rest[i]) -- below the pin: stays down\n\t\t\t\telse\n\t\t\t\t\tqueue(p, cf * g.Rel[i])\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\tfor name, ab in pairs(e.Cables) do\n\t\tlocal c = ctx.Cables[name]\n\t\tif c then\n\t\t\tlocal len = (ab[2] - ab[1]).Magnitude\n\t\t\tif len > 0.05 then\n\t\t\t\tc.Part.Size = Vector3.new(len, c.RestSize.Y, c.RestSize.Z)\n\t\t\t\tqueue(c.Part, axisCF(ab[1], ab[2]))\n\t\t\tend\n\t\tend\n\tend\nend\n\nlocal function restoreEquipment(ctx)\n\tsetPlates(ctx, IDLE_PLATES)\n\tfor _, g in pairs(ctx.Groups) do\n\t\tfor i, p in ipairs(g.Parts) do\n\t\t\tqueue(p, g.Rest[i])\n\t\tend\n\tend\n\tfor _, c in pairs(ctx.Cables) do\n\t\tc.Part.Size = c.RestSize\n\t\tqueue(c.Part, c.RestCF)\n\tend\nend\n\n-- ----------------------------------------------------------------------\n-- Athletes\n-- ----------------------------------------------------------------------\nlocal active = {} -- [model] = state\nlocal lastPelvis = {} -- [model] = LowerTorso CFrame while walking (for blend-in)\nlocal warned = {}\n\nlocal function activate(model, station)\n\tlocal ctx = getCtx(station)\n\tif not ctx then\n\t\treturn nil\n\tend\n\tlocal ok, rig = pcall(RigSolver.new, model)\n\tif not ok then\n\t\treturn nil -- rig still streaming in; try again next frame\n\tend\n\treturn {\n\t\tModel = model,\n\t\tRig = rig,\n\t\tCtx = ctx,\n\t\tStation = station,\n\t\tSeatedAt = model:GetAttribute(\"SeatedAt\"),\n\t\tRarity = model:GetAttribute(\"Rarity\") or 1,\n\t\tP = Exercises.Params(model:GetAttribute(\"Seed\") or 1, model:GetAttribute(\"Rarity\") or 1),\n\t\tStartClock = os.clock(),\n\t\tStartPelvis = lastPelvis[model],\n\t}\nend\n\nlocal function deactivate(a)\n\tif a.Ctx then\n\t\trestoreEquipment(a.Ctx)\n\tend\n\tif a.Rig and a.Model.Parent then\n\t\ta.Rig:reset()\n\t\tpcall(function()\n\t\t\ta.Rig:apply()\n\t\tend)\n\tend\nend\n\nlocal function animate(a, now)\n\tlocal rig = a.Rig\n\trig:reset()\n\trig:setRootCFrame(nil)\n\tlocal t = now - (a.SeatedAt or now)\n\tlocal fn = Exercises[a.Ctx.Kind] or Exercises.Idle\n\tlocal ok, e = pcall(fn, rig, a.Ctx, math.max(t, 0), a.P)\n\tif not ok then\n\t\tif not warned[a.Ctx.Kind] then\n\t\t\twarned[a.Ctx.Kind] = true\n\t\t\twarn(\"[GymAnimator] \" .. tostring(a.Ctx.Kind) .. \": \" .. tostring(e))\n\t\tend\n\t\treturn\n\tend\n\n\tlocal k = (os.clock() - a.StartClock) / BLEND_TIME\n\tif k < 1 and a.StartPelvis then\n\t\tif not a.Snap then\n\t\t\ta.Snap = {}\n\t\t\tfor name in pairs(rig.T) do\n\t\t\t\ta.Snap[name] = CFrame.new()\n\t\t\tend\n\t\t\tlocal j = rig.J.Root\n\t\t\tlocal hrpCF = rig.Parts.HumanoidRootPart.CFrame\n\t\t\ta.Snap.Root = (hrpCF * j.C0):Inverse() * a.StartPelvis * j.C1\n\t\tend\n\t\trig:blendFrom(a.Snap, smooth(k))\n\tend\n\trig:apply()\n\tapplyEquipment(a.Ctx, e, a.Rarity)\nend\n\n-- ----------------------------------------------------------------------\n-- Conveyor chevrons\n-- ----------------------------------------------------------------------\nlocal chevrons = {}\nlocal chevSpacing = 8\ndo\n\tlocal belt = mapFolder:WaitForChild(\"Belt\", 10)\n\tlocal folder = belt and belt:FindFirstChild(\"Chevrons\")\n\tif folder then\n\t\tchevSpacing = folder:GetAttribute(\"Spacing\") or chevSpacing\n\t\tfor _, m in ipairs(folder:GetChildren()) do\n\t\t\tfor _, p in ipairs(m:GetDescendants()) do\n\t\t\t\tif p:IsA(\"BasePart\") then\n\t\t\t\t\ttable.insert(chevrons, { Part = p, Rest = p.CFrame })\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\nend\n\n-- ----------------------------------------------------------------------\n-- Belt posing idles (characters with a Poses attribute strike a pose every\n-- few seconds while riding the conveyor, layered over their idle animation)\n-- ----------------------------------------------------------------------\nlocal POSE_PERIOD, POSE_HOLD = 9, 3.2\nlocal POSE_JOINTS = Poses.JOINTS\nlocal beltRigs = {}\n\nlocal function beltPose(model, now, camPos)\n\tlocal hrp = model:FindFirstChild(\"HumanoidRootPart\")\n\tif not hrp or (hrp.Position - camPos).Magnitude > 170 then\n\t\treturn\n\tend\n\tlocal t = now + ((model:GetAttribute(\"Seed\") or 1) % 97)\n\tlocal cycle = math.floor(t / POSE_PERIOD)\n\tlocal u = t - cycle * POSE_PERIOD\n\tif u > POSE_HOLD then\n\t\treturn\n\tend\n\tlocal w = smooth(u / 0.45) * smooth((POSE_HOLD - u) / 0.45)\n\tif w <= 0.001 then\n\t\treturn\n\tend\n\tlocal rig = beltRigs[model]\n\tif rig == nil then\n\t\tlocal ok, r = pcall(RigSolver.new, model)\n\t\trig = ok and r or false\n\t\tbeltRigs[model] = rig\n\tend\n\tif not rig then\n\t\treturn\n\tend\n\tlocal poses = string.split(model:GetAttribute(\"Poses\"), \",\")\n\tlocal name = poses[(cycle % #poses) + 1]\n\trig:reset()\n\trig:setRootCFrame(nil)\n\tPoses.Apply(rig, name)\n\tfor _, jn in ipairs(POSE_JOINTS) do\n\t\tlocal j = rig.J[jn]\n\t\tif j then\n\t\t\tj.Inst.Transform = j.Inst.Transform:Lerp(rig.T[jn], w)\n\t\tend\n\tend\nend\n\n-- ----------------------------------------------------------------------\n-- Main loop (PreSimulation runs after the Animator, so our joint transforms win)\n-- ----------------------------------------------------------------------\nlocal promptAccum = 0\n\nRunService.PreSimulation:Connect(function(dt)\n\ttable.clear(bulkParts)\n\ttable.clear(bulkCFs)\n\tlocal now = workspace:GetServerTimeNow()\n\tlocal camPos = camera.CFrame.Position\n\n\t-- belt\n\tlocal speed = workspace:GetAttribute(\"BeltSpeed\") or Constants.BELT.Speed\n\tlocal off = (now * speed) % chevSpacing\n\tlocal dir = Vector3.new(0, 0, off)\n\tfor _, c in ipairs(chevrons) do\n\t\tqueue(c.Part, c.Rest + dir)\n\tend\n\n\tpromptAccum += dt\n\tlocal doPrompts = promptAccum > 0.3\n\tif doPrompts then\n\t\tpromptAccum = 0\n\tend\n\n\tif influencers then\n\t\tfor _, model in ipairs(influencers:GetChildren()) do\n\t\t\tlocal state = model:GetAttribute(\"State\")\n\t\t\tlocal ref = model:FindFirstChild(\"Station\")\n\t\t\tlocal station = ref and ref.Value\n\t\t\tlocal a = active[model]\n\t\t\tif state == \"Placed\" and station then\n\t\t\t\tlocal seatedAt = model:GetAttribute(\"SeatedAt\")\n\t\t\t\tif a and (a.Station ~= station or a.SeatedAt ~= seatedAt) then\n\t\t\t\t\tdeactivate(a)\n\t\t\t\t\ta = nil\n\t\t\t\t\tactive[model] = nil\n\t\t\t\tend\n\t\t\t\tif not a then\n\t\t\t\t\ta = activate(model, station)\n\t\t\t\t\tactive[model] = a\n\t\t\t\tend\n\t\t\t\tlocal hrp = model:FindFirstChild(\"HumanoidRootPart\")\n\t\t\t\tif a and hrp and (hrp.Position - camPos).Magnitude < ANIM_RANGE then\n\t\t\t\t\tanimate(a, now)\n\t\t\t\tend\n\t\t\t\tif doPrompts then\n\t\t\t\t\tlocal prompt = hrp and hrp:FindFirstChild(\"GrabPrompt\")\n\t\t\t\t\tif prompt then\n\t\t\t\t\t\tlocal mine = model:GetAttribute(\"OwnerUserId\") == player.UserId\n\t\t\t\t\t\tif mine and prompt.Enabled then\n\t\t\t\t\t\t\tprompt.Enabled = false\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\telse\n\t\t\t\tif a then\n\t\t\t\t\tdeactivate(a)\n\t\t\t\t\tactive[model] = nil\n\t\t\t\tend\n\t\t\t\tlocal lt = model:FindFirstChild(\"LowerTorso\")\n\t\t\t\tif lt then\n\t\t\t\t\tlastPelvis[model] = lt.CFrame\n\t\t\t\tend\n\t\t\t\t-- walkers strut; they only strike poses if they're standing still\n\t\t\t\tlocal root = model:FindFirstChild(\"HumanoidRootPart\")\n\t\t\t\tif state == \"OnBelt\" and model:GetAttribute(\"Poses\") and root and root.AssemblyLinearVelocity.Magnitude < 1 then\n\t\t\t\t\tbeltPose(model, now, camPos)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\tif #bulkParts > 0 then\n\t\tworkspace:BulkMoveTo(bulkParts, bulkCFs, Enum.BulkMoveMode.FireCFrameChanged)\n\tend\nend)\n\nif influencers then\n\tinfluencers.ChildRemoved:Connect(function(model)\n\t\tlocal a = active[model]\n\t\tactive[model] = nil\n\t\tlastPelvis[model] = nil\n\t\tbeltRigs[model] = nil\n\t\tif a and a.Ctx then\n\t\t\ttable.clear(bulkParts)\n\t\t\ttable.clear(bulkCFs)\n\t\t\trestoreEquipment(a.Ctx)\n\t\t\tworkspace:BulkMoveTo(bulkParts, bulkCFs, Enum.BulkMoveMode.FireCFrameChanged)\n\t\tend\n\tend)\nend\n\n-- [X] = let go of whoever is following you\nUIS.InputBegan:Connect(function(input, processed)\n\tif processed then\n\t\treturn\n\tend\n\tif input.KeyCode == Enum.KeyCode.X and (player:GetAttribute(\"Carrying\") or \"\") ~= \"\" then\n\t\tRemotes.DismissFollower:FireServer()\n\tend\nend)\n"},{"StarterPlayerScripts/MeshCharacters","LocalScript","--[[\n\tMeshCharacters\n\tDresses every rig tagged with a MeshCharacter attribute in its imported\n\tmodel (see ReplicatedStorage.Modules.MeshCharacter).\n]]\n\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal MeshCharacter = require(RS:WaitForChild(\"Modules\"):WaitForChild(\"MeshCharacter\"))\n\nlocal function consider(inst)\n\tif inst:IsA(\"Model\") and inst:GetAttribute(\"MeshCharacter\") then\n\t\ttask.spawn(MeshCharacter.Attach, inst)\n\tend\nend\n\nworkspace.DescendantAdded:Connect(consider)\nfor _, d in ipairs(workspace:GetDescendants()) do\n\tconsider(d)\nend\n"},{"StarterPlayerScripts/PortalFx","LocalScript","--[[\n\tPortalFx\n\tBrings the spawn / exit gates to life on each client (parts built by\n\ttools/map/Portal.luau, tagged with a \"PortalFx\" attribute):\n\t  Chase    marquee bulbs running around the sign and up the pillars\n\t  Pulse    the glowing portal disc breathing\n\t  Curtain  light-curtain slats shimmering\n\t  Sweep    searchlights sweeping the sky\n\t  Scan     a light bar gliding up and down the portal plane\n]]\n\nlocal RunService = game:GetService(\"RunService\")\n\nlocal map = workspace:WaitForChild(\"GymWarsMap\")\n\nlocal chase, pulse, curtain, sweep, scan = {}, {}, {}, {}, {}\nlocal BULB_ON = Color3.fromRGB(255, 240, 200)\nlocal BULB_OFF = Color3.fromRGB(90, 70, 40)\n\nlocal function register(p)\n\tif not p:IsA(\"BasePart\") then\n\t\treturn\n\tend\n\tlocal fx = p:GetAttribute(\"PortalFx\")\n\tif fx == \"Chase\" then\n\t\ttable.insert(chase, { Part = p, Index = p:GetAttribute(\"Index\") or 0 })\n\telseif fx == \"Pulse\" then\n\t\ttable.insert(pulse, { Part = p, Light = p:FindFirstChildOfClass(\"PointLight\") })\n\telseif fx == \"Curtain\" then\n\t\ttable.insert(curtain, { Part = p, Index = p:GetAttribute(\"Index\") or 0 })\n\telseif fx == \"Sweep\" then\n\t\ttable.insert(sweep, { Part = p, Rest = p.CFrame, Phase = p:GetAttribute(\"Phase\") or 0 })\n\telseif fx == \"Scan\" then\n\t\t-- remember the bar's frame at the bottom of its travel\n\t\tlocal low, high = p:GetAttribute(\"Low\") or 0, p:GetAttribute(\"High\") or 10\n\t\tlocal mid = (low + high) / 2\n\t\ttable.insert(scan, { Part = p, Base = p.CFrame * CFrame.new(0, low - mid, 0), Travel = high - low })\n\tend\nend\n\nfor _, d in ipairs(map:GetDescendants()) do\n\tregister(d)\nend\nmap.DescendantAdded:Connect(register)\n\nlocal lastStep = -1\nRunService.RenderStepped:Connect(function()\n\tlocal t = os.clock()\n\n\t-- marquee: every third bulb lit, marching along (only update on a step)\n\tlocal step = math.floor(t * 7)\n\tif step ~= lastStep then\n\t\tlastStep = step\n\t\tfor _, b in ipairs(chase) do\n\t\t\tlocal on = (b.Index + step) % 3 == 0\n\t\t\tb.Part.Color = on and BULB_ON or BULB_OFF\n\t\t\tb.Part.Transparency = on and 0 or 0.35\n\t\tend\n\tend\n\n\tfor _, p in ipairs(pulse) do\n\t\tlocal k = 0.5 + 0.5 * math.sin(t * 2.2)\n\t\tp.Part.Transparency = 0.1 + 0.25 * (1 - k)\n\t\tif p.Light then\n\t\t\tp.Light.Brightness = 2 + 2.5 * k\n\t\tend\n\tend\n\n\tfor _, c in ipairs(curtain) do\n\t\tc.Part.Transparency = 0.62 + 0.3 * (0.5 + 0.5 * math.sin(t * 5 + c.Index * 0.8))\n\tend\n\n\tfor _, b in ipairs(scan) do\n\t\t-- smooth ease up and down, a slow modern sweep\n\t\tlocal k = 0.5 - 0.5 * math.cos(t * 0.9)\n\t\tb.Part.CFrame = b.Base * CFrame.new(0, b.Travel * k, 0)\n\t\tb.Part.Transparency = 0.15 + 0.35 * math.abs(k - 0.5)\n\tend\n\n\tfor _, s in ipairs(sweep) do\n\t\tlocal yaw = math.sin(t * 0.6 + s.Phase) * 0.7\n\t\tlocal pitch = 0.12 * math.sin(t * 0.9 + s.Phase)\n\t\ts.Part.CFrame = s.Rest * CFrame.Angles(0, yaw, 0) * CFrame.Angles(pitch, 0, 0)\n\tend\nend)\n"},{"StarterPlayerScripts/DropClocks","LocalScript","--[[\n\tDropClocks\n\tCounts down the guaranteed drops on the clock board in the wall above the\n\tdrop gate (tools/map/ClockBoard.luau): a Legendary every 5 minutes, a\n\tMythic every 15. Times come from the server (workspace attributes\n\tGuaranteeLegendaryAt / GuaranteeMythicAt, in server time).\n]]\n\nlocal RunService = game:GetService(\"RunService\")\n\nlocal ROWS = {\n\t{ Name = \"Legendary\", Word = \"LEGENDARY\", Hex = \"#FFB02E\", Attr = \"GuaranteeLegendaryAt\" },\n\t{ Name = \"Mythic\", Word = \"MYTHIC\", Hex = \"#FF3878\", Attr = \"GuaranteeMythicAt\" },\n}\n\nlocal map = workspace:WaitForChild(\"GymWarsMap\")\n\nlocal function labels()\n\tlocal out = {}\n\tfor _, d in ipairs(map:GetDescendants()) do\n\t\tif d:IsA(\"SurfaceGui\") and d.Name == \"Clock\" then\n\t\t\tfor _, row in ipairs(ROWS) do\n\t\t\t\tlocal l = d:FindFirstChild(row.Name)\n\t\t\t\tif l then\n\t\t\t\t\ttable.insert(out, { Label = l, Row = row })\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\treturn out\nend\n\nlocal function fmt(seconds)\n\tseconds = math.max(0, math.floor(seconds))\n\treturn (\"%d:%02d\"):format(seconds // 60, seconds % 60)\nend\n\nlocal list = labels()\nmap.DescendantAdded:Connect(function(d)\n\tif d:IsA(\"SurfaceGui\") and d.Name == \"Clock\" then\n\t\ttask.defer(function()\n\t\t\tlist = labels()\n\t\tend)\n\tend\nend)\n\nlocal accum = 0\nRunService.Heartbeat:Connect(function(dt)\n\taccum += dt\n\tif accum < 0.2 then\n\t\treturn\n\tend\n\taccum = 0\n\tlocal now = workspace:GetServerTimeNow()\n\tfor _, e in ipairs(list) do\n\t\tlocal at = workspace:GetAttribute(e.Row.Attr)\n\t\tlocal left = at and (at - now) or nil\n\t\tlocal time = left and (left <= 0.5 and \"NOW\" or fmt(left)) or \"--:--\"\n\t\te.Label.Text = ('<font color=\"%s\">%s</font>   %s'):format(e.Row.Hex, e.Row.Word, time)\n\tend\nend)\n"},{"StarterPlayerScripts/NpcLocomotion","LocalScript","--[[\n\tNpcLocomotion\n\tWalk / run / idle for every NPC (influencers, front desk), played on this\n\tclient so it's smooth every frame (the server only moves them). Models are\n\tflagged by the server with the \"Loco\" attribute (false while working out).\n\n\t  - Rthro idle / walk / run (heavier, more natural gait), falling back to\n\t    the classic R15 set if those don't load\n\t  - Walk/run blended and speed-matched to how fast they move\n\t  - Bodybuilder swagger: arms carried out from the body (more for bigger\n\t    rarities) so big arms don't clip through the lats and thighs\n]]\n\nlocal RunService = game:GetService(\"RunService\")\n\nlocal SETS = {\n\tRthro = { Idle = \"rbxassetid://2510196951\", Walk = \"rbxassetid://2510202577\", Run = \"rbxassetid://2510198475\" },\n\tClassic = { Idle = \"rbxassetid://507766388\", Walk = \"rbxassetid://507777826\", Run = \"rbxassetid://507767714\" },\n}\n\nlocal rigs = {} -- [model] = state\n\nlocal function loadSet(animator, ids)\n\tlocal tracks = {}\n\tfor key, id in pairs(ids) do\n\t\tlocal anim = Instance.new(\"Animation\")\n\t\tanim.AnimationId = id\n\t\tlocal ok, track = pcall(function()\n\t\t\treturn animator:LoadAnimation(anim)\n\t\tend)\n\t\tif not ok or not track then\n\t\t\treturn nil\n\t\tend\n\t\ttrack.Looped = true\n\t\ttrack.Priority = Enum.AnimationPriority.Core\n\t\ttracks[key] = track\n\tend\n\treturn tracks\nend\n\nlocal function loaded(tracks)\n\tfor _, t in pairs(tracks) do\n\t\tif t.Length <= 0 then\n\t\t\treturn false\n\t\tend\n\tend\n\treturn true\nend\n\nlocal function stopAll(state)\n\tif state.Tracks then\n\t\tfor _, t in pairs(state.Tracks) do\n\t\t\tt:Stop(0.25)\n\t\tend\n\tend\nend\n\nlocal function findJoint(model, name)\n\tfor _, d in ipairs(model:GetDescendants()) do\n\t\tif d.Name == name and (d:IsA(\"Motor6D\") or d:IsA(\"AnimationConstraint\")) then\n\t\t\treturn d\n\t\tend\n\tend\n\treturn nil\nend\n\nlocal function track(model)\n\tif rigs[model] then\n\t\treturn\n\tend\n\tlocal hum = model:FindFirstChildOfClass(\"Humanoid\")\n\tlocal animator = hum and hum:FindFirstChildOfClass(\"Animator\")\n\tlocal root = model:FindFirstChild(\"HumanoidRootPart\")\n\tif not (hum and animator and root) then\n\t\treturn\n\tend\n\tlocal state = { Model = model, Humanoid = hum, Root = root, Weights = { 1, 0, 0 } }\n\trigs[model] = state\n\ttask.spawn(function()\n\t\t-- prefer Rthro; use the classic clips if those never load\n\t\tlocal tracks = loadSet(animator, SETS.Rthro)\n\t\tlocal t0 = os.clock()\n\t\twhile tracks and not loaded(tracks) and os.clock() - t0 < 4 do\n\t\t\ttask.wait(0.2)\n\t\tend\n\t\tif not (tracks and loaded(tracks)) then\n\t\t\tif tracks then\n\t\t\t\tfor _, t in pairs(tracks) do\n\t\t\t\t\tt:Destroy()\n\t\t\t\tend\n\t\t\tend\n\t\t\ttracks = loadSet(animator, SETS.Classic)\n\t\tend\n\t\tif rigs[model] == state then\n\t\t\tstate.Tracks = tracks\n\t\tend\n\tend)\n\tstate.LeftShoulder = findJoint(model, \"LeftShoulder\")\n\tstate.RightShoulder = findJoint(model, \"RightShoulder\")\n\t-- arms out a little for regular guys, a lot for the mass monsters\n\tlocal rarity = model:GetAttribute(\"Rarity\") or 1\n\tstate.Spread = math.rad(4 + 2 * rarity)\n\tmodel.Destroying:Connect(function()\n\t\trigs[model] = nil\n\tend)\nend\n\n-- The server sets \"Loco\" right after spawning, and it can reach this client a\n-- moment AFTER the model itself does, so wait for the flag instead of checking once.\nlocal watched = setmetatable({}, { __mode = \"k\" })\nlocal function consider(inst)\n\tif not inst:IsA(\"Model\") or watched[inst] then\n\t\treturn\n\tend\n\tif inst:GetAttribute(\"Loco\") ~= nil then\n\t\twatched[inst] = true\n\t\ttrack(inst)\n\t\treturn\n\tend\n\tif inst:FindFirstChildOfClass(\"Humanoid\") then\n\t\twatched[inst] = true\n\t\tlocal conn\n\t\tconn = inst:GetAttributeChangedSignal(\"Loco\"):Connect(function()\n\t\t\tconn:Disconnect()\n\t\t\ttrack(inst)\n\t\tend)\n\tend\nend\n\nfor _, d in ipairs(workspace:GetDescendants()) do\n\tconsider(d)\nend\nworkspace.DescendantAdded:Connect(function(d)\n\tif d:IsA(\"Model\") then\n\t\ttask.defer(consider, d)\n\telseif d:IsA(\"Humanoid\") and d.Parent then\n\t\t-- the humanoid can replicate after its model\n\t\ttask.defer(consider, d.Parent)\n\tend\nend)\n\n-- Blend walk/run by ground speed (mirrors Roblox's Animate script)\nRunService.Heartbeat:Connect(function(dt)\n\tfor model, state in pairs(rigs) do\n\t\tif not model.Parent then\n\t\t\trigs[model] = nil\n\t\t\tcontinue\n\t\tend\n\t\tlocal tracks = state.Tracks\n\t\tif not tracks then\n\t\t\tcontinue\n\t\tend\n\t\tlocal active = model:GetAttribute(\"Loco\") ~= false and not state.Root.Anchored\n\t\tif not active then\n\t\t\tif state.Playing then\n\t\t\t\tstopAll(state)\n\t\t\t\tstate.Playing = false\n\t\t\tend\n\t\t\tcontinue\n\t\tend\n\t\tif not state.Playing then\n\t\t\tfor _, t in pairs(tracks) do\n\t\t\t\tt:Play(0.25, 0.001, 1)\n\t\t\tend\n\t\t\tstate.Playing = true\n\t\tend\n\t\tlocal v = state.Root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)\n\t\tlocal speed = v.Magnitude\n\t\tlocal heightScale = math.max(state.Humanoid.HipHeight / 2, 0.5)\n\t\tlocal rs = speed * 1.25 / 16 / heightScale\n\t\tlocal wIdle, wWalk, wRun, warp = 0, 0, 0, 1\n\t\tif speed < 0.6 then\n\t\t\twIdle = 1\n\t\telseif rs <= 0.5 then\n\t\t\twWalk, warp = 1, rs / 0.5\n\t\telseif rs < 1 then\n\t\t\tlocal f = (rs - 0.5) / 0.5\n\t\t\twWalk, wRun = 1 - f, f\n\t\telse\n\t\t\twRun, warp = 1, rs\n\t\tend\n\t\tlocal k = math.clamp(dt * 8, 0, 1)\n\t\tlocal w = state.Weights\n\t\tw[1] += (wIdle - w[1]) * k\n\t\tw[2] += (wWalk - w[2]) * k\n\t\tw[3] += (wRun - w[3]) * k\n\t\ttracks.Idle:AdjustWeight(math.max(w[1], 0.001), 0.1)\n\t\ttracks.Walk:AdjustWeight(math.max(w[2], 0.001), 0.1)\n\t\ttracks.Run:AdjustWeight(math.max(w[3], 0.001), 0.1)\n\t\ttracks.Idle:AdjustSpeed(model:GetAttribute(\"IdleSpeed\") or 1)\n\t\ttracks.Walk:AdjustSpeed(math.max(warp, 0.1))\n\t\ttracks.Run:AdjustSpeed(math.max(warp, 0.1))\n\tend\nend)\n\n-- Swagger layer: after the Animator has posed the rig, carry the arms out.\nRunService.PreSimulation:Connect(function()\n\tfor model, state in pairs(rigs) do\n\t\tif state.Playing and model:GetAttribute(\"Loco\") ~= false then\n\t\t\tlocal a = state.Spread\n\t\t\tif state.LeftShoulder then\n\t\t\t\tstate.LeftShoulder.Transform = state.LeftShoulder.Transform * CFrame.Angles(0, 0, -a)\n\t\t\tend\n\t\t\tif state.RightShoulder then\n\t\t\t\tstate.RightShoulder.Transform = state.RightShoulder.Transform * CFrame.Angles(0, 0, a)\n\t\t\tend\n\t\tend\n\tend\nend)\n"}} local PATCH={{"Gate","--[[\n\tGate — minimalist teleporter set into the world wall.\n\n\t  Gate.Build(parent, name, faceCF, color, label, width, height, depth) -> Model\n\n\tfaceCF: ground center of the doorway on the wall's inner face; -Z points\n\tout into the world. The wall itself leaves the opening (Walls.Build with an\n\topening); the gate lines it: matte black surround, one thin neon outline,\n\tblack reveals, a glowing portal plane recessed in the wall with a light bar\n\tthat sweeps up and down, and a clean label.\n\n\tPure Roblox API: the same code builds the map offline and patches a live\n\tplace. \"PortalFx\" parts are animated by StarterPlayerScripts.PortalFx\n\t(Pulse = portal plane, Scan = light bar). Neon lines are named\n\t\"TunnelGlow\" so rarity spawns flash them.\n]]\n\nlocal Gate = {}\n\nlocal MATTE = Color3.fromRGB(16, 16, 19)\nlocal SATIN = Color3.fromRGB(28, 28, 33)\n\nlocal function part(parent, name, size, cf, color, material, opts)\n\tlocal p = Instance.new(\"Part\")\n\tp.Name = name\n\tp.Anchored = true\n\tp.Size = size\n\tp.CFrame = cf\n\tp.Color = color\n\tp.Material = material or Enum.Material.SmoothPlastic\n\tp.TopSurface = Enum.SurfaceType.Smooth\n\tp.BottomSurface = Enum.SurfaceType.Smooth\n\topts = opts or {}\n\tif opts.Decor then\n\t\tp.CanCollide = false\n\t\tp.CanTouch = false\n\t\tp.CanQuery = false\n\tend\n\tif opts.Transparency then\n\t\tp.Transparency = opts.Transparency\n\tend\n\tif opts.Reflectance then\n\t\tp.Reflectance = opts.Reflectance\n\tend\n\tif opts.NoShadow then\n\t\tp.CastShadow = false\n\tend\n\tif opts.Fx then\n\t\tp:SetAttribute(\"PortalFx\", opts.Fx)\n\tend\n\tp.Parent = parent\n\treturn p\nend\n\nfunction Gate.Build(parent, name, faceCF, color, label, width, height, depth)\n\tlocal W, H, D = width or 12, height or 18, depth or 4\n\tlocal m = Instance.new(\"Model\")\n\tm.Name = name\n\tm:SetAttribute(\"Portal\", true)\n\tlocal function at(x, y, z)\n\t\treturn faceCF * CFrame.new(x, y, z)\n\tend\n\n\t-- matte surround, slightly proud of the stone\n\tlocal J = 2.2 -- jamb width\n\tfor _, s in ipairs({ -1, 1 }) do\n\t\tpart(m, \"Surround\", Vector3.new(J, H + J, 1), at(s * (W / 2 + J / 2), (H + J) / 2, -0.5), MATTE, Enum.Material.SmoothPlastic, { Reflectance = 0.04 })\n\tend\n\tlocal header = part(m, \"Surround\", Vector3.new(W + J * 2, J, 1), at(0, H + J / 2, -0.5), MATTE, Enum.Material.SmoothPlastic, { Reflectance = 0.04 })\n\n\t-- one thin neon outline around the opening, plus the threshold line\n\tlocal g = 0.22\n\tfor _, s in ipairs({ -1, 1 }) do\n\t\tpart(m, \"TunnelGlow\", Vector3.new(g, H, g), at(s * (W / 2 + g / 2), H / 2, -1.02), color, Enum.Material.Neon, { Decor = true, NoShadow = true })\n\tend\n\tpart(m, \"TunnelGlow\", Vector3.new(W + g * 2, g, g), at(0, H + g / 2, -1.02), color, Enum.Material.Neon, { Decor = true, NoShadow = true })\n\tpart(m, \"TunnelGlow\", Vector3.new(W, 0.06, g), at(0, 0.15, -1.1), color, Enum.Material.Neon, { Decor = true, NoShadow = true })\n\n\t-- black reveals lining the doorway through the wall + a satin floor plate\n\tfor _, s in ipairs({ -1, 1 }) do\n\t\tpart(m, \"Reveal\", Vector3.new(0.3, H, D), at(s * (W / 2 - 0.15), H / 2, D / 2), SATIN, Enum.Material.SmoothPlastic, { Decor = true })\n\tend\n\tpart(m, \"Reveal\", Vector3.new(W, 0.3, D), at(0, H - 0.15, D / 2), SATIN, Enum.Material.SmoothPlastic, { Decor = true })\n\tpart(m, \"FloorPlate\", Vector3.new(W, 0.14, D + 2), at(0, 0.07, D / 2 - 1), SATIN, Enum.Material.SmoothPlastic, { Reflectance = 0.12 })\n\n\t-- the portal plane, recessed in the wall, and the scanning light bar\n\tlocal plane = part(m, \"PortalPlane\", Vector3.new(W - 0.6, H - 0.6, 0.2), at(0, H / 2, D * 0.45), color, Enum.Material.Neon, { Decor = true, Transparency = 0.2, NoShadow = true, Fx = \"Pulse\" })\n\tlocal light = Instance.new(\"PointLight\")\n\tlight.Color = color\n\tlight.Range = 18\n\tlight.Brightness = 2.5\n\tlight.Parent = plane\n\tlocal shimmer = Instance.new(\"ParticleEmitter\")\n\tshimmer.Name = \"Shimmer\"\n\tshimmer.EmissionDirection = Enum.NormalId.Front\n\tshimmer.Color = ColorSequence.new(Color3.new(1, 1, 1), color)\n\tshimmer.LightEmission = 1\n\tshimmer.Rate = 10\n\tshimmer.Lifetime = NumberRange.new(1.5, 2.5)\n\tshimmer.Speed = NumberRange.new(0.6, 1.6)\n\tshimmer.SpreadAngle = Vector2.new(20, 20)\n\tshimmer.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.18), NumberSequenceKeypoint.new(1, 0) })\n\tshimmer.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.2), NumberSequenceKeypoint.new(1, 1) })\n\tshimmer.Parent = plane\n\tlocal bar = part(m, \"ScanBar\", Vector3.new(W - 0.6, 0.12, 0.1), at(0, H / 2, D * 0.45 - 0.2), Color3.new(1, 1, 1), Enum.Material.Neon, { Decor = true, Transparency = 0.25, NoShadow = true, Fx = \"Scan\" })\n\tbar:SetAttribute(\"Low\", 0.6)\n\tbar:SetAttribute(\"High\", H - 0.6)\n\t-- solid back so nothing outside the wall shows through the portal\n\tpart(m, \"Backstop\", Vector3.new(W + 2, H + 2, 1), at(0, H / 2, D + 0.5), MATTE, Enum.Material.SmoothPlastic)\n\n\t-- clean label on the header\n\tlocal gui = Instance.new(\"SurfaceGui\")\n\tgui.Name = \"Label\"\n\tgui.Face = Enum.NormalId.Front\n\tgui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud\n\tgui.PixelsPerStud = 50\n\tgui.LightInfluence = 0\n\tgui.Brightness = 1.3\n\tgui.Parent = header\n\tlocal text = Instance.new(\"TextLabel\")\n\ttext.Size = UDim2.new(0.8, 0, 0.42, 0)\n\ttext.Position = UDim2.new(0.1, 0, 0.29, 0)\n\ttext.BackgroundTransparency = 1\n\ttext.Font = Enum.Font.GothamMedium\n\ttext.TextScaled = true\n\ttext.TextColor3 = Color3.fromRGB(240, 242, 248)\n\ttext.Text = label\n\ttext.Parent = gui\n\n\tm.Parent = parent\n\treturn m\nend\n\nreturn Gate\n"},{"ClockBoard","--[[\n\tClockBoard — the guaranteed-drop clocks set into the wall above the drop gate.\n\n\t  ClockBoard.Build(parent, faceCF, gateTop) -> Model \"DropClock\"\n\n\tfaceCF: ground center of the gate on the wall's inner face (-Z = out into\n\tthe world), same frame Gate.Build uses. A matte black panel with two rows:\n\t\"LEGENDARY  4:32\" and \"MYTHIC  12:10\"; only the rarity word is colored\n\t(RichText). StarterPlayerScripts.DropClocks fills in the times from the\n\tworkspace attributes GuaranteeLegendaryAt / GuaranteeMythicAt.\n\tPure Roblox API (shared by the map builder and the live patch).\n]]\n\nlocal ClockBoard = {}\n\nlocal MATTE = Color3.fromRGB(16, 16, 19)\n\nlocal function part(parent, name, size, cf, color, material, decor)\n\tlocal p = Instance.new(\"Part\")\n\tp.Name = name\n\tp.Anchored = true\n\tp.Size = size\n\tp.CFrame = cf\n\tp.Color = color\n\tp.Material = material\n\tp.TopSurface = Enum.SurfaceType.Smooth\n\tp.BottomSurface = Enum.SurfaceType.Smooth\n\tif decor then\n\t\tp.CanCollide = false\n\t\tp.CanTouch = false\n\t\tp.CanQuery = false\n\t\tp.CastShadow = false\n\tend\n\tp.Parent = parent\n\treturn p\nend\n\nClockBoard.ROWS = {\n\t{ Name = \"Legendary\", Word = \"LEGENDARY\", Hex = \"#FFB02E\" },\n\t{ Name = \"Mythic\", Word = \"MYTHIC\", Hex = \"#FF3878\" },\n}\n\nfunction ClockBoard.Build(parent, faceCF, gateTop)\n\tlocal m = Instance.new(\"Model\")\n\tm.Name = \"DropClock\"\n\tlocal y = (gateTop or 20.2) + 1 + 3.5\n\tlocal face = part(m, \"ClockFace\", Vector3.new(22, 7, 0.6), faceCF * CFrame.new(0, y, -0.3), MATTE, Enum.Material.SmoothPlastic)\n\tface.Reflectance = 0.04\n\t-- hairline between the rows\n\tpart(m, \"ClockRule\", Vector3.new(18, 0.06, 0.05), faceCF * CFrame.new(0, y, -0.63), Color3.fromRGB(70, 70, 78), Enum.Material.SmoothPlastic, true)\n\n\tlocal gui = Instance.new(\"SurfaceGui\")\n\tgui.Name = \"Clock\"\n\tgui.Face = Enum.NormalId.Front\n\tgui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud\n\tgui.PixelsPerStud = 50\n\tgui.LightInfluence = 0\n\tgui.Brightness = 1.4\n\tgui.Parent = face\n\tfor i, row in ipairs(ClockBoard.ROWS) do\n\t\tlocal label = Instance.new(\"TextLabel\")\n\t\tlabel.Name = row.Name\n\t\tlabel.Size = UDim2.new(0.84, 0, 0.3, 0)\n\t\tlabel.Position = UDim2.new(0.08, 0, i == 1 and 0.12 or 0.58, 0)\n\t\tlabel.BackgroundTransparency = 1\n\t\tlabel.Font = Enum.Font.GothamMedium\n\t\tlabel.TextScaled = true\n\t\tlabel.RichText = true\n\t\tlabel.TextColor3 = Color3.fromRGB(240, 242, 248)\n\t\tlabel.Text = ('<font color=\"%s\">%s</font>   --:--'):format(row.Hex, row.Word)\n\t\tlabel.Parent = gui\n\tend\n\n\tm.Parent = parent\n\treturn m\nend\n\nreturn ClockBoard\n"},{"Walls","--[[\n\tWalls — the tall stone boundary around the world.\n\n\t  Walls.Build(parent, halfX, halfZ, height, opening) -> Folder \"WorldWalls\"\n\n\tA closed rectangle just outside (halfX, halfZ): thick fieldstone wall with a\n\tslate cap, stepped plinth, buttress pilasters with lanterns, and an ivy\n\thedge planted along the inside. `opening` ({ Width, Height }) cuts a\n\tdoorway in the middle of both end walls (z = -/+) for the teleport gates.\n\tPure Roblox API, shared by the map builder and the live command-bar patch.\n]]\n\nlocal Walls = {}\n\nlocal STONE = Color3.fromRGB(122, 118, 110)\nlocal STONE_DARK = Color3.fromRGB(96, 92, 86)\nlocal CAP = Color3.fromRGB(70, 70, 74)\nlocal IVY = Color3.fromRGB(48, 78, 36)\nlocal LANTERN = Color3.fromRGB(255, 226, 170)\n\nlocal function part(parent, name, size, cf, color, material, decor)\n\tlocal p = Instance.new(\"Part\")\n\tp.Name = name\n\tp.Anchored = true\n\tp.Size = size\n\tp.CFrame = cf\n\tp.Color = color\n\tp.Material = material\n\tp.TopSurface = Enum.SurfaceType.Smooth\n\tp.BottomSurface = Enum.SurfaceType.Smooth\n\tif decor then\n\t\tp.CanCollide = false\n\t\tp.CanTouch = false\n\t\tp.CanQuery = false\n\tend\n\tp.Parent = parent\n\treturn p\nend\n\n-- pieces of [a, b] (along the wall) that avoid the gap [-g, g]\nlocal function around(a, b, g)\n\tif not g then\n\t\treturn { { a, b } }\n\tend\n\treturn { { a, -g }, { g, b } }\nend\n\nfunction Walls.Build(parent, halfX, halfZ, height, opening)\n\tlocal f = Instance.new(\"Folder\")\n\tf.Name = \"WorldWalls\"\n\tlocal H = height or 30\n\tlocal T = 4\n\tlocal ox, oz = halfX + T / 2, halfZ + T / 2\n\t-- each side: center, length, inward direction, has the gate opening\n\tlocal sides = {\n\t\t{ CFrame.new(-ox, 0, 0), oz * 2 + T, Vector3.new(1, 0, 0), false },\n\t\t{ CFrame.new(ox, 0, 0), oz * 2 + T, Vector3.new(-1, 0, 0), false },\n\t\t{ CFrame.new(0, 0, -oz) * CFrame.Angles(0, math.rad(90), 0), ox * 2 + T, Vector3.new(0, 0, 1), true },\n\t\t{ CFrame.new(0, 0, oz) * CFrame.Angles(0, math.rad(90), 0), ox * 2 + T, Vector3.new(0, 0, -1), true },\n\t}\n\tfor _, sd in ipairs(sides) do\n\t\tlocal cf, len, inward, gated = sd[1], sd[2], sd[3], sd[4]\n\t\tlocal gap = (gated and opening) and opening.Width / 2 or nil\n\t\tlocal oh = (gated and opening) and opening.Height or 0\n\t\tlocal inX = (cf - cf.Position):PointToObjectSpace(inward).X\n\t\t-- local frame: wall runs along Z, thickness along X\n\t\tfor _, seg in ipairs(around(-len / 2, len / 2, gap)) do\n\t\t\tlocal l, c = seg[2] - seg[1], (seg[1] + seg[2]) / 2\n\t\t\tpart(f, \"WorldWall\", Vector3.new(T, H, l), cf * CFrame.new(0, H / 2, c), STONE, Enum.Material.Cobblestone)\n\t\t\tpart(f, \"WallPlinth\", Vector3.new(T + 1.6, 2.4, l), cf * CFrame.new(0, 1.2, c), STONE_DARK, Enum.Material.Slate)\n\t\tend\n\t\tfor _, seg in ipairs(around(-len / 2 + 3, len / 2 - 3, gap and gap + 3.5)) do\n\t\t\tlocal l, c = seg[2] - seg[1], (seg[1] + seg[2]) / 2\n\t\t\tpart(f, \"WallIvy\", Vector3.new(2.4, 5, l), cf * CFrame.new(inX * (T / 2 + 1.5), 2.5, c), IVY, Enum.Material.LeafyGrass, true)\n\t\tend\n\t\tif gap then\n\t\t\t-- wall continues above the doorway\n\t\t\tpart(f, \"WorldWall\", Vector3.new(T, H - oh, gap * 2), cf * CFrame.new(0, oh + (H - oh) / 2, 0), STONE, Enum.Material.Cobblestone)\n\t\tend\n\t\tpart(f, \"WallCap\", Vector3.new(T + 1.2, 1.2, len + 1), cf * CFrame.new(0, H + 0.6, 0), CAP, Enum.Material.Slate)\n\t\tpart(f, \"WallCoping\", Vector3.new(T + 0.4, 0.6, len), cf * CFrame.new(0, H + 1.5, 0), STONE_DARK, Enum.Material.Slate)\n\t\t-- buttress pilasters with a lantern on top (none in front of the gate)\n\t\tlocal n = math.max(2, math.floor(len / 32))\n\t\tfor k = 0, n do\n\t\t\tlocal z = -len / 2 + k * len / n\n\t\t\tif not gap or math.abs(z) > gap + 6 then\n\t\t\t\tlocal pc = cf * CFrame.new(inX * 1.2, 0, z)\n\t\t\t\tpart(f, \"Pilaster\", Vector3.new(T + 2.6, H + 3, 5), pc * CFrame.new(0, (H + 3) / 2, 0), STONE_DARK, Enum.Material.Cobblestone)\n\t\t\t\tpart(f, \"PilasterCap\", Vector3.new(T + 3.4, 1, 5.8), pc * CFrame.new(0, H + 3.5, 0), CAP, Enum.Material.Slate)\n\t\t\t\tlocal lamp = part(f, \"WallLantern\", Vector3.new(1.4, 2, 1.4), pc * CFrame.new(0, H + 5, 0), LANTERN, Enum.Material.Neon, true)\n\t\t\t\tlamp.CastShadow = false\n\t\t\t\tif k % 2 == 0 then\n\t\t\t\t\tlocal light = Instance.new(\"PointLight\")\n\t\t\t\t\tlight.Color = LANTERN\n\t\t\t\t\tlight.Range = 22\n\t\t\t\t\tlight.Brightness = 0.9\n\t\t\t\t\tlight.Parent = lamp\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\tf.Parent = parent\n\treturn f\nend\n\nreturn Walls\n"}} do local SS=game:GetService("ServerStorage") local RS=game:GetService("ReplicatedStorage") local SSS=game:GetService("ServerScriptService") local SPS=game:GetService("StarterPlayer"):FindFirstChildOfClass("StarterPlayerScripts") local map=workspace:FindFirstChild("GymWarsMap") if not map then warn("GymWarsMap not found") return end local n=0 local kill={Promenade=true,Curb=true,Walkway=true,WalkCurb=true} for _,d in ipairs(map:GetDescendants()) do if d:IsA("BasePart") and kill[d.Name] then d:Destroy() n+=1 end end local belt=map:FindFirstChild("Belt") if belt then for _,d in ipairs(belt:GetDescendants()) do if d:IsA("BasePart") and (d.Name=="BeltTrack" or d.Name=="BeltSkirt" or d.Name=="BeltGlow" or d.Name=="RailLeft" or d.Name=="RailRight") then d:Destroy() n+=1 end end local ch=belt:FindFirstChild("Chevrons") if ch then ch:Destroy() end end for _,root in ipairs({map,SS:FindFirstChild("HiddenGymFloors")}) do if root then for _,d in ipairs(root:GetDescendants()) do if d:IsA("BasePart") then if d.Name=="RoofSlab" then d.Material=Enum.Material.Slate elseif d.Name=="TunnelLeft" or d.Name=="TunnelRight" or d.Name=="TunnelTop" then d.Material=Enum.Material.Metal end end end end end local sp=workspace:FindFirstChild("SpawnLocation") if sp then sp.Color=Color3.fromRGB(88,148,66) sp.Material=Enum.Material.Grass end local tmp=SS:FindFirstChild("_GymWarsPatch") if tmp then tmp:Destroy() end tmp=Instance.new("Folder") tmp.Name="_GymWarsPatch" tmp.Parent=SS local M={} for _,pm in ipairs(PATCH) do local ms=Instance.new("ModuleScript") ms.Name=pm[1] ms.Source=pm[2] ms.Parent=tmp M[pm[1]]=require(ms) end local LOTX,HX,HZ=118,176,178 local env=map:FindFirstChild("Environment") local plotsF=map:FindFirstChild("Plots") local dx=LOTX-(map:GetAttribute("LotX") or 106) local function anyPos(c) if c:IsA("BasePart") then return c.CFrame.Position end for _,d in ipairs(c:GetDescendants()) do if d:IsA("BasePart") then return d.CFrame.Position end end return nil end local function shift(c,off) if c:IsA("BasePart") then c.CFrame=c.CFrame+off end for _,d in ipairs(c:GetDescendants()) do if d:IsA("BasePart") then d.CFrame=d.CFrame+off end end if c:IsA("Model") then pcall(function() c.WorldPivot=c.WorldPivot+off end) end end if dx~=0 and plotsF then for _,plot in ipairs(plotsF:GetChildren()) do local fl=plot:FindFirstChild("Floor") if fl then local side=fl.CFrame.Position.X>0 and 1 or -1 local off=Vector3.new(side*dx,0,0) shift(plot,off) local hid=SS:FindFirstChild("HiddenGymFloors") and SS.HiddenGymFloors:FindFirstChild(plot.Name) if hid then for _,d in ipairs(hid:GetDescendants()) do if d:IsA("BasePart") then d.CFrame=d.CFrame+off end end end end end local keep={Ground=true,RedCarpet=true,CarpetEdge=true} local movers={} if env then for _,c in ipairs(env:GetChildren()) do table.insert(movers,c) end local nat=env:FindFirstChild("Nature") if nat then for _,c in ipairs(nat:GetChildren()) do table.insert(movers,c) end end end for _,c in ipairs(movers) do if (c:IsA("BasePart") or c:IsA("Model")) and not keep[c.Name] then local pos=anyPos(c) if pos and math.abs(pos.X)>=30 then shift(c,Vector3.new((pos.X>0 and 1 or -1)*dx,0,0)) end end end map:SetAttribute("LotX",LOTX) end if env then for _,c in ipairs(env:GetChildren()) do if c.Name=="StoneWall" or c.Name=="WallCap" or c.Name=="Hedge" or c.Name=="GatePillar" or c.Name=="PillarCap" or c.Name=="PillarLamp" or c.Name=="WorldWalls" then c:Destroy() end end local g=env:FindFirstChild("Ground") if g then g.Size=Vector3.new(HX*2+60,g.Size.Y,g.Size.Z) end M.Walls.Build(env,HX,HZ,30,{Width=12,Height=18}) for _,c in ipairs(env:GetChildren()) do if c:IsA("BasePart") and (c.Name=="RedCarpet" or c.Name=="CarpetEdge") then c.Size=Vector3.new(c.Size.X,c.Size.Y,HZ*2) end end end if belt then for _,nm in ipairs({"DropTunnel","ExitTunnel","DropGate","ExitGate","DropClock"}) do local o=belt:FindFirstChild(nm) if o then o:Destroy() end end M.Gate.Build(belt,"DropGate",CFrame.new(0,0,-HZ)*CFrame.Angles(0,math.pi,0),Color3.fromRGB(60,170,255),"INFLUENCER DROP",12,18,4) M.Gate.Build(belt,"ExitGate",CFrame.new(0,0,HZ),Color3.fromRGB(255,70,90),"LAST CHANCE",12,18,4) M.ClockBoard.Build(belt,CFrame.new(0,0,-HZ)*CFrame.Angles(0,math.pi,0),20.2) local dp=belt:FindFirstChild("DropPoint") if dp then dp.CFrame=CFrame.new(0,3.5,-HZ-1) end local bs=belt:FindFirstChild("BeltStart") if bs then bs.CFrame=CFrame.new(0,3,-HZ+1) end local be=belt:FindFirstChild("BeltEnd") if be then be.CFrame=CFrame.new(0,3,HZ+1.2) end end tmp:Destroy() local FY,FH=0.4,16 local function ft(f) return FY+(f-1)*FH end local function mk(parent,name,size,cf,visible) local p=Instance.new("Part") p.Name=name p.Anchored=true p.Size=size p.CFrame=cf p.Transparency=1 p.CastShadow=false p.Material=Enum.Material.SmoothPlastic if not visible then p.CanCollide=false p.CanTouch=false p.CanQuery=false end p.Parent=parent return p end local plots=map:FindFirstChild("Plots") local ramps=0 for _,plot in ipairs(plots and plots:GetChildren() or {}) do local floor=plot:FindFirstChild("Floor") if floor then local base=floor.CFrame*CFrame.new(0,-floor.Size.Y/2,0) local function L(x,y,z) return base*CFrame.new(x,y,z) end local hidden=SS:FindFirstChild("HiddenGymFloors") and SS.HiddenGymFloors:FindFirstChild(plot.Name) for f=2,3 do local folder=plot:FindFirstChild("Floor"..f) or (hidden and hidden:FindFirstChild("Floor"..f)) if folder then for _,d in ipairs(folder:GetChildren()) do if d.Name=="StairRamp" then d:Destroy() end end local y0=ft(f-1) local ym=y0+FH/2 local y1=y0+FH for _,fl in ipairs({{18,15,30,y0,ym+0.5},{24,30,15,ym+0.5,y1}}) do local a=L(fl[1],fl[4],fl[2]).Position local b=L(fl[1],fl[5],fl[3]).Position local r=mk(folder,"StairRamp",Vector3.new(6,1.2,(b-a).Magnitude+0.2),CFrame.lookAt((a+b)/2,b)*CFrame.new(0,-0.6,0),true) ramps+=1 end end end local old=plot:FindFirstChild("Nav") if old then old:Destroy() end local nav=Instance.new("Folder") nav.Name="Nav" nav.Parent=plot local one=Vector3.new(1,1,1) local function np(name,x,y,z) mk(nav,name,one,L(x,y,z)) end np("DoorOut",0,FY,-40) np("Lobby",0,FY,-30) for f=1,3 do np("Cross"..f,0,ft(f),12.5) if f<3 then np("StairFoot"..f,18,ft(f),12.5) np("LandA"..f,18,ft(f)+8.5,32.5) np("LandB"..f,24,ft(f)+8.5,32.5) np("StairTop"..(f+1),24,ft(f+1),12.5) end end np("F3Turn",24,ft(3),14) np("F3Lane",9.5,ft(3),14) local fp=floor.CFrame.Position mk(nav,"Yard",one,CFrame.new((fp.X>0 and 1 or -1)*17,0,fp.Z)) nav:SetAttribute("FloorY",FY) nav:SetAttribute("FloorH",FH) nav:SetAttribute("AisleX",0) end end local o1=SSS:FindFirstChild("RonnieSwap") if o1 then o1:Destroy() end local o2=SPS and SPS:FindFirstChild("RonnieSwapClient") if o2 then o2:Destroy() end local roots={ReplicatedStorage=RS,ServerScriptService=SSS,StarterPlayerScripts=SPS} local installed=0 for _,e in ipairs(FILES) do local segs=string.split(e[1],"/") local parent=roots[segs[1]] for i=2,#segs-1 do local c=parent:FindFirstChild(segs[i]) if not c then c=Instance.new("Folder") c.Name=segs[i] c.Parent=parent end parent=c end local name=segs[#segs] local s=parent:FindFirstChild(name) if s and s.ClassName~=e[2] then s:Destroy() s=nil end if not s then s=Instance.new(e[2]) s.Name=name s.Parent=parent end s.Source=e[3] installed+=1 end print(("GYM WARS UPDATED: %d scripts, smoother NPC walking, wall teleporters + drop clocks, gyms at %d studs from the carpet, %d stair ramps. Press Ctrl/Cmd+S, then Play."):format(installed,LOTX,ramps)) end
